type PendingRailCommand = { offerKey: string };
const pendingRailCommands = new Map<string, PendingRailCommand>();

/** A local pending entry suppresses only a second answer to the exact live server offer. It is not game-rule
 * authority: a changed offer replaces it, a refused transport never consumes it, and server flags/dialogs decide
 * whether a command is legal. This mirrors the movement planner's offer-revision boundary. */
export function pendingRailCommandDecision(pendingOfferKey: string | null, liveOfferKey: string | null): 'allow' | 'duplicate' | 'no-live-offer' {
  if (!liveOfferKey) return 'no-live-offer';
  return pendingOfferKey === liveOfferKey ? 'duplicate' : 'allow';
}

function submitPendingRailCommand(rail: string, offerKey: string | null, command: Record<string, unknown>): boolean {
  const decision = pendingRailCommandDecision(pendingRailCommands.get(rail)?.offerKey ?? null, offerKey);
  if (decision !== 'allow' || !offerKey) {
    console.warn('[rail-dedup] dropped', rail, decision, offerKey);
    devLog('log', `[rail-dedup] dropped rail=${rail} decision=${decision} key=${offerKey ?? '(none)'}`);
    return false;
  }
  const accepted = sendCommand(command);
  // This catches two client consumers firing from ONE interaction only. It must never survive into another user
  // gesture or wait on server acknowledgement: server model/dialog/flags remain the sole action authority.
  if (accepted) {
    const pending = { offerKey };
    pendingRailCommands.set(rail, pending);
    queueMicrotask(() => {
      if (pendingRailCommands.get(rail) === pending) pendingRailCommands.delete(rail);
    });
  }
  return accepted;
}

function expirePendingRailCommandsOnServerFrame(): void {
  // Belt-and-suspenders for unusual synchronous test/headless pumps: every inbound frame ends the gesture window.
  pendingRailCommands.clear();
}

function clearPendingRailCommands(): void {
  pendingRailCommands.clear();
}
// Team action allowances remain server-owned (`blitzUsed`, `passUsed`, `foulUsed`, `handOverUsed`).
function currentTurnKey(g: GameJson): string {
  const gg = g as { half?: number; homePlaying?: boolean; turnDataHome?: { turnNr?: number }; turnDataAway?: { turnNr?: number } };
  return `${gg.half ?? 0}:${gg.turnDataHome?.turnNr ?? 0}:${gg.turnDataAway?.turnNr ?? 0}:${gg.homePlaying ? 'H' : 'A'}`;
}
