// A skillUse answer belongs to one server dialog OCCURRENCE, not to player+skill. Upstream may replace a
// consumed dialog with a second, byte-identical prompt without an intervening null frame (captured Barik/
// Blast It! flow). Object identity is the server model's occurrence boundary: repeated syncs retain the same
// object, while gameSetDialogParameter installs a new object. Keying by player+skill ate the second prompt.
let answeredSkillDialog: object | null = null;
const normSkill = (s: unknown) => String(s ?? '').toLowerCase().replace(/[^a-z]/g, '');
function skillDialogMatches(
  dialog: Record<string, unknown> | null | undefined,
  playerId: unknown,
  skill: unknown,
): dialog is Record<string, unknown> {
  return dialog?.dialogId === 'skillUse'
    && String(dialog.playerId ?? '') === String(playerId ?? '')
    && normSkill(dialog.skill) === normSkill(skill);
}
function skillDialogAnswered(dialog: unknown): boolean {
  return !!dialog && typeof dialog === 'object' && dialog === answeredSkillDialog;
}
const WATCH_OUT_SKILL = 'Watch Out!';
const WITHERGRASP_NAME = 'Withergrasp Doubledrool';
/** A Watch Out! occurrence is announced from the authoritative block declaration. The later
 * StepEndBlocking used-skill mark is retained as a reconnect/fallback signal but must not replay it. */
const watchOutAnnouncedPlayers = new Set<string>();

/** Exact star identity + exact owned rule. A user-named ordinary player must never impersonate this cue. */
function isWithergraspWatchOutPlayer(g: GameJson, playerId: string): boolean {
  const teams = [g.teamHome, g.teamAway] as {
    playerArray?: { playerId?: string; playerName?: string; playerType?: string; positionName?: string; positionId?: string | number; skillArray?: string[]; usedSkills?: string[] }[];
    roster?: { positionArray?: { positionId?: string | number; positionName?: string }[] };
  }[];
  for (const team of teams) {
    const player = team.playerArray?.find((candidate) => candidate.playerId === playerId);
    if (!player?.skillArray?.includes(WATCH_OUT_SKILL)) continue;
    const rosterName = team.roster?.positionArray?.find(
      (position) => String(position.positionId ?? '') === String(player.positionId ?? ''),
    )?.positionName;
    const positionIdentity = [player.positionName, rosterName]
      .some((name) => String(name ?? '').trim() === WITHERGRASP_NAME);
    const starPlayerIdentity = player.playerType === 'Star'
      && String(player.playerName ?? '').trim() === WITHERGRASP_NAME;
    if (positionIdentity || starPlayerIdentity) return true;
  }
  return false;
}

