/** Return the player whose authoritative Watch Out! usage changes false→true in this frame. */
function watchOutUsageTransition(g: GameJson, modelChangeList: unknown, suppressPresentation = false): string | null {
  const changes = (modelChangeList as ModelChangeListJson | null | undefined)?.modelChangeArray ?? [];
  for (const change of changes) {
    if (change.modelChangeId === ModelChangeId.PLAYER_MARK_SKILL_UNUSED
        && change.modelChangeValue === WATCH_OUT_SKILL) {
      watchOutAnnouncedPlayers.delete(String(change.modelChangeKey ?? ''));
      continue;
    }
    if (change.modelChangeId !== ModelChangeId.PLAYER_MARK_SKILL_USED
        || change.modelChangeValue !== WATCH_OUT_SKILL) continue;
    const playerId = String(change.modelChangeKey ?? '');
    if (!playerId || !isWithergraspWatchOutPlayer(g, playerId)) continue;
    const player = [...g.teamHome.playerArray, ...g.teamAway.playerArray].find((candidate) => candidate.playerId === playerId);
    if (!player?.usedSkills?.includes(WATCH_OUT_SKILL)) {
      if (suppressPresentation || watchOutAnnouncedPlayers.has(playerId)) return null;
      watchOutAnnouncedPlayers.add(playerId);
      return playerId;
    }
  }
  return null;
}

/** StepBlockRoll publishes ReportBlock before the coach chooses a die. That report is the earliest
 * authoritative proof that Watch Out! is taking effect; StepEndBlocking marks it used much later. */
function watchOutBlockDeclaration(g: GameJson, reports: readonly Record<string, unknown>[]): string | null {
  const defenderId = String(reports.find((report) => String(report.reportId) === 'block')?.defenderId ?? '');
  if (!defenderId || watchOutAnnouncedPlayers.has(defenderId)
      || !isWithergraspWatchOutPlayer(g, defenderId)) return null;
  const players = [...g.teamHome.playerArray, ...g.teamAway.playerArray];
  const defender = players.find((player) => player.playerId === defenderId);
  if (!defender || defender.usedSkills?.includes(WATCH_OUT_SKILL)) return null;
  const attackerId = String((g.actingPlayer as { playerId?: string | null } | undefined)?.playerId ?? '');
  const attackerIsHome = g.teamHome.playerArray.some((player) => player.playerId === attackerId);
  const attackerIsAway = g.teamAway.playerArray.some((player) => player.playerId === attackerId);
  const defenderIsHome = g.teamHome.playerArray.some((player) => player.playerId === defenderId);
  if (!attackerId || (!attackerIsHome && !attackerIsAway) || attackerIsHome === defenderIsHome) return null;
  watchOutAnnouncedPlayers.add(defenderId);
  return defenderId;
}
