        const c = g.fieldModel.playerDataArray.find((d) => d.playerId === id)?.playerCoordinate;
        return c && c[0] >= 0 && c[0] < 26 && c[1] >= 0 && c[1] < 15 ? [c[0], c[1]] : null;
