  state.leap = null; state.leapFail = null; leapMovesAwaitingReport.clear(); state.scatterAnim = null; state.ballCatch = null; state.deferMove = null;
  clearPassPacing(true);
  state.ttmHeld = null; state.throwAnim = null; state.trickster = null; state.passDestination = null;
  state.vampireBite = null; clearFallOver(); state.negatraitCue = null; // #132: flush the negatrait cue on a game change
  state.watchOutToast = null; // Withergrasp's transient overhead announcement never crosses a game boundary
  if (hardGameBoundary) watchOutAnnouncedPlayers.clear();
  state.sppToasts = [];
  resetCasualtySppPacing();
  state.inducementBuy = null; state.cardBuy = null;
  state.unknownCall = null; unknownDialogKey = '';
  state.weatherCine = null; state.kickoffCine = null; state.kickoffArcNeedsDecisionDwell = false;
  state.dodgySnackCine = null; state.dodgySnackAnnouncement = null; state.dodgySnackSplash = null; state.dodgySnackPlayers = [];
  state.kickoffVictimSplash = null; // #131: flush the kickoff victim-splash on a game change
  pendingKickoffTurnStartSide = null; // 647: drop a deferred turn-start so the surface-clear watch can't re-fire into a torn-down game
  state.masterChefSplash = null; // #139: flush the master-chef splash on a game change
  state.riotousRookiesSplash = null; // owner 08-17: flush the riotous-rookies splash on a game change
  state.prayerAnnounce = null; // owner 08-17 (audit P2): flush the prayer announcement on a game change
  prayerAnnounceSeq = 0;
  state.prayerChoiceWait = null;
  prayerDialogDrainArms.clear();
  state.defectors = null; // #140: flush the defector list on a game change
  state.endGameStats = null; // #169: flush the end-of-match results on a game change
  state.ballDirection = null; // #141: flush the punt/swoop direction on a game change
  state.opponentLeft = null; // #136: flush the opponent-left notice on a game change

  gazeVictimIds.clear(); state.gazeVictims = []; // owner 2026-07-08: fresh game — clear gaze-victim markers
  state.fanFactorCine = null; state.inducementReveal = null; state.apothecaryChoice = null;
  pendingApothecaryResult = null;
  clearApothecaryResult();
  if (hardGameBoundary) apothecaryAutoReturnSeen.clear();
  state.apothecaryAnim = null; state.crowdSurf = null; state.rockThrow = null; state.turnover = null;
  state.injurySplash = null; state.injuryPuff = null;
  clearRockImpactGate();
  state.grabUse = null; // #79: fresh game — drop any stale grab-icon signal
  state.blitzTokens = null; blitzActor = null; blitzActorTarget = ''; // #94: fresh game — drop blitz-token capture
  state.turnStart = null; clearRerollSplash();
  for (const t of rerollStageTimers) cancelGameTimeout(t); rerollStageTimers = []; // owner 2026-07-08: drop staged fail→reroll beats
  state.reRollPrompt = null; state.skillChoice = null; state.setupPhase = null;
  state.solidDefenceError = null; solidDefenceSelection = null; solidDefenceErrorNr = -1;
  state.sendOff = null; state.sendOffResult = null; clearSendOffWaiting(); sendOffKey = ''; sendOffAnsweredKey = null;
  // Owner 2026-07-04 interaction rails (wave 0 + 1.1): pick/yes-no/followup
  clearPlayerPick(); clearYesNo(); clearInjuryInteraction(); // Phase 3c: drop a stale injury gate
  state.followupChoice = null; state.followupIndicator = null; state.followupFlash = null;
  state.onTheBallMover = null;
  state.onTheBallWaiting = null;
  pendingFollowup = null; lastPushFrom.clear(); armourAfterFollow = null; // 08-19: drop withheld armour dice
