  for (const t of [turnoverTimer, turnoverClearTimer, weatherTimer, kickoffTimer, fanFactorTimer]) if (t) cancelGameTimeout(t);
  turnoverTimer = turnoverClearTimer = weatherTimer = kickoffTimer = fanFactorTimer = null;
