// --- M4: player session + pregame auto-advance -----------------------------
// `play.active` = we joined as a PLAYER (not a spectator). When `autoPregame` is on the store answers the pregame dialog chain itself (mirrors the drivePregame harness) so a game reaches active on-pitch play. Turn actions (Move/Block) then send real commands from the planner (M4.2+).
const play = reactive({ active: false, coach: '', autoPregame: true });
watch(
  () => [play.active, replay.active] as const,
  ([active, replayActive]) => setPresentationMode(replayActive ? 'replay' : active ? 'live' : 'spectator'),
  { immediate: true },
);

// Suppress duplicate blitz-target handling while playerBlitz owns it; reset on send, actor change, or new game.
let blitzDriving = false;
let blitzAttackerId: string | null = null; // the player playerBlitz is currently driving (for the reset above)
function swoopOccurrenceKey(g: GameJson, actingId: string, source: [number, number]): string {
  const offered = serverMoveSquares(g).map(([x, y]) => `${x},${y}`).sort().join(';');
  return `${String(g.gameId)}|${actingId}|${source[0]},${source[1]}|${offered}`;
}

// Wait for the acting-player echo before blocking; same-tick activation+block is dropped by the server.
let blockInFlight = false;
// Keep a sticky sent-push key until a fresh block prevents stale pushback arrays from re-arming.
let lastSentPushKey = '';
let blockWatchTimer: ReturnType<typeof setTimeout> | null = null;
type BlockWatchOccurrence = { id: number; attackerId: string; defenderId: string };
let blockWatchOccurrence: BlockWatchOccurrence | null = null;
let blockWatchOccurrenceSeq = 0;
let activeFoulAppearanceContext: BlockWatchOccurrence | null = null;
function clearBlockWatch() {
  if (blockWatchTimer) { cancelGameTimeout(blockWatchTimer); blockWatchTimer = null; }
  blockWatchOccurrence = null;
  activeFoulAppearanceContext = null;
  blockInFlight = false;
}

/** Resolve a Foul Appearance report against the exact pending plain-block send. The report omits defenderId;
 * use the send tuple while one is live, or the pre-apply model defender for passive/spectator formatting. */
function captureFoulAppearanceFrameContext(
  reports: readonly Record<string, unknown>[],
  defenderIdBeforeFrame: string,
): BlockWatchOccurrence | null {
  const foulAppearance = reports.find((report) => String(report.reportId ?? '') === 'foulAppearanceRoll');
  if (!foulAppearance) return null;
  const attackerId = String(foulAppearance.playerId ?? '');
  const pending = blockWatchOccurrence?.attackerId === attackerId ? blockWatchOccurrence : null;
  const active = activeFoulAppearanceContext?.attackerId === attackerId ? activeFoulAppearanceContext : null;
  const defenderId = String(foulAppearance.defenderId ?? pending?.defenderId ?? active?.defenderId ?? defenderIdBeforeFrame ?? '');
  const context = defenderId
    ? { ...(pending ?? active ?? { id: 0, attackerId, defenderId }), defenderId }
    : null;
  if (foulAppearance.successful === false && pending) {
    // Expected non-registration: StepFoulAppearance owns the block occurrence until reroll/activation teardown.
    // Cancel only this timer; a later send receives a new occurrence id and a fresh watchdog.
    if (blockWatchTimer) { cancelGameTimeout(blockWatchTimer); blockWatchTimer = null; }
    blockWatchOccurrence = null;
    blockInFlight = false;
    activeFoulAppearanceContext = pending;
  }
  return context;
}
// Track acting-player acknowledgements at receive time so presentation lag cannot delay commands.
let srvActingId: string | null = null;
let srvActingAction: string | null = null;
type WideRailDeclareCorrelation = {
  playerId: string;
  requestedPlayerAction: string;
  playerAction: string;
  seq: number;
};
type PendingWideRailDeclare = WideRailDeclareCorrelation & { sawPlayerIdEcho: boolean; sawPlayerActionEcho: boolean };
let pendingWideRailDeclare: PendingWideRailDeclare | null = null;
let acknowledgedWideRailDeclare: WideRailDeclareCorrelation | null = null;
let completedWideRailDeclare: WideRailDeclareCorrelation | null = null;
let wideRailDeclareSeq = 0;
type DeferredStandUpWideRail = {
  playerId: string;
  playerAction: 'standUp';
  seq: number;
  stage: 'electing' | 'awaitingActor' | 'resolving';
  options: WideRailActivationOption[];
  selectedRuleId: WideRailPreActionRuleId | null;
  authoritativeFramesAfterUse: number;
};
let deferredStandUpWideRail: DeferredStandUpWideRail | null = null;
type ShotToNothingCorrelation = { playerId: string; playerAction: 'passMove'; seq: number };
type PendingShotToNothingCorrelation = ShotToNothingCorrelation & { sawPlayerIdEcho: boolean; sawPlayerActionEcho: boolean };
let pendingShotToNothingDeclare: PendingShotToNothingCorrelation | null = null;
let acknowledgedShotToNothingDeclare: ShotToNothingCorrelation | null = null;
let shotToNothingDeclareSeq = 0;
const WIDE_RAIL_RULE_IDS = new Set<string>(WIDE_RAIL_PRE_ACTION_RULES.map((rule) => rule.ruleId));
function localWideRailSessionActive(): boolean {
  return !!pendingWideRailDeclare || !!acknowledgedWideRailDeclare || !!completedWideRailDeclare
    || !!deferredStandUpWideRail;
}

function standUpWideRailOptions(g: GameJson, playerId: string): WideRailActivationOption[] {
  // Upstream advertises these rows from the transient Move state after stand-up. Project that exact post-stand
  // state before sending the terminal action; every server sequence still revalidates its own targets and skill.
  const actorData = g.fieldModel.playerDataArray.find((data) => data.playerId === playerId);
  const actorCoordinate = actorData?.playerCoordinate;
  const ownIds = new Set(
    (g.teamHome.playerArray.some((player) => player.playerId === playerId)
      ? g.teamHome.playerArray : g.teamAway.playerArray).map((player) => player.playerId),
  );
  const initialAdjacentPartnerIds = Array.isArray(actorCoordinate)
    ? g.fieldModel.playerDataArray.filter((data) => {
        const coordinate = data.playerCoordinate;
        return data.playerId !== playerId && ownIds.has(data.playerId) && Array.isArray(coordinate)
          && Math.max(Math.abs(coordinate[0] - actorCoordinate[0]), Math.abs(coordinate[1] - actorCoordinate[1])) === 1;
      }).map((data) => data.playerId)
    : [];
  const projected = {
    ...g,
    fieldModel: {
      ...g.fieldModel,
      playerDataArray: g.fieldModel.playerDataArray.map((data) => data.playerId === playerId
        ? { ...data, playerState: (Number(data.playerState ?? 0) & ~0xff) | PlayerStateBase.STANDING | PlayerStateFlag.ACTIVE }
        : data),
    },
    actingPlayer: {
      ...(g.actingPlayer ?? {}),
      playerId,
      playerAction: 'standUp',
      playerStateOld: actorData?.playerState ?? null,
      standingUp: true,
      currentMove: 3,
      initialAdjacentPartnerIds,
      hasMoved: false,
      hasFouled: false,
      hasBlocked: false,
      hasPassed: false,
      hasTriggeredEffect: false,
      forgone: false,
      usedSkills: [],
    },
  } as GameJson;
  return wideRailActivationOptions(projected, playerId, 'standUp');
}

function sendDeferredStandUp(continuation: DeferredStandUpWideRail): boolean {
  const accepted = sendCommand({
    netCommandId: NetCommandId.CLIENT_ACTING_PLAYER,
    playerId: continuation.playerId,
    playerAction: continuation.playerAction,
    leaping: false,
  });
  if (accepted && deferredStandUpWideRail?.seq === continuation.seq) {
    deferredStandUpWideRail = null;
    log('system', `play: DECLARE standUp ${playerName(game.value, continuation.playerId)} (after special action)`);
  }
  return accepted;
}

function advanceDeferredStandUpWideRail(): void {
  const continuation = deferredStandUpWideRail;
  const g = game.value;
  if (!continuation || !g || !play.active || !iControlPlayer(continuation.playerId)) return;
  const actingId = String(g.actingPlayer?.playerId ?? '');
  const actingAction = String(g.actingPlayer?.playerAction ?? '');
  if (continuation.stage === 'awaitingActor') {
    if (actingId !== continuation.playerId || actingAction) return;
    const ruleId = continuation.selectedRuleId;
    if (!ruleId) return;
    const rule = wideRailPreActionRule(ruleId);
    let command: Record<string, unknown> | null = null;
    if (rule.mode === 'wisdom') {
      command = { netCommandId: NetCommandId.CLIENT_USE_TEAM_MATES_WISDOM };
    } else if (rule.mode === 'toggle' && rule.skill) {
      command = {
        netCommandId: NetCommandId.CLIENT_USE_SKILL,
        skill: rule.skill,
        skillUsed: !incorporealIsActive(g, continuation.playerId),
        playerId: continuation.playerId,
      };
    } else if (rule.skill) {
      command = {
        netCommandId: NetCommandId.CLIENT_USE_SKILL,
        skill: rule.skill,
        skillUsed: true,
        playerId: continuation.playerId,
      };
    }
    if (!command) return;
    const accepted = sendCommand(command);
    if (accepted && deferredStandUpWideRail?.seq === continuation.seq) {
      deferredStandUpWideRail = {
        ...continuation,
        stage: 'resolving',
        authoritativeFramesAfterUse: 0,
      };
      log('system', `play: ${rule.label.toUpperCase()} (before Stand up and End Activation)`);
    }
    return;
  }
  if (continuation.stage !== 'resolving') return;
  const frames = continuation.authoritativeFramesAfterUse + 1;
  deferredStandUpWideRail = { ...continuation, authoritativeFramesAfterUse: frames };
  // Every force-dispatched special runs above a fresh Select sequence. A client-input sequence exposes a dialog
  // or non-regular turnMode; an automatic/toggle sequence completes within the authoritative response. Resume
  // only once the model has returned to the staged actor/null-action Select tuple on a later server frame.
  if (frames >= 1 && String(g.turnMode ?? '') === 'regular'
      && !g.dialogParameter && actingId === continuation.playerId && !actingAction) {
    sendDeferredStandUp(continuation);
  }
}

const PLAN_RESOLUTION_REPORT: Record<string, PlanResolution> = {
  goForItRoll: 'gfi', dodgeRoll: 'dodge', pickUpRoll: 'pickup',
};

/** Release only the oldest matching roll-boundary occurrence. A square can own Dodge, Rush and Pick Up in
 * sequence, so the visual edge stays closed until every required successful report has arrived. */
function settleMovementRollPresentation(reports: readonly Record<string, unknown>[]): void {
  if (playback.catchingUp) return;
  for (const report of reports) {
    if (report.successful !== true) continue;
    const resolution = PLAN_RESOLUTION_REPORT[String(report.reportId ?? '')];
    const playerId = String(report.playerId ?? '');
    if (!resolution || !playerId) continue;
    const active = presentation.presenting;
    if (active?.kind === 'rollBeat' && active.id === playerId && active.pendingRolls?.has(resolution)) {
      active.pendingRolls.delete(resolution);
      if (active.pendingRolls.size === 0) active.release();
      continue;
    }
    const queued = presentation.queue.find((event): event is Extract<PresentationEvent, { kind: 'step' }> =>
      event.kind === 'step' && event.playerId === playerId && event.rollRequirements.has(resolution));
    queued?.rollRequirements.delete(resolution);
  }
}
function reconcileWideRailDeclarationEcho() {
  if (pendingWideRailDeclare
      && pendingWideRailDeclare.sawPlayerIdEcho
      && pendingWideRailDeclare.sawPlayerActionEcho
      && srvActingId === pendingWideRailDeclare.playerId
      && srvActingAction === pendingWideRailDeclare.playerAction) {
    acknowledgedWideRailDeclare = pendingWideRailDeclare;
    pendingWideRailDeclare = null;
    return;
  }
  if (!pendingWideRailDeclare && acknowledgedWideRailDeclare
      && (srvActingId !== acknowledgedWideRailDeclare.playerId
        || srvActingAction !== acknowledgedWideRailDeclare.playerAction)) {
    acknowledgedWideRailDeclare = null;
  }
  if (!pendingWideRailDeclare && !acknowledgedWideRailDeclare && completedWideRailDeclare
      && (srvActingId !== completedWideRailDeclare.playerId
        || srvActingAction !== completedWideRailDeclare.playerAction)) {
    completedWideRailDeclare = null;
  }
}

function clearShotToNothingElection(): void {
  pendingShotToNothingDeclare = null;
  acknowledgedShotToNothingDeclare = null;
  if (state.skillChoice?.origin === 'shotToNothing') state.skillChoice = null;
}

function shotToNothingElectionStillLive(correlation: ShotToNothingCorrelation): boolean {
  const g = game.value;
  return !!g && play.active && iControlPlayer(correlation.playerId)
    && acknowledgedShotToNothingDeclare?.seq === correlation.seq
    && srvActingId === correlation.playerId
    && srvActingAction === correlation.playerAction
    && hasUnusedSkillNamed(g, correlation.playerId, 'Shot to Nothing');
}

function reconcileShotToNothingDeclarationEcho(): void {
  const pending = pendingShotToNothingDeclare;
  if (pending && pending.sawPlayerIdEcho && pending.sawPlayerActionEcho
      && srvActingId === pending.playerId && srvActingAction === pending.playerAction) {
    pendingShotToNothingDeclare = null;
    acknowledgedShotToNothingDeclare = pending;
    if (interactiveReRolls && shotToNothingElectionStillLive(pending)) {
      state.skillChoice = {
        playerId: pending.playerId,
        skill: 'Shot to Nothing',
        label: 'Shot to Nothing',
        minimumRoll: 0,
        mine: true,
        seq: (state.skillChoice?.seq ?? 0) + 1,
        origin: 'shotToNothing',
        declarationSeq: pending.seq,
      };
    } else acknowledgedShotToNothingDeclare = null;
    return;
  }
  const armed = acknowledgedShotToNothingDeclare;
  if (armed && (srvActingId !== armed.playerId || srvActingAction !== armed.playerAction)) {
    clearShotToNothingElection();
  }
}

function trackActingPlayer(cmd: Record<string, unknown>) {
  const arr = (cmd.modelChangeList as { modelChangeArray?: { modelChangeId?: string; modelChangeValue?: unknown }[] } | undefined)?.modelChangeArray;
  if (!arr) return;
  let explicitPlayerId = false;
  let explicitPlayerIdNonNull = false;
  let explicitPlayerAction = false;
  let explicitPlayerActionNonNull = false;
  let terminalBoundary = false;
  for (const ch of arr) {
    if (ch.modelChangeId === 'actingPlayerSetPlayerId') {
      explicitPlayerId = true;
      explicitPlayerIdNonNull = ch.modelChangeValue != null;
      srvActingId = (ch.modelChangeValue as string | null) ?? null;
      if (pendingWideRailDeclare && srvActingId === pendingWideRailDeclare.playerId) {
        pendingWideRailDeclare.sawPlayerIdEcho = true;
      }
      if (pendingShotToNothingDeclare && srvActingId === pendingShotToNothingDeclare.playerId) {
        pendingShotToNothingDeclare.sawPlayerIdEcho = true;
      }
    } else if (ch.modelChangeId === 'actingPlayerSetPlayerAction') {
      explicitPlayerAction = true;
      explicitPlayerActionNonNull = ch.modelChangeValue != null;
      srvActingAction = (ch.modelChangeValue as string | null) ?? null;
      if (pendingWideRailDeclare && srvActingAction === pendingWideRailDeclare.playerAction) {
        pendingWideRailDeclare.sawPlayerActionEcho = true;
      }
      if (pendingShotToNothingDeclare && srvActingAction === pendingShotToNothingDeclare.playerAction) {
        pendingShotToNothingDeclare.sawPlayerActionEcho = true;
      }
    } else if (ch.modelChangeId === 'gameSetHomePlaying'
        || ch.modelChangeId === 'turnDataSetTurnNr'
        || ch.modelChangeId === 'gameSetHalf'
        || (ch.modelChangeId === 'gameSetTurnMode'
          && ['betweenTurns', 'setup', 'kickoff', 'endGame'].includes(String(ch.modelChangeValue ?? '')))) {
      terminalBoundary = true;
    }
  }
  const reports = (cmd.reportList as { reports?: { reportId?: string }[] } | undefined)?.reports ?? [];
  if (reports.some((report) => ['turnEnd', 'endGame', 'startHalf'].includes(String(report.reportId ?? '')))) {
    terminalBoundary = true;
  }
  // Evaluate the whole received command, never an intermediate CLEAR within it. Nulls are deliberately
  // inconclusive because upstream may publish CLEAR and the replacement tuple in separate frames. A coherent
  // non-null foreign tuple is a real rejection/supersession and releases only the pending client election.
  if (terminalBoundary) {
    pendingWideRailDeclare = null;
    acknowledgedWideRailDeclare = null;
    completedWideRailDeclare = null;
    deferredStandUpWideRail = null;
    clearShotToNothingElection();
  } else if (pendingWideRailDeclare && explicitPlayerId && explicitPlayerIdNonNull
      && srvActingId !== pendingWideRailDeclare.playerId) {
    pendingWideRailDeclare = null;
  } else if (pendingWideRailDeclare && srvActingId === pendingWideRailDeclare.playerId
      && explicitPlayerAction && explicitPlayerActionNonNull
      && srvActingAction !== pendingWideRailDeclare.playerAction) {
    pendingWideRailDeclare = null;
  }
  if (pendingShotToNothingDeclare && explicitPlayerId && explicitPlayerIdNonNull
      && srvActingId !== pendingShotToNothingDeclare.playerId) {
    clearShotToNothingElection();
  } else if (pendingShotToNothingDeclare && srvActingId === pendingShotToNothingDeclare.playerId
      && explicitPlayerAction && explicitPlayerActionNonNull
      && srvActingAction !== pendingShotToNothingDeclare.playerAction) {
    clearShotToNothingElection();
  }
  // A foreign activation can legitimately CLEAR before whenPriorActivationEnded sends and arms the requested
  // declaration. Once armed, only an exact tuple acknowledges it; coherent mismatches above reject it.
  reconcileWideRailDeclarationEcho();
  reconcileShotToNothingDeclarationEcho();
  // Voss review batch: event-gated blitz-guard reset. If the server now has a DIFFERENT player acting than the one we're blitz-driving, that blitz is over/abandoned — drop the guard so a fresh selectBlitzTarget prompt isn't swallowed. (srvActingId momentarily null mid CLEAR-then-SET swap is fine — we only clear on a concrete different player.)
  if (blitzDriving && blitzAttackerId && srvActingId && srvActingId !== blitzAttackerId) {
    blitzDriving = false; blitzAttackerId = null;
  }
}
/** Seed the receive-time acting mirror from full gameState snapshots for first action and reconnect. */
function seedActingPlayer(g: GameJson | null | undefined) {
  const ap = g?.actingPlayer as { playerId?: string | null; playerAction?: string | null } | undefined;
  srvActingId = ap?.playerId ?? null;
  srvActingAction = ap?.playerAction ?? null;
  pendingWideRailDeclare = null;
  acknowledgedWideRailDeclare = null;
  completedWideRailDeclare = null;
  deferredStandUpWideRail = null;
  clearShotToNothingElection();
  if (g && play.active && interactiveReRolls && srvActingId && srvActingAction === 'passMove'
      && !g.dialogParameter && iControlPlayer(srvActingId)
      && hasUnusedSkillNamed(g, srvActingId, 'Shot to Nothing')) {
    const correlation: ShotToNothingCorrelation = {
      playerId: srvActingId,
      playerAction: 'passMove',
      seq: ++shotToNothingDeclareSeq,
    };
    acknowledgedShotToNothingDeclare = correlation;
    state.skillChoice = {
      playerId: correlation.playerId,
      skill: 'Shot to Nothing',
      label: 'Shot to Nothing',
      minimumRoll: 0,
      mine: true,
      seq: (state.skillChoice?.seq ?? 0) + 1,
      origin: 'shotToNothing',
      declarationSeq: correlation.seq,
    };
  }
  if (g) observeModelShadow(g);
}
/** Pure property-map projection guarded by the exact locally requested declaration echo. Reconnect uses the
 * canonical action-context rows; an arbitrary snapshot must not recreate this client-owned election. */
function receivedWideRailActivationOptions(g: GameJson, playerId: string, playerAction: string) {
  if (acknowledgedWideRailDeclare?.playerId !== playerId
      || acknowledgedWideRailDeclare.playerAction !== playerAction) return [];
  return wideRailActivationOptions(g, playerId, playerAction);
}
/** Fire `cb` as soon as the SERVER has confirmed our activation — the last inbound frame set the acting player to `id` with action `action` (read at RECEIVE time via srvActingId/Action, so it's ~10ms not ~900ms). The action check guards the CLEAR-then-SET swap (wire: PlayerId=null → PlayerId=<new> → PlayerAction, one frame). Paced fallback after `maxWaitMs` so a missed sync degrades to a delayed send, never wedges (the drop watchdog then surfaces it). */
function whenActingPlayerAcked(id: string, action: string, cb: (acked: boolean) => void, maxWaitMs = 900) {
  const start = Date.now();
  const tick = () => {
    const acked = srvActingId === id && srvActingAction === action;
    if (acked) { cb(true); return; }
    if (Date.now() - start >= maxWaitMs) { cb(false); return; } // fallback: BLIND-FIRE — the caller warns
    scheduleGameTimeout(tick, 20);
  };
  tick(); // check immediately — the ack often landed before the send round-trips back to us
}
/** Owner 09-09: the presentation-paced MODEL can trail the receive-time mirror (a kickoff drain queues the declare
 *  echo); senders that validate against the model wait here for it to catch up (20 ms polls, bounded). */
function whenModelShowsActing(id: string, cb: (ready: boolean) => void, maxWaitMs = 1500) {
  const start = Date.now();
  const tick = () => {
    const acting = (game.value?.actingPlayer ?? {}) as { playerId?: string | null };
    if (acting.playerId === id) { cb(true); return; }
    if (Date.now() - start >= maxWaitMs) { cb(false); return; }
    scheduleGameTimeout(tick, 20);
  };
  tick();
}
/** On blind-fired non-block actions, warn only if the acting-player acknowledgement still never arrives. */
function watchActivationTook(playerId: string, label: string) {
  scheduleGameTimeout(() => {
    if (srvActingId === playerId) return; // the activation landed after all — nothing dropped
    const g = game.value; if (!g) return;
    const text = `⚠ ${label} may not have registered — the server never confirmed ${playerName(g, playerId)}'s activation. Re-select the player and try again.`;
    log('system', text);
    state.actionNotice = { text, seq: (state.actionNotice?.seq ?? 0) + 1 };
  }, 700);
}
// End the prior moving activation before a plain block; StepInitMoving accepts CLIENT_BLOCK only for Blitz.
function whenPriorActivationEnded(attackerId: string, cb: () => void, maxWaitMs = 900) {
  // Clean state (no live activation) or re-declaring on the SAME player → nothing to end, go now.
  if (srvActingId == null || srvActingId === attackerId) { cb(); return; }
  sendCommand({ netCommandId: NetCommandId.CLIENT_ACTING_PLAYER, playerId: null, playerAction: null, leaping: isJumping() });
  const start = Date.now();
  const tick = () => {
    if (srvActingId == null || Date.now() - start >= maxWaitMs) { cb(); return; }
    scheduleGameTimeout(tick, 20);
  };
  tick();
}

/** Wait for an already-sent cancellation/refund to clear the receive-time actor. Unlike
 * whenPriorActivationEnded this never sends a second generic cancel and never fires on timeout. */
function afterActivationCleared(cb: () => void, maxWaitMs = 1500) {
  const start = Date.now();
  const tick = () => {
    if (srvActingId == null) { cb(); return; }
    if (Date.now() - start >= maxWaitMs) return;
    scheduleGameTimeout(tick, 20);
  };
  tick();
}
function blitzEndConfirmationRequired(g: GameJson): boolean {
  const turnMode = String(g.turnMode ?? '');
  const playerAction = String((g.actingPlayer as { playerAction?: string | null } | undefined)?.playerAction ?? '');
  return turnMode === 'selectBlitzTarget' || /blitz/i.test(playerAction);
}
let friendlySwitchRequestSeq = 0;
/** After a block is sent, watch for the server accepting it (a `block`/`blockRoll` report calls clearBlockWatch in handleReports). If none lands, the server dropped the command — toast the likely reason and release the debounce so a genuine retry is allowed. */
function watchBlockAccepted(attackerId: string, defenderId: string) {
  if (blockWatchTimer) cancelGameTimeout(blockWatchTimer);
  activeFoulAppearanceContext = null;
  const occurrence: BlockWatchOccurrence = { id: ++blockWatchOccurrenceSeq, attackerId, defenderId };
  blockWatchOccurrence = occurrence;
  blockWatchTimer = scheduleGameTimeout(() => {
    if (blockWatchOccurrence?.id !== occurrence.id) return;
    blockWatchTimer = null;
    blockWatchOccurrence = null;
    blockInFlight = false; // release the debounce — the coach may legitimately retry now
    const g = game.value; if (!g) return;
    const ap = (g.actingPlayer as { playerId?: string } | undefined)?.playerId ?? null;
    const reason = !ap
      ? "the server hasn't accepted this player's activation yet"
      : ap !== attackerId
        ? `it's a different player's activation (${playerName(g, ap)})`
        : 'the server rejected it (already acted this turn, or the target moved out of reach)';
    const text = `⚠ Block not registered — ${reason}. Re-select the player and try the block again.`;
    log('system', text);
    state.actionNotice = { text, seq: (state.actionNotice?.seq ?? 0) + 1 };
  }, 1500);
}

type ThrowMateCommandTarget = { thrownPlayerId: string } | { targetCoordinate: [number, number] };

/** BB2025 ClientCommandThrowTeamMate.java:68-75: TTM and KTM share this wire; `kicked` selects the skill path. */
export function throwMateCommand(
  actingPlayerId: string,
  target: ThrowMateCommandTarget,
  kicked: boolean,
): Record<string, unknown> {
  return { netCommandId: NetCommandId.CLIENT_THROW_TEAM_MATE, actingPlayerId, ...target, kicked };
}

// Planner advances from server model echoes, sends one square at a time, and fires the terminal action only after required outcomes resolve.
type PlanActKind = 'pass' | 'foul' | 'handOver' | 'throwTeamMate' | 'kickTeamMate' | 'block' | 'blitz' | 'move' | 'blitzWalk';
interface PlannerPlan {
  seq: number;
  playerId: string;
  actKind: PlanActKind;
  moving: boolean;                              // route non-empty (else a 0-waypoint declare→act plan)
  declare: string;                             // moving ? passMove/foulMove/handOverMove : pass/foul/handOver
  declareOnly: boolean;
  route: [number, number][];                   // waypoints, excludes the start square
  sentIdx: number;                             // #76: index of the last route square SENT (per-square walk); -1 before the walk starts
  squareResolutions: Set<PlanResolution>[];    // #104: per-route-square flagged rolls (index i = the roll owed by the step INTO route[i]); each resolves on its own sync
  /** A successful re-roll can return the server to move selection without applying the attempted coordinate.
   *  In that exact case the same still-offered destination must be sent once more before the route can continue. */
  retryResolvedIdx: number | null;
  /** Exact target-add occurrence consumed by each sent edge. A same-origin reroll retry must consume a newer
   *  server republish of that target, never the surviving entry from the prior roll generation. */
  sentOfferRevisions: number[];
  targetCoordinate: [number, number] | null;   // pass target square
  targetPlayerId: string | null;               // foul (defender) / hand-off (catcher)
  blockKind: string | null;                    // #34: a BLITZ's optional special block-kind (stab/chainsaw/vomit/breatheFire/chomp) — rides sendBlock's flavor flags
  blockChoiceResolved: boolean;
  goredCommit: boolean;
  terminalSent: boolean;
  phase: 'declaring' | 'moving' | 'acting';
  turnKey: string;                             // flush if the turn changes under us
  onTheBallMode: 'kickoffReturn' | 'passBlock' | null; // W27: admits only the OtB plan that started in this exact window
}
/** #34: BLITZ optional special block-kind → sendBlock flavor flags (store-side mirror of SpectateView's o66BlockFlags); null/undefined ⇒ PLAIN block (byte-identical to pre-#34). */
/** #113 (JC-3/JC-4): SINGLE source of truth for acting player's jump state; reads SERVER's echoed actingPlayer.leaping (ModelChangeId.ACTING_PLAYER_SET_JUMPING), NOT local latch; ONE derivation via CLIENT_ACTING_PLAYER's leaping:isJumping(), never re-hardcoded false; defaults false → byte-identical to old hardcode until jump toggled. */
function isJumping(): boolean {
  return !!(game.value?.actingPlayer as { leaping?: boolean } | undefined)?.leaping;
}

function blockFlagsFromKind(kind: string | null | undefined):
  { usingStab: boolean; usingChainsaw: boolean; usingVomit: boolean; usingBreatheFire: boolean; usingChomp: boolean } | undefined {
  return kind
    ? { usingStab: kind === 'stab', usingChainsaw: kind === 'chainsaw', usingVomit: kind === 'vomit', usingBreatheFire: kind === 'breatheFire', usingChomp: kind === 'chomp' }
    : undefined;
}
/** Owner ruling 08-05 (verbatim): "The block chooser should only surface for Chainsaw, the rest of the family can
 *  live on the context menu." This is an owner-UX-ruled presentation deviation from upstream/master: [SOURCE]
 *  `ffb-client-logic/.../BlockLogicExtension.java:95-100,189-194` forces its chooser-equivalent for all
 *  `providesBlockAlternative` flavors. The wire remains upstream-shaped through the two existing clientBlock
 *  shapes: a plain click sends all using* flags false; an explicit context-menu pick sends its using* flag true. */
const CHOOSER_FLAVORS = new Set<string>([
  'chainsaw',
  // Owner ruling 08-05: chooser surfaces for Chainsaw only; the rest live on the context menu.
  // Re-enable any flavor by uncommenting its line — the chooser machinery still handles all five.
  // 'stab',
  // 'vomit',
  // 'breatheFire',
  // 'chomp',
]);
function blockChooserOffers(g: GameJson, playerId: string) {
  return blockAlternativeOffers(g, playerId).filter((offer) => CHOOSER_FLAVORS.has(offer.kind));
}
// Star S5: 'gored' is NOT a BlockKind flavor — no using* flag exists for it. It commits as CLIENT_USE_SKILL
// (Gored By The Bull, used) then a PLAIN clientBlock, so it rides the chooser card as its own offer kind.
const GORED_OFFER_KIND = 'gored';
/** Blitz-commit chooser offers: the flavor offers plus the Gored by the Bull alternative when the server's
 *  decorations carry it (upstream surfaces Gored only at the blitz block window — isGoredAvailable && pDoBlitz). */
function blitzBlockCommitOffers(g: GameJson, blitzerId: string, targetId: string): { kind: string; label: string }[] {
  const offers: { kind: string; label: string }[] = blockChooserOffers(g, blitzerId);
  if (goredByTheBullAvailable(g, blitzerId, targetId)) offers.push({ kind: GORED_OFFER_KIND, label: 'Gored by the Bull' });
  return offers;
}
/** Blitz-commit hold (planner act leg + test seam): arm the chooser card when there is anything to choose. */
function holdBlitzBlockChoice(blitzerId: string, targetId: string): boolean {
  const offers = game.value ? blitzBlockCommitOffers(game.value, blitzerId, targetId) : [];
  if (offers.length >= 1 && !state.blitzBlockChoice) {
    state.blitzBlockChoice = { blitzerId, targetId, offers, origin: 'blitz' };
    return true;
  }
  return false;
}
// leg-2a (Echo per-touch hardening, 07-15): SINGLE entered final square carries MULTIPLE resolutions each on OWN sync (Move.java: GO_FOR_IT→MOVE_DODGE→PICK_UP each with own report); fix: enumerate final square's flagged rolls from moveSquareInfo + ball-on-final, require EACH outcome report before firing; any FAILING roll knocks prone or opens dialog, so all-resolved+standing+no-dialog ⇒ safe to fire.
function plannerSquareResolutions(g: GameJson, square: [number, number]): Set<PlanResolution> {
  return movementRollResolutions(g, plannerActingId(), square);
}
type MoveOfferOccurrence = {
  gameId: string;
  playerId: string;
  origin: [number, number];
  action: string;
  target: [number, number];
  minimumRollDodge: number;
  minimumRollGfi: number;
  revision: number;
};
let moveOfferRevision = 0;
const moveOfferOccurrences = new Map<string, MoveOfferOccurrence>();

function currentGameId(): string {
  return String((game.value as { gameId?: string | number } | null)?.gameId ?? '');
}

function moveOfferTargetKey(target: [number, number]): string {
  return `${target[0]},${target[1]}`;
}

function currentMoveAction(): string {
  return String((game.value?.actingPlayer as { playerAction?: string | null } | undefined)?.playerAction ?? '');
}

function recordMoveOffer(
  playerId: string,
  origin: [number, number],
  target: [number, number],
  minimumRollDodge = 0,
  minimumRollGfi = 0,
): MoveOfferOccurrence {
  const occurrence: MoveOfferOccurrence = {
    gameId: currentGameId(), playerId,
    origin: [origin[0], origin[1]], action: currentMoveAction(),
    target: [target[0], target[1]],
    minimumRollDodge: Number(minimumRollDodge) || 0,
    minimumRollGfi: Number(minimumRollGfi) || 0,
    revision: ++moveOfferRevision,
  };
  moveOfferOccurrences.set(moveOfferTargetKey(target), occurrence);
  return occurrence;
}

/** Track target-level server occurrences from the real applied model-change list. A remove never certifies the
 * survivors of an old generation; only an explicit Add for this target can authorize a later send. */
function observeMoveOfferGeneration(cmd: Record<string, unknown>): void {
  const changes = (cmd.modelChangeList as { modelChangeArray?: {
    modelChangeId?: unknown;
    modelChangeValue?: { coordinate?: unknown; minimumRollDodge?: unknown; minimumRollGfi?: unknown };
  }[] } | undefined)?.modelChangeArray ?? [];
  if (!changes.some((change) => {
    const id = String(change.modelChangeId ?? '');
    return id === 'fieldModelAddMoveSquare' || id === 'fieldModelRemoveMoveSquare';
  })) return;
  const playerId = plannerActingId();
  const coordinate = playerId ? plannerCoord(playerId) : null;
  for (const change of changes) {
    const id = String(change.modelChangeId ?? '');
    const raw = change.modelChangeValue?.coordinate;
    if (!Array.isArray(raw) || raw.length < 2) continue;
    const target: [number, number] = [Number(raw[0]), Number(raw[1])];
    const key = moveOfferTargetKey(target);
    if (id === 'fieldModelRemoveMoveSquare') {
      moveOfferOccurrences.delete(key);
    } else if (id === 'fieldModelAddMoveSquare' && playerId && coordinate) {
      recordMoveOffer(
        playerId, coordinate, target,
        Number(change.modelChangeValue?.minimumRollDodge ?? 0),
        Number(change.modelChangeValue?.minimumRollGfi ?? 0),
      );
    }
  }
}

/** Full GameState/reconnect snapshots contain a coherent current offer set but no add-model-change history. Seed
 * exactly at that trusted boundary (and in isolated production test harness setup), never during reroll retry. */
function seedMoveOfferSnapshot(playerId = plannerActingId()): void {
  moveOfferOccurrences.clear();
  const coordinate = plannerCoord(playerId);
  if (!playerId || !coordinate || plannerActingId() !== playerId) return;
  const snapshotSquares = (game.value?.fieldModel.moveSquareArray ?? []) as {
    coordinate?: [number, number]; minimumRollDodge?: number; minimumRollGfi?: number;
  }[];
  for (const square of snapshotSquares) {
    const target = square.coordinate as [number, number] | undefined;
    if (!target) continue;
    recordMoveOffer(
      playerId, coordinate, target,
      Number((square as { minimumRollDodge?: number }).minimumRollDodge ?? 0),
      Number((square as { minimumRollGfi?: number }).minimumRollGfi ?? 0),
    );
  }
}

function currentMoveOffer(
  playerId: string,
  target: [number, number],
  minimumRevisionExclusive = -1,
): MoveOfferOccurrence | null {
  const coordinate = plannerCoord(playerId);
  const occurrence = moveOfferOccurrences.get(moveOfferTargetKey(target));
  return coordinate && occurrence
    && occurrence.gameId === currentGameId()
    && occurrence.playerId === playerId
    && occurrence.origin[0] === coordinate[0] && occurrence.origin[1] === coordinate[1]
    && occurrence.action === currentMoveAction()
    && occurrence.revision > minimumRevisionExclusive
      ? occurrence : null;
}
let plannerPlan: PlannerPlan | null = null;
let plannerSeq = 0;
let answeredDialogInstanceKey: string | null = null;
// The shared key separates dialog kinds/modes; object identity separates a byte-identical replacement
// occurrence while the previous server dialog is still parked in the raw model.
let answeredDialogInstanceRef: object | null = null;
let plannerAbortTimer: ReturnType<typeof setTimeout> | null = null;
const PLANNER_ABORT_MS = 8000;                  // ABORT-ONLY watchdog: cancels a stuck plan, never advances a leg
function plannerActive(): boolean { return plannerPlan != null; }
function plannerSet(next: PlannerPlan | null): void {
  if (plannerPlan === next) return;
  plannerPlan = next;
  state.plannerRevision += 1;
}
function plannerArmAbort() {
  if (plannerAbortTimer) cancelGameTimeout(plannerAbortTimer);
  plannerAbortTimer = scheduleGameTimeout(() => {
    plannerAbortTimer = null;
    // An owned decision prompt re-arms the planner watchdog; it is not a server timeout.
    if (plannerPlan && plannerPromptPending()) { plannerArmAbort(); return; }
    plannerFlush('the server did not respond');
  }, PLANNER_ABORT_MS);
}
function plannerClearAbort() { if (plannerAbortTimer) { cancelGameTimeout(plannerAbortTimer); plannerAbortTimer = null; } }
function plannerFlush(reason: string) {
  if (!plannerPlan) return;
  plannerSet(null); plannerClearAbort();
  if (state.yesNo?.key.startsWith('starCommit:')) clearYesNo();
  state.blitzBlockChoice = null; // #111 fail-safe: a held block-choice dies with its plan (turn-end/knockdown/etc.) — never a stale hold
  const text = `Plan cancelled — ${reason}.`;
  log('system', `⚠ ${text}`);
  state.actionNotice = { text, seq: (state.actionNotice?.seq ?? 0) + 1 };
}
function plannerPData(pid: string) { return game.value?.fieldModel.playerDataArray.find((d) => d.playerId === pid); }
function plannerBase(pid: string): number | null { const d = plannerPData(pid); return d ? (playerStateBase(d.playerState) ?? 0) : null; }
function plannerCoord(pid: string): [number, number] | null { const c = plannerPData(pid)?.playerCoordinate as [number, number] | undefined; return c ? [c[0], c[1]] : null; }
function plannerActingId(): string { return String((game.value?.actingPlayer as { playerId?: string | null } | undefined)?.playerId ?? ''); }
function plannerActingAction(): string { return String((game.value?.actingPlayer as { playerAction?: string | null } | undefined)?.playerAction ?? ''); }
function clearAnsweredDialogInstance(): void {
  answeredDialogInstanceKey = null;
  answeredDialogInstanceRef = null;
}
function latchAnsweredDialogInstance(key: string | null, instance: object | null = null): void {
  answeredDialogInstanceKey = key;
  answeredDialogInstanceRef = key ? instance : null;
}
function dialogAlreadyAnswered(): boolean {
  if (!answeredDialogInstanceKey) return false;
  const live = game.value?.dialogParameter as object | null | undefined;
  if (!live || !dialogInstanceLive(answeredDialogInstanceKey)
    || (answeredDialogInstanceRef !== null && live !== answeredDialogInstanceRef)) {
    clearAnsweredDialogInstance();
    return false;
  }
  return true;
}
/** Send an answer, then hide only that exact still-live dialog occurrence from subsequent outgoing rails. */
function sendAnsweredDialogCommand(
  command: Record<string, unknown>,
  expectedKey: string | null,
  expectedInstance: object | null,
): boolean {
  const sent = sendCommand(command);
  if (sent && expectedKey && expectedInstance
    && game.value?.dialogParameter === expectedInstance
    && dialogInstanceLive(expectedKey)) {
    latchAnsweredDialogInstance(expectedKey, expectedInstance);
  }
  return sent;
}
/** Hide an exact locally-declined dialog occurrence when upstream deliberately expects no command. */
function acknowledgeAnsweredDialogInstance(
  expectedKey: string | null,
  expectedInstance: object | null,
): boolean {
  if (!expectedKey || !expectedInstance
    || game.value?.dialogParameter !== expectedInstance
    || !dialogInstanceLive(expectedKey)) return false;
  latchAnsweredDialogInstance(expectedKey, expectedInstance);
  return true;
}
/** Any interactive decision surface is up — the queue PAUSES (never answers a dialog on the user's behalf). */
function plannerPromptPending(): boolean {
  // Hold the planner on model-level dialogs/pushback; UI surfaces arm after model application.
  const g = game.value;
  const dialogId = String((g?.dialogParameter as { dialogId?: unknown } | null | undefined)?.dialogId ?? '');
  const onTheBallInfo = plannerPlan?.onTheBallMode != null && dialogId === plannerPlan.onTheBallMode;
  if (g?.dialogParameter && !onTheBallInfo && !dialogAlreadyAnswered()) return true;
  if (state.failedActionHold) return true; // owner 09-06: a failed roll's walk is still draining
  // SB-3/SR-269: model-truth HOLD, not FLUSH; the existing model-apply pause/resume advances once waitingForOpponent clears.
  if ((g as Record<string, unknown> | undefined)?.waitingForOpponent) return true;
  if (((g?.fieldModel?.pushbackSquareArray ?? []) as unknown[]).length > 0) return true;
  return !!(state.reRollPrompt || state.skillChoice || state.followupChoice || state.playerPick
    || state.pushChoice || state.blockPartial || state.multiBlockResolution || state.injuryInteraction || state.yesNo
    || state.blitzBlockChoice); // #111: a held blitz block-commit flavor choice pauses the queue + exempts the watchdog
}
/** Start a declare→move→act plan. `route` excludes the start square (may be empty = 0-waypoint declare→act). */
function plannerStart(input: {
  playerId: string; actKind: PlanActKind; route: [number, number][];
  targetCoordinate?: [number, number] | null; targetPlayerId?: string | null;
  blockKind?: string | null;                   // #34: optional special block-kind for a blitz (rides sendBlock flags)
  declareOnly?: boolean; declareAction?: string;
}): boolean {
  if (!play.active || !game.value) return false;
  const onTheBall = game.value.turnMode === 'kickoffReturn' || game.value.turnMode === 'passBlock';
  if (!settings.order66 && !onTheBall) return false;
  const { playerId, actKind } = input;
  if (!iControlPlayer(playerId)) { log('system', 'ignored: not your player / not your turn'); return false; }
  // Match the direct action offer: a fresh Blitz plan is legal only while the server's team-turn flag is clear.
  // `blitzWalk` is the continuation of an already-declared Blitz and must remain available after the flag flips.
  if (actKind === 'blitz') {
    const sideHome = game.value.teamHome.playerArray.some((p) => p.playerId === playerId);
    const turnData = sideHome ? game.value.turnDataHome : game.value.turnDataAway;
    // U9e 0.3.17 REGRESSION FIX: gate ONLY a FRESH second blitz, never the EXECUTION of the acting player's OWN
    // already-declared blitz. The `actKind:'blitz'` walk-to-contact-then-block (SpectateView, BLITZ client state)
    // is reached AFTER the server accepted this player's blitz declare — which is exactly what SET blitzUsed — so
    // re-gating it on that same flag wrongly reds a legal declared-blitz walk ("blitz already used" with none used).
    // Exempt when the acting player already carries a blitz action (their own in-flight blitz); a genuine second
    // blitz has a non-blitz acting action (or a different acting player). blitzWalk stays exempt as before.
    // U9e SUCCESSOR (g835, owner-live P1): the LIVE actingPlayer read can momentarily desync at the
    // walk-to-contact→block re-entry (SpectateView re-arms this plan after a flush) — one tick reads a
    // non-blitz action ⇒ the live test falsely reds a legal declared-blitz execution ("blitz already used",
    // none used; wire verified g835: server actingPlayer stayed {blitzer,blitzMove} throughout). Anchor the
    // exemption ALSO on the STICKY per-turn blitz declarer (#94 blitzActor): captured from the observed blitz
    // action, sticky through the turn, immune to the volatile live read. Still refuses a genuine second blitz —
    // a DIFFERENT player isn't the recorded declarer (blitzActor.id !== playerId), the turn-key guard prevents
    // any leak into a later turn, and the server stays the ultimate authority.
    const liveOwnBlitz = plannerActingId() === playerId && /blitz/i.test(plannerActingAction());
    const stickyOwnBlitz = !!blitzActor && blitzActor.turnKey === currentTurnKey(game.value) && blitzActor.id === playerId;
    const declaredOwnBlitz = liveOwnBlitz || stickyOwnBlitz;
    if (turnData?.blitzUsed && !declaredOwnBlitz) {
      log('system', '⚠ Blitz cancelled — this team has already used its Blitz this turn.');
      state.actionNotice = { text: 'Blitz already used this turn.', seq: (state.actionNotice?.seq ?? 0) + 1 };
      return false;
    }
  }
  // Abort an empty-route foul unless already adjacent; never burn the foul on a distant target.
  if (actKind === 'foul' && (input.route ?? []).length === 0) {
    const ac = plannerCoord(playerId);
    const vc = input.targetPlayerId ? plannerCoord(input.targetPlayerId) : null;
    const adjacent = !!ac && !!vc && Math.max(Math.abs(ac[0] - vc[0]), Math.abs(ac[1] - vc[1])) === 1;
    if (!adjacent) {
      log('system', '⚠ Foul cancelled — the fouler can’t reach the victim (no walk path). Move adjacent first.');
      state.actionNotice = { text: 'Can’t reach the victim to foul — no walk path.', seq: (state.actionNotice?.seq ?? 0) + 1 };
      return false;
    }
  }
  if (plannerPlan) plannerFlush('superseded by a new plan');
  const route = (input.route ?? []).map((c) => [c[0], c[1]] as [number, number]);
  const moving = route.length > 0;
  // TTM/KTM/blitz are ALWAYS declared as their moving variant via the earlier click/menu, so they use it regardless of route length; pass/foul/hand-off switch to the plain (standing) variant when there's no walk.
  let declare: string = moving
    ? ({ pass: 'passMove', foul: 'foulMove', handOver: 'handOverMove', throwTeamMate: 'throwTeamMateMove', kickTeamMate: 'kickTeamMateMove', block: 'block', blitz: 'blitzMove', move: 'move', blitzWalk: 'blitzMove' } as const)[actKind]
    : ({ pass: 'pass', foul: 'foul', handOver: 'handOver', throwTeamMate: 'throwTeamMateMove', kickTeamMate: 'kickTeamMateMove', block: 'block', blitz: 'blitzMove', move: 'move', blitzWalk: 'blitzMove' } as const)[actKind];
  let requestedDeclare = input.declareAction ?? declare;
  if (requestedDeclare === 'shotToNothing') declare = 'passMove';
  else if (requestedDeclare === 'shotToNothingBomb') declare = 'throwBomb';
  else if (input.declareAction) declare = input.declareAction;
  // HAIL_MARY_PASS has no moving variant: preserve the already-declared action through both walk-only and
  // walk-then-throw plans while Punt remains a composite move action below.
  const currentAction = plannerActingId() === playerId ? plannerActingAction() : '';
  if ((actKind === 'move' || actKind === 'pass') && currentAction === 'hailMaryPass') declare = currentAction;
  // Preserve a server-confirmed composite move action while walking; do not redeclare it as Move.
  if (actKind === 'move') {
    const cur = currentAction;
    // Punt is the same composite *Move shape: movement happens inside the declared action. Preserve `puntMove`
    // through the per-square planner drip so the later in-action `punt` escalation remains available.
    if (cur === 'passMove' || cur === 'foulMove' || cur === 'handOverMove' || cur === 'gazeMove'
        || cur === 'throwTeamMateMove' || cur === 'kickTeamMateMove' || cur === 'puntMove'
        || cur === 'kickEmBlitz') declare = cur;
    // Item 866-TTM (row27): once the acting player's *Move variant resolves its target-select click, the server
    // demotes playerAction to the BASE form (throwTeamMate/kickTeamMate/pass/foul/handOver/gaze[Select]) and
    // clears every offered move square — PlayerAction.isMoving() (PlayerAction.java:68-71) is false for every one
    // of these bases, so upstream offers no further walk once the target is selected; only the throw/act itself
    // remains. availableActions.ts's `declaresAllowed` (Law 10d) agrees: `hasMoved`/`hasPassed`/`hasFouled` etc.
    // are already true here, so the move rail correctly REFUSES a fresh clientActingPlayer{playerAction:'move'}
    // (rail-shadow classification=false-refusal, game 866 22:24:36.893 — the server's ack (commandNr 2045)
    // silently overwrote actingPlayerSetPlayerAction to 'move' mid-DISPATCH_SCATTER_PLAYER, then the coach's
    // deselect at 22:24:38.385 tore down the whole THROW_TEAM_MATE activation, stranding the picked-up
    // teammate — read as "ball carrier cannot move"). Refuse the plan instead of emitting the illegal redeclare;
    // the coach must finish the already-declared throw (click a landing square) or End Activation.
    const targetLockedBase = cur === 'throwTeamMate' || cur === 'kickTeamMate' || cur === 'pass'
      || cur === 'foul' || cur === 'handOver' || cur === 'gaze' || cur === 'gazeSelect';
    if (targetLockedBase) {
      const text = `⚠ Move cancelled — ${playerName(game.value, playerId)} already selected a target; finish or end that action first.`;
      log('system', text);
      state.actionNotice = { text, seq: (state.actionNotice?.seq ?? 0) + 1 };
      return false;
    }
  }
  // Precompute server-published rolls per route square and wait for each successful result before advancing.
  const squareResolutions: Set<PlanResolution>[] = route.map((sq) => plannerSquareResolutions(game.value!, sq));
  plannerSet({
    seq: ++plannerSeq, playerId, actKind, moving, declare, declareOnly: input.declareOnly === true,
    route, sentIdx: -1, squareResolutions, retryResolvedIdx: null, sentOfferRevisions: [],
    targetCoordinate: input.targetCoordinate ?? null, targetPlayerId: input.targetPlayerId ?? null,
    blockKind: input.blockKind ?? null,
    blockChoiceResolved: input.blockKind != null,
    goredCommit: false,
    terminalSent: false,
    phase: 'declaring', turnKey: currentTurnKey(game.value),
    onTheBallMode: game.value.turnMode === 'kickoffReturn' || game.value.turnMode === 'passBlock' ? game.value.turnMode : null,
  });
  plannerArmAbort();
  log('system', `plan: ${actKind.toUpperCase()} ${playerName(game.value, playerId)} — ${route.length} sq walk${squareResolutions.some((s) => s.size) ? ` (${squareResolutions.filter((s) => s.size).length} roll-sq)` : ''} → act (server-sequenced)`);
  const alreadyDeclared = plannerActingId() === playerId && plannerActingAction() === declare;
  if (!alreadyDeclared) gameStore.declareAction(playerId, declare);
  plannerAdvance();
  return true;
}

/** Send the trailing act command (leg 3) and retire the plan — the derived act state / server resolution is the ack; we never hang on full resolution (opponent-side interception resolves independently). */
function plannerFireAct() {
  const p = plannerPlan; if (!p) return;
  // #99-b: a WALK-ONLY plan (pure Move / bare blitz Walk) has NO act leg — the per-square walk IS the whole plan; once the final square settles, just retire. (o66Move/o66BlitzMove multi-square delegate here purely to get #76's per-square drip so the server rolls each TZ-exit dodge/GFI — a batched clientMove skips them = the #99 bug.)
  if (p.actKind === 'move' || p.actKind === 'blitzWalk') { plannerSet(null); plannerClearAbort(); return; }
  if (p.actKind === 'pass' && p.targetCoordinate) {
    if (!p.terminalSent) {
      const accepted = gameStore.sendPassTarget(p.targetCoordinate);
      if (accepted) {
        state.acceptedPassSubmission = {
          seq: p.seq, playerId: p.playerId, square: [p.targetCoordinate[0], p.targetCoordinate[1]],
        };
      }
      p.terminalSent = accepted;
    }
    if (!p.terminalSent) return;
  }
  else if (p.actKind === 'foul' && p.targetPlayerId) {
    p.terminalSent = gameStore.sendFoulTarget(p.targetPlayerId);
    if (!p.terminalSent) return;
  }
  else if (p.actKind === 'handOver' && p.targetPlayerId) {
    p.terminalSent = gameStore.sendHandOverTarget(p.targetPlayerId);
    if (!p.terminalSent) return;
  }
  else if ((p.actKind === 'throwTeamMate' || p.actKind === 'kickTeamMate') && p.targetPlayerId) {
    gameStore.sendThrowMatePickup(p.targetPlayerId, p.actKind === 'kickTeamMate');
  }
  else if (p.actKind === 'block' && p.targetPlayerId) {
    p.terminalSent = gameStore.sendBlock(p.playerId, p.targetPlayerId, blockFlagsFromKind(p.blockKind));
    if (!p.terminalSent) return;
  }
  // Blitz: the act leg is the BLOCK — sendBlock hands off to the FROZEN block rail (blockPartial/
  // followupChoice/reRollPrompt); the queue drives declare→target→walk then RELEASES here (Echo: don't template
  // the block sub-choices). Plain block (no flavor) — matches the retired o66BlitzExecute.
  else if (p.actKind === 'blitz' && p.targetPlayerId) {
    // #207 + owner 08-05: an explicit menu flavor is already decided and never needs this chooser. Otherwise HOLD
    // for a Chainsaw offer or a server-decorated Gored by the Bull offer (Star S5); a non-carrier falls through to
    // the same plain send as a flavorless blitzer. The hold participates in plannerPromptPending (watchdog pauses).
    if (!p.blockChoiceResolved && p.blockKind == null && holdBlitzBlockChoice(p.playerId, p.targetPlayerId)) {
      return; // held — plan stays in 'acting'; commitBlitzBlock fires the terminal clientBlock + retires
    }
    if (p.goredCommit) {
      sendCommand({ netCommandId: NetCommandId.CLIENT_USE_SKILL, skill: 'Gored By The Bull', skillUsed: true, playerId: p.playerId });
      p.terminalSent = gameStore.sendBlock(p.playerId, p.targetPlayerId);
    } else {
      p.terminalSent = gameStore.sendBlock(p.playerId, p.targetPlayerId, blockFlagsFromKind(p.blockKind));
    }
    if (!p.terminalSent) return;
  }
  else { plannerFlush('the plan lost its target'); return; }
  plannerSet(null); plannerClearAbort();
}
/** Advance / flush the plan against the CURRENT model. Called on plan start and after every applied command. */
function plannerAdvance() {
  const p = plannerPlan, g = game.value; if (!p || !g) return;
  const turnMode = String(g.turnMode ?? '');
  // ---- GLOBAL FLUSH GUARDS ----
  // W27: an OtB walk-only plan may drain only inside the exact reaction window where it started. Every pre-W27
  // plan keeps the original regular/blitz allow-list; a regular plan cannot survive into an OtB window, and an
  // OtB plan cannot survive the mode ending or switching to the other reaction mode.
  const allowedTurnMode = p.onTheBallMode !== null
    ? p.actKind === 'move' && turnMode === p.onTheBallMode
    : turnMode === 'regular' || turnMode === 'blitz';
  if (!allowedTurnMode) { plannerFlush(`the turn ended (${turnMode || 'no turn'})`); return; }
  if (currentTurnKey(g) !== p.turnKey) { plannerFlush('the turn changed'); return; }
  const base = plannerBase(p.playerId);
  // knocked down / stunned / removed at any point = turnover-ish; never continue a plan past it
  if (base != null && base !== 0x01 && base !== 0x02) { plannerFlush(`${playerName(g, p.playerId)} is no longer standing`); return; }
  // ---- PAUSE (a decision surface is up) ----
  if (plannerPromptPending()) return;
  const actingId = plannerActingId();
  switch (p.phase) {
    case 'declaring': {
      if (actingId === p.playerId && plannerActingAction() === p.declare) {
        if (p.declareOnly) {
          plannerSet(null);
          plannerClearAbort();
          return;
        }
        // Send one live-coordinate move/blitzMove square per server echo; Blitz must retain blitzMove for its block.
        if (p.moving) {
          const first: [number, number][] = [p.route[0]!];
          // A declaration acknowledgement and the refreshed MoveSquare list can arrive in adjacent model
          // frames. Never ask either sender to speculate across that seam; wait for the server to publish the
          // exact first square and let the next applied frame resume this same plan.
          const firstOffer = currentMoveOffer(p.playerId, first[0]!);
          if (!firstOffer) return;
          if (!moveSquareInfo(g).has(`${first[0]![0]},${first[0]![1]}`)) return;
          // The declaration acknowledgement owns the authoritative first-step roll values. Refresh here rather
          // than trusting the pre-declaration planning snapshot.
          p.squareResolutions[0] = plannerSquareResolutions(g, first[0]!);
          const accepted = p.actKind === 'blitz' || p.actKind === 'blitzWalk'
            ? gameStore.o66BlitzMove(p.playerId, first)
            : gameStore.o66Move(p.playerId, first);
          // A refused send has no server echo to wait for. Keep the declaring index intact and retry only when
          // another authoritative frame calls plannerAdvance; never manufacture an 8s phantom-response timeout.
          if (!accepted) { plannerClearAbort(); return; }
          p.phase = 'moving';
          p.sentIdx = 0;
          p.sentOfferRevisions[0] = firstOffer.revision;
          plannerArmAbort();
        }
        else { p.phase = 'acting'; plannerArmAbort(); plannerFireAct(); }
      } else if (actingId && actingId !== p.playerId) {
        plannerFlush('the server activated a different player');
      }
      return;
    }
    case 'moving': {
      if (actingId !== p.playerId) { plannerFlush('lost the activation during the walk'); return; }
      if (plannerActingAction() !== p.declare) { plannerFlush('the move action ended'); return; }
      const coord = plannerCoord(p.playerId);
      // Advance after the coordinate echo and successful required rolls; MOVING can persist for the activation.
      const atSent = !!coord && !!p.route[p.sentIdx] && coord[0] === p.route[p.sentIdx]![0] && coord[1] === p.route[p.sentIdx]![1];
      const curRolls = p.squareResolutions[p.sentIdx];
      if (!atSent) {
        // Captured fork wire (g907 cmd99..102): a failed Dodge followed by a successful re-roll reports success,
        // clears the dialog, and republishes the attempted destination, but does not emit a coordinate change.
        // Upstream has returned to move selection and expects the client to submit that SAME destination once.
        // Keep it strictly server-bounded: only a successful re-roll can arm this path, every owed roll must be
        // resolved, the destination must be freshly offered, and clearing the marker before send prevents a
        // duplicate applied frame from issuing it twice. A refused transport re-arms for the next model frame.
        if (p.retryResolvedIdx === p.sentIdx && (!curRolls || curRolls.size === 0)) {
          const retry = p.route[p.sentIdx];
          const priorRevision = p.sentOfferRevisions[p.sentIdx] ?? -1;
          const retryOffer = retry ? currentMoveOffer(p.playerId, retry, priorRevision) : null;
          if (!retryOffer) return;
          if (!retry || !moveSquareInfo(g).has(`${retry[0]},${retry[1]}`)) return;
          p.retryResolvedIdx = null;
          const accepted = p.actKind === 'blitz' || p.actKind === 'blitzWalk'
            ? gameStore.o66BlitzMove(p.playerId, [retry], priorRevision)
            : gameStore.o66Move(p.playerId, [retry], priorRevision);
          if (!accepted) { p.retryResolvedIdx = p.sentIdx; plannerClearAbort(); return; }
          p.sentOfferRevisions[p.sentIdx] = retryOffer.revision;
          plannerArmAbort();
        }
        return; // still walking to the last-sent square
      }
      if (p.retryResolvedIdx === p.sentIdx) p.retryResolvedIdx = null; // a late authoritative echo won the race
      if (curRolls && curRolls.size > 0) return; // arrived, but this square's flagged roll(s) haven't all resolved-successful yet
      if (p.sentIdx < p.route.length - 1) {
        // reached square N, its rolls resolved → send square N+1 (single square, live coordinateFrom). Idempotent:
        // keyed on reaching route[sentIdx], so a duplicate echo at the same reached square re-sends nothing (sentIdx
        // already points past it, coord != route[sentIdx+1] yet).
        const nextIdx = p.sentIdx + 1;
        const next: [number, number][] = [p.route[nextIdx]!];
        // The coordinate echo and its next-square refresh are not guaranteed to share a command. Games 905
        // and 906 delivered them one frame apart. Sending in that gap either trips a shadow false-refusal or
        // reaches the server before the square exists. Keep the existing watchdog and resume on the refresh.
        const nextOffer = currentMoveOffer(p.playerId, next[0]!);
        if (!nextOffer) return;
        if (!moveSquareInfo(g).has(`${next[0]![0]},${next[0]![1]}`)) return;
        // Every later step has a new server-authored Dodge/Rush/Pickup offer. The initial route snapshot cannot
        // know those values several squares ahead (g907 failed on step four), so bind the owed results now.
        p.squareResolutions[nextIdx] = plannerSquareResolutions(g, next[0]!);
        const accepted = p.actKind === 'blitz' || p.actKind === 'blitzWalk'
          ? gameStore.o66BlitzMove(p.playerId, next)
          : gameStore.o66Move(p.playerId, next);
        // Commit the sent index only after the command reached transport. A later model frame retries the same
        // square after a refusal; once accepted, the new index makes duplicate frames idempotent as before.
        if (!accepted) { plannerClearAbort(); return; }
        p.sentIdx = nextIdx;
        p.sentOfferRevisions[nextIdx] = nextOffer.revision;
        plannerArmAbort();
        return;
      }
      // reached the FINAL square + its rolls resolved (the gate above) → fire the act (walk-only plans retire in plannerFireAct; a trailing block/act is thus ack-gated behind the final walk-square's resolution).
      p.phase = 'acting'; plannerArmAbort(); plannerFireAct();
      return;
    }
    case 'acting':
      plannerFireAct();
      return;
  }
}

let isolatedPresentationTestCommandNr = 900_000_000;

/** @internal Authoritative Pro-result presentation seam. Every mode drives the same applyFrame path used by
 * live play, live spectators, and replay; only the runtime mode flags differ. */
export function installProFailureSplashTestHarness(
  fixture: GameJson,
  mode: 'play' | 'spectator' | 'replay',
): {
  apply(successful: boolean, reportId?: 'reRoll' | 'blockReRoll'): void;
  splash(): typeof state.rerollSplash;
  skillUsed(): typeof state.skillUsed;
  teardown(): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorPlay = { ...play };
  const priorReplayActive = replay.active;
  const priorCatchingUp = playback.catchingUp;
  const priorCommandNr = lastAppliedCommandNr;
  const priorSplash = state.rerollSplash;
  const priorSkillUsed = state.skillUsed;
  clearCinematics(true);
  game.value = structuredClone(fixture);
  game.value.half = Math.max(1, Number(game.value.half ?? 0));
  game.value.turnMode = 'regular';
  game.value.dialogParameter = null;
  play.active = mode === 'play';
  play.coach = play.active ? String(fixture.teamHome.coach ?? '') : '';
  replay.active = mode === 'replay';
  playback.catchingUp = false;
  lastAppliedCommandNr = -1;
  return {
    apply(successful, reportId = 'reRoll') {
      isolatedPresentationTestCommandNr += 1;
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr: isolatedPresentationTestCommandNr,
          modelChangeList: { modelChangeArray: [] },
          reportList: {
            reports: [{
              reportId,
              playerId: fixture.teamHome.playerArray[0]!.playerId,
              reRollSource: 'Pro',
              roll: successful ? 4 : 1,
              successful,
            }],
          },
        },
      });
    },
    splash: () => state.rerollSplash,
    skillUsed: () => state.skillUsed,
    teardown: () => clearCinematics(true),
    dispose() {
      clearCinematics(true);
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      replay.active = priorReplayActive;
      playback.catchingUp = priorCatchingUp;
      lastAppliedCommandNr = priorCommandNr;
      state.rerollSplash = priorSplash;
      state.skillUsed = priorSkillUsed;
    },
  };
}

/** @internal W27 production-planner test seam. Installs an isolated in-memory game/session and drives the SAME
 * plannerStart/plannerAdvance functions used at runtime; no alternate drain implementation exists. The caller
 * must dispose it. Kept out of gameStore so application code cannot discover or invoke it accidentally. */
export function installMovePlannerTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => void,
): {
  start(playerId: string, route: [number, number][]): boolean;
  submit(playerId: string, route: [number, number][]): void;
  echo(
    playerId: string,
    square: [number, number],
    currentMove: number,
    moveSquares?: Array<[number, number] | {
      coordinate: [number, number]; minimumRollDodge?: number; minimumRollGfi?: number;
    }>,
  ): void;
  apply(changes: Record<string, unknown>[], reports?: Record<string, unknown>[]): void;
  fail(playerId: string, reportId: 'dodgeRoll' | 'goForItRoll' | 'pickUpRoll'): void;
  failAndFall(playerId: string, reportId: 'dodgeRoll' | 'goForItRoll', injuryType: 'dropDodge' | 'dropGfi'): void;
  failAndEndActivation(playerId: string, reportId: 'dodgeRoll' | 'goForItRoll' | 'pickUpRoll'): void;
  resolve(playerId: string, reportId: 'dodgeRoll' | 'goForItRoll' | 'pickUpRoll', successful: boolean, reRolled?: boolean): void;
  fall(playerId: string, injuryType: 'dropDodge' | 'dropGfi'): void;
  endActivation(): void;
  setTurnMode(turnMode: string): void;
  setCatchUp(catchingUp: boolean): void;
  /** Test seam: stamp the receive-time acting mirror the way enqueueSync does, WITHOUT applying it to the model
   *  (simulates a declare echo still queued behind a presentation drain). */
  mirrorActing(playerId: string | null, playerAction: string | null): void;
  active(): boolean;
  intent(): typeof state.movementIntent;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorOrder66 = settings.order66;
  const priorInteractiveSetup = interactiveSetup;
  const priorMovementIntent = state.movementIntent;
  const priorMovementPresentationFence = state.movementPresentationFence;
  const priorBoardPresentationFence = state.boardPresentationFence;
  const priorConfirmedMovementDrainActive = state.confirmedMovementDrainActive;
  const priorPlaybackCatchingUp = playback.catchingUp;
  const priorMovementRttEwmaMs = movementRttEwmaMs;
  const priorMoveOfferOccurrences = new Map(moveOfferOccurrences);
  const priorMoveOfferRevision = moveOfferRevision;
  const priorCommandNr = lastAppliedCommandNr;
  plannerClearAbort();
  plannerSet(null);
  state.movementIntent = null;
  movementRttEwmaMs = 90;
  lastAppliedCommandNr = -1;
  game.value = fixture;
  play.active = true;
  play.coach = String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach');
  interactiveSetup = true;
  settings.order66 = true;
  // This harness exercises the production Modern Order-66 planner/presentation seam; mirror the mounted Modern
  // capability so its confirmed-step assertions do not bypass the consumer contract under test.
  const unregisterConfirmedMovementPresentation = gameStore.registerConfirmedMovementPresentationConsumer();
  session = { send } as unknown as GameSession;
  seedMoveOfferSnapshot();

  return {
    start: (playerId, route) => plannerStart({ playerId, actKind: 'move', route }),
    submit: (playerId, route) => gameStore.o66Move(playerId, route),
    echo(playerId, square, currentMove, moveSquares) {
      observeMovementIntentEcho(playerId, square);
      const data = game.value?.fieldModel.playerDataArray.find((entry) => entry.playerId === playerId);
      if (data) data.playerCoordinate = [square[0], square[1]];
      if (game.value && moveSquares) {
        const priorSquares = game.value.fieldModel.moveSquareArray ?? [];
        const nextSquares = moveSquares.map((entry) => Array.isArray(entry)
          ? { coordinate: [entry[0], entry[1]] }
          : {
              coordinate: [entry.coordinate[0], entry.coordinate[1]],
              minimumRollDodge: entry.minimumRollDodge,
              minimumRollGfi: entry.minimumRollGfi,
            });
        game.value.fieldModel.moveSquareArray = nextSquares;
        observeMoveOfferGeneration({
          modelChangeList: {
            modelChangeArray: [
              ...priorSquares.map((entry) => ({
                modelChangeId: 'fieldModelRemoveMoveSquare', modelChangeValue: entry,
              })),
              ...nextSquares.map((entry) => ({
                modelChangeId: 'fieldModelAddMoveSquare', modelChangeValue: entry,
              })),
            ],
          },
        });
      }
      const acting = game.value?.actingPlayer as { currentMove?: number } | undefined;
      if (acting) acting.currentMove = currentMove;
      plannerAdvance();
    },
    apply(changes, reports = []) {
      isolatedPresentationTestCommandNr += 1;
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr: isolatedPresentationTestCommandNr,
          modelChangeList: { modelChangeArray: changes },
          reportList: { reports },
        },
      });
    },
    fail(playerId, reportId) {
      confirmFailedMovementIntent([{ reportId, playerId, successful: false }]);
    },
    failAndFall(playerId, reportId, injuryType) {
      const intentAtFrameStart = state.movementIntent;
      const data = game.value?.fieldModel.playerDataArray.find((entry) => entry.playerId === playerId);
      if (data) data.playerState = 0x03;
      const reports = [
        { reportId, playerId, successful: false },
        { reportId: 'injury', defenderId: playerId, injuryType, armorBroken: false },
      ];
      confirmFailedMovementIntent(reports);
      plannerOnModelApplied({ reportList: { reports } });
      settleMovementIntentAfterFrame(reports, intentAtFrameStart);
    },
    failAndEndActivation(playerId, reportId) {
      const intentAtFrameStart = state.movementIntent;
      const reports = [{ reportId, playerId, successful: false }];
      const acting = game.value?.actingPlayer as { playerId?: string | null } | undefined;
      if (acting) acting.playerId = null;
      confirmFailedMovementIntent(reports);
      plannerOnModelApplied({ reportList: { reports } });
      settleMovementIntentAfterFrame(reports, intentAtFrameStart);
    },
    resolve(playerId, reportId, successful, reRolled = false) {
      const intentAtFrameStart = state.movementIntent;
      const reports = [{ reportId, playerId, successful, reRolled }];
      confirmFailedMovementIntent(reports);
      plannerOnModelApplied({ reportList: { reports } });
      settleMovementIntentAfterFrame(reports, intentAtFrameStart);
    },
    fall(playerId, injuryType) {
      const intentAtFrameStart = state.movementIntent;
      const data = game.value?.fieldModel.playerDataArray.find((entry) => entry.playerId === playerId);
      if (data) data.playerState = 0x03;
      const reports = [{ reportId: 'injury', defenderId: playerId, injuryType, armorBroken: false }];
      plannerOnModelApplied({ reportList: { reports } });
      settleMovementIntentAfterFrame(reports, intentAtFrameStart);
    },
    endActivation() {
      const intentAtFrameStart = state.movementIntent;
      const acting = game.value?.actingPlayer as { playerId?: string | null } | undefined;
      if (acting) acting.playerId = null;
      plannerOnModelApplied({ reportList: { reports: [] } });
      settleMovementIntentAfterFrame([], intentAtFrameStart);
    },
    setTurnMode(turnMode) {
      if (game.value) game.value.turnMode = turnMode;
      plannerAdvance();
    },
    setCatchUp(catchingUp) {
      playback.catchingUp = catchingUp;
      syncConfirmedMovementPresentationCapability();
    },
    mirrorActing(playerId, playerAction) { srvActingId = playerId; srvActingAction = playerAction; },
    active: plannerActive,
    intent: () => state.movementIntent,
    dispose() {
      unregisterConfirmedMovementPresentation();
      plannerClearAbort();
      plannerSet(null);
      srvActingId = null; srvActingAction = null; // mirrorActing seam must not leak across tests
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      interactiveSetup = priorInteractiveSetup;
      settings.order66 = priorOrder66;
      state.movementIntent = priorMovementIntent;
      state.movementPresentationFence = priorMovementPresentationFence;
      state.boardPresentationFence = priorBoardPresentationFence;
      state.confirmedMovementDrainActive = priorConfirmedMovementDrainActive;
      playback.catchingUp = priorPlaybackCatchingUp;
      movementRttEwmaMs = priorMovementRttEwmaMs;
      moveOfferOccurrences.clear();
      for (const [key, occurrence] of priorMoveOfferOccurrences) moveOfferOccurrences.set(key, occurrence);
      moveOfferRevision = priorMoveOfferRevision;
      lastAppliedCommandNr = priorCommandNr;
    },
  };
}

/** @internal Exact pending-block/Foul-Appearance correlation seam. It drives the production send, apply,
 * formatter, and watchdog paths so tests can prove expected non-registration is occurrence-scoped. */
export function installFoulAppearanceBlockWatchTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => boolean | void,
): {
  sendBlock(attackerId: string, defenderId: string): void;
  apply(reports: Record<string, unknown>[], changes?: ModelChangeListJson['modelChangeArray']): void;
  resetAction(attackerId: string, defenderId: string): void;
  logs(): string[];
  notice(): typeof state.actionNotice;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorOrder66 = settings.order66;
  const priorInteractiveSetup = interactiveSetup;
  const priorNotice = state.actionNotice;
  const logStart = state.log.length;
  clearBlockWatch();
  game.value = fixture;
  play.active = true;
  play.coach = String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach');
  settings.order66 = true;
  interactiveSetup = true;
  state.actionNotice = null;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;
  let commandNr = 900_000;
  return {
    sendBlock(attackerId, defenderId) { gameStore.sendBlock(attackerId, defenderId); },
    apply(reports, changes = []) {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr: ++commandNr,
          modelChangeList: { modelChangeArray: changes },
          reportList: { reports },
        },
      });
    },
    resetAction(attackerId, defenderId) {
      if (!game.value) return;
      (game.value as { defenderId?: string | null }).defenderId = defenderId;
      game.value.actingPlayer = {
        ...(game.value.actingPlayer ?? {}),
        playerId: attackerId,
        playerAction: 'block',
        currentMove: 0,
      } as GameJson['actingPlayer'];
    },
    logs: () => state.log.slice(logStart).map((entry) => entry.text),
    notice: () => state.actionNotice,
    dispose() {
      clearBlockWatch();
      activeFoulAppearanceContext = null;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      settings.order66 = priorOrder66;
      interactiveSetup = priorInteractiveSetup;
      state.actionNotice = priorNotice;
    },
  };
}

