/** @internal Prayers-to-Nuffle production applyFrame/FIFO seam. */
export function installPrayerPresentationTestHarness(
  fixture: GameJson,
  seat: 'home' | 'away' | 'classicHome' | 'spectator',
  send: (command: Record<string, unknown>) => boolean | void = () => undefined,
): {
  apply(reports: Record<string, unknown>[], dialog: Record<string, unknown> | null, commandNr: number): void;
  announcement(): typeof state.prayerAnnounce;
  wait(): typeof state.prayerChoiceWait;
  selectSkill(): typeof state.selectSkill;
  playerPick(): typeof state.playerPick;
  rockThrow(): typeof state.rockThrow;
  cineShowing(): boolean;
  setCatchingUp(on: boolean): void;
  settleCatchup(): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorInteractiveSetup = interactiveSetup;
  const priorInteractiveReRolls = interactiveReRolls;
  const priorClickDismiss = settings.clickDismissCinematics;
  const priorCatchingUp = playback.catchingUp;
  const priorAnnouncement = state.prayerAnnounce;
  const priorAnnouncementSeq = prayerAnnounceSeq;
  const priorWait = state.prayerChoiceWait;
  const priorSelectSkill = state.selectSkill;
  const priorPlayerPick = state.playerPick;
  const priorRockThrow = state.rockThrow;
  const priorHandled = [...pregameHandled];

  clearPregameCine();
  pregameHandled.clear();
  state.prayerAnnounce = null;
  prayerAnnounceSeq = 0;
  state.prayerChoiceWait = null;
  state.selectSkill = null;
  state.playerPick = null;
  state.rockThrow = null;
  prayerDialogDrainArms.clear();
  game.value = fixture;
  game.value.turnMode = 'regular';
  play.active = seat !== 'spectator';
  play.coach = seat === 'home' || seat === 'classicHome'
    ? String(fixture.teamHome.coach ?? '')
    : seat === 'away' ? String(fixture.teamAway.coach ?? '') : 'spectator';
  interactiveSetup = seat !== 'classicHome';
  interactiveReRolls = true;
  settings.clickDismissCinematics = true;
  playback.catchingUp = false;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  const refreshLiveTail = () => {
    clearCatchupTransients();
    const prayer = game.value ? interactivePrayerDialog(game.value) : null;
    syncInteractivePrayerPresentation();
    if (prayer?.kind === 'player' && play.active) drivePregameStep();
  };
  return {
    apply(reports, dialog, commandNr) {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr,
          modelChangeList: { modelChangeArray: [{
            modelChangeId: 'gameSetDialogParameter', modelChangeKey: null, modelChangeValue: dialog,
          }] },
          reportList: { reports },
        },
      });
    },
    announcement: () => state.prayerAnnounce,
    wait: () => state.prayerChoiceWait,
    selectSkill: () => state.selectSkill,
    playerPick: () => state.playerPick,
    rockThrow: () => state.rockThrow,
    cineShowing: () => gameStore.cineShowing.value,
    setCatchingUp(on) { playback.catchingUp = on; },
    settleCatchup() { playback.catchingUp = false; refreshLiveTail(); },
    dispose() {
      clearPregameCine();
      pregameHandled.clear();
      for (const key of priorHandled) pregameHandled.add(key);
      prayerDialogDrainArms.clear();
      state.prayerAnnounce = priorAnnouncement;
      prayerAnnounceSeq = priorAnnouncementSeq;
      state.prayerChoiceWait = priorWait;
      state.selectSkill = priorSelectSkill;
      state.playerPick = priorPlayerPick;
      state.rockThrow = priorRockThrow;
      game.value = priorGame;
      session = priorSession;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      interactiveSetup = priorInteractiveSetup;
      interactiveReRolls = priorInteractiveReRolls;
      settings.clickDismissCinematics = priorClickDismiss;
      playback.catchingUp = priorCatchingUp;
    },
  };
}

/** @internal Wizard Zap target-staging seam. Both Modern and Classic consume this one store rail; the seat name
 *  only proves both interactive presentations reach the same controller. Spectator remains passive/zero-send. */
export function installWizardTargetConfirmationTestHarness(
  fixture: GameJson,
  seat: 'modern' | 'classic' | 'spectator',
  send: (command: Record<string, unknown>) => void,
): {
  targetSquares(): [number, number][];
  select(square: [number, number]): void;
  pending(): typeof state.wizardTargetConfirm;
  confirm(): void;
  cancel(): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorCommandNr = lastAppliedCommandNr;
  const priorOffer = liveWizardSpellOffer;
  const priorSpell = liveWizardSpell;
  const priorAwaiting = liveWizardSpellAwaitingServer;
  const priorPick = state.squarePick;
  const priorConfirm = state.wizardTargetConfirm;
  const priorInducement = state.inducementUse;

  const commandNr = 41;
  const teamId = fixture.teamHome.teamId;
  fixture.turnMode = 'wizard';
  fixture.dialogParameter = { dialogId: 'wizardSpell', teamId };
  game.value = fixture;
  play.active = seat !== 'spectator';
  play.coach = seat === 'spectator' ? 'spectator' : String(fixture.teamHome.coach ?? 'home-coach');
  lastAppliedCommandNr = commandNr;
  liveWizardSpellOffer = {
    commandNr, teamId, enabledSpells: ['zap'],
    authority: seat === 'spectator'
      ? { role: 'spectator' }
      : { role: 'player', myTeamId: teamId, decisionTeamId: teamId },
  };
  liveWizardSpell = 'zap';
  liveWizardSpellAwaitingServer = false;
  state.squarePick = null;
  state.wizardTargetConfirm = null;
  state.inducementUse = {
    key: wizardSpellKey(commandNr), prompt: 'Choose a Zap target on the pitch.', declineLabel: 'Cancel',
    options: [], seq: (priorInducement?.seq ?? 0) + 1,
  };
  session = { send } as unknown as GameSession;
  armServerCoordinatePicks();

  return {
    targetSquares: () => state.squarePick?.kind === 'wizard' ? [...state.squarePick.squares] : [],
    select(square) { gameStore.resolveSquarePick(square); },
    pending: () => state.wizardTargetConfirm,
    confirm() { gameStore.confirmWizardTarget(); },
    cancel() { gameStore.cancelWizardTarget(); },
    dispose() {
      state.squarePick = priorPick;
      state.wizardTargetConfirm = priorConfirm;
      state.inducementUse = priorInducement;
      liveWizardSpellOffer = priorOffer;
      liveWizardSpell = priorSpell;
      liveWizardSpellAwaitingServer = priorAwaiting;
      lastAppliedCommandNr = priorCommandNr;
      game.value = priorGame;
      session = priorSession;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
    },
  };
}

/** @internal skillUse card clear-path seam (R-A6 Wrestle-decline persistence, owner 08-18). */
export function installSkillUseClearTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => boolean | void,
): {
  /** Apply one sync frame. `dialog` = new dialogParameter; `'keep'` leaves it unchanged (server holds the dialog live). */
  applySync(dialog: Record<string, unknown> | null | 'keep', reports: Record<string, unknown>[], commandNr: number): void;
  card(): typeof state.skillChoice;
  /** Owner 08-19: the used/declined skill TOAST arm (a declined Stand Firm must ride this, never a card). */
  skillUsed(): typeof state.skillUsed;
  opponentPending(): typeof state.opponentChoicePending;
  opponentPendingPlayerId(): typeof state.opponentChoicePendingPlayerId;
  passTarget(square: [number, number]): boolean;
  handOverTarget(playerId: string): void;
  resolve(use: boolean): void;
  setPlayActive(on: boolean): void;
  setCoach(coach: string): void;
  /** @internal test-only: reinject a captured card (stale UI reference across a dialog transition). */
  forceCard(card: typeof state.skillChoice): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorChoice = state.skillChoice;
  const priorSkillUsed = state.skillUsed;
  const priorOpponentPending = state.opponentChoicePending;
  const priorOpponentPendingPlayerId = state.opponentChoicePendingPlayerId;
  const priorAnswered = answeredSkillDialog;
  const priorAutoFired = autoFiredSkillDialog;
  const priorInteractive = interactiveReRolls;
  const priorPassSkillUseTruth = passSkillUseTruth;
  const priorHmpScatterSkillUseTruth = hmpScatterSkillUseTruth;
  const priorPendingRailCommands = new Map(pendingRailCommands);

  answeredSkillDialog = null;
  clearPendingRailCommands();
  autoFiredSkillDialog = null;
  state.skillChoice = null;
  state.opponentChoicePending = null; state.opponentChoicePendingPlayerId = null;
  hmpScatterSkillUseTruth = null;
  game.value = fixture;
  game.value.turnMode = 'regular';
  play.active = true;
  play.coach = String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach');
  gameStore.setInteractiveReRolls(true);
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  return {
    applySync(dialog, reports, commandNr) {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: 'serverModelSync', commandNr,
          modelChangeList: {
            modelChangeArray: dialog === 'keep' ? [] : [{
              modelChangeId: 'gameSetDialogParameter', modelChangeKey: null, modelChangeValue: dialog,
            }],
          },
          reportList: { reports },
        },
      });
    },
    card: () => state.skillChoice,
    skillUsed: () => state.skillUsed,
    opponentPending: () => state.opponentChoicePending,
    opponentPendingPlayerId: () => state.opponentChoicePendingPlayerId,
    passTarget: (square) => gameStore.sendPassTarget(square),
    handOverTarget: (playerId) => gameStore.sendHandOverTarget(playerId),
    resolve(use) { gameStore.resolveSkillUse(use); },
    setPlayActive(on) { play.active = on; },
    setCoach(coach) { play.coach = coach; },
    forceCard(card) { state.skillChoice = card; },
    dispose() {
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      state.skillChoice = priorChoice;
      state.skillUsed = priorSkillUsed;
      state.opponentChoicePending = priorOpponentPending;
      state.opponentChoicePendingPlayerId = priorOpponentPendingPlayerId;
      answeredSkillDialog = priorAnswered;
      autoFiredSkillDialog = priorAutoFired;
      interactiveReRolls = priorInteractive;
      passSkillUseTruth = priorPassSkillUseTruth;
      hmpScatterSkillUseTruth = priorHmpScatterSkillUseTruth;
      clearPendingRailCommands();
      for (const [rail, pending] of priorPendingRailCommands) pendingRailCommands.set(rail, pending);
    },
  };
}

/** @internal Withergrasp Watch Out! integration seam over the production model-change apply path. */
export function installWatchOutToastTestHarness(
  fixture: GameJson,
  seat: 'home' | 'away' | 'spectator' | 'replay' = 'spectator',
): {
  apply(changes: ModelChangeListJson['modelChangeArray'], reports?: Record<string, unknown>[]): void;
  toast(): typeof state.watchOutToast;
  setCatchingUp(catchingUp: boolean): void;
  gameChange(next: GameJson): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorToast = state.watchOutToast;
  const priorCatchingUp = playback.catchingUp;
  const priorReplayActive = replay.active;
  const priorCommandNr = lastAppliedCommandNr;
  const priorAnnouncements = new Set(watchOutAnnouncedPlayers);

  game.value = fixture;
  game.value.turnMode = 'regular';
  play.active = seat === 'home' || seat === 'away';
  play.coach = seat === 'home'
    ? String((fixture.teamHome as { coach?: string }).coach ?? '')
    : seat === 'away'
      ? String((fixture.teamAway as { coach?: string }).coach ?? '')
      : 'watch-out-spectator';
  replay.active = seat === 'replay';
  state.watchOutToast = null;
  playback.catchingUp = false;
  session = { send() { /* presentation-only harness: no outbound command expected */ } } as unknown as GameSession;
  let commandNr = 0;

  return {
    apply(changes, reports = []) {
      commandNr += 1;
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr,
          modelChangeList: { modelChangeArray: changes },
          reportList: { reports },
        },
      });
    },
    toast: () => state.watchOutToast,
    setCatchingUp(catchingUp) { playback.catchingUp = catchingUp; },
    gameChange(next) {
      clearCinematics(true);
      game.value = next;
    },
    dispose() {
      state.watchOutToast = priorToast;
      playback.catchingUp = priorCatchingUp;
      replay.active = priorReplayActive;
      lastAppliedCommandNr = priorCommandNr;
      watchOutAnnouncedPlayers.clear();
      for (const playerId of priorAnnouncements) watchOutAnnouncedPlayers.add(playerId);
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
    },
  };
}

/** @internal Persistent blitz occurrence seam across replay collapse/seek and live-tail settlement. */
export function installBlitzTokenReplayTestHarness(fixture: GameJson): {
  apply(): void;
  collapse(): void;
  mutate(change: (game: GameJson) => void): void;
  hardBoundary(next: GameJson): void;
  tokens(): typeof state.blitzTokens;
  setCatchingUp(catchingUp: boolean): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorTokens = state.blitzTokens;
  const priorActor = blitzActor;
  const priorTarget = blitzActorTarget;
  const priorReplayActive = replay.active;
  const priorCatchingUp = playback.catchingUp;
  const priorCommandNr = lastAppliedCommandNr;

  clearCinematics(true);
  game.value = structuredClone(fixture);
  replay.active = true;
  playback.catchingUp = true;
  let commandNr = 0;
  return {
    apply() {
      commandNr += 1;
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr,
          modelChangeList: { modelChangeArray: [] },
          reportList: { reports: [] },
        },
      });
    },
    collapse() { clearCollapsedReplayPresentation(); },
    mutate(change) { if (game.value) change(game.value); },
    hardBoundary(next) { clearCinematics(true); game.value = structuredClone(next); },
    tokens: () => state.blitzTokens,
    setCatchingUp(catchingUp) { playback.catchingUp = catchingUp; },
    dispose() {
      clearCinematics(true);
      game.value = priorGame;
      state.blitzTokens = priorTokens;
      blitzActor = priorActor;
      blitzActorTarget = priorTarget;
      replay.active = priorReplayActive;
      playback.catchingUp = priorCatchingUp;
      lastAppliedCommandNr = priorCommandNr;
    },
  };
}

/** @internal Production applyFrame seam for the Modern confirmed-step renderer ownership publication. */
export function installConfirmedMovementDrainTestHarness(
  fixture: GameJson,
  mode: 'play' | 'spectator' | 'replay',
): {
  apply(changes?: ModelChangeListJson['modelChangeArray'], reports?: Record<string, unknown>[]): void;
  setCatchingUp(catchingUp: boolean): void;
  active(): boolean;
  gameChange(next: GameJson): void;
  teardown(): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorPlay = { ...play };
  const priorReplayActive = replay.active;
  const priorCatchingUp = playback.catchingUp;
  const priorOrder66 = settings.order66;
  const priorActive = state.confirmedMovementDrainActive;
  const priorRecovery = state.movementPresentationRecovery;
  const priorCommandNr = lastAppliedCommandNr;

  resetPresentation();
  game.value = structuredClone(fixture);
  game.value.half = Math.max(1, Number(game.value.half ?? 0));
  game.value.turnMode = 'regular';
  game.value.dialogParameter = null;
  play.active = mode === 'play';
  play.coach = mode === 'play'
    ? String((game.value.teamHome as { coach?: string }).coach ?? '')
    : 'confirmed-drain-spectator';
  replay.active = mode === 'replay';
  playback.catchingUp = true;
  settings.order66 = true;
  let commandNr = 0;

  return {
    apply(changes = [], reports = []) {
      commandNr += 1;
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr,
          modelChangeList: { modelChangeArray: changes },
          reportList: { reports },
        },
      });
    },
    setCatchingUp(catchingUp) { playback.catchingUp = catchingUp; },
    active: () => state.confirmedMovementDrainActive,
    gameChange(next) {
      clearCinematics(true);
      game.value = structuredClone(next);
      game.value.half = Math.max(1, Number(game.value.half ?? 0));
      game.value.turnMode = 'regular';
      game.value.dialogParameter = null;
    },
    teardown() { clearCinematics(true); },
    dispose() {
      clearCinematics(true);
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      replay.active = priorReplayActive;
      playback.catchingUp = priorCatchingUp;
      settings.order66 = priorOrder66;
      state.confirmedMovementDrainActive = priorActive;
      state.movementPresentationRecovery = priorRecovery;
      lastAppliedCommandNr = priorCommandNr;
    },
  };
}

/** @internal block-partial / synchronous multi-block reroll integration seam (Hatred `Single Skull` fixture coverage). */
export function installBlockPartialTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => boolean | void,
): {
  applyBlockDialog(extra: Record<string, unknown>, reports?: readonly Record<string, unknown>[]): void;
  surfaceReadOnlyBlockDialog(extra: Record<string, unknown>): void;
  applyAuthoritativeFrame(command: Record<string, unknown>): void;
  applyMultiBlockDialog(extra: Record<string, unknown>): void;
  partial(): typeof state.blockPartial;
  stamp(): typeof state.blockResultStamp;
  multi(): typeof state.multiBlockResolution;
  resolve(kind: 'accept' | 'declineReroll' | 'team' | 'mascot' | 'mascotTrr' | 'brawler' | 'pro' | 'consummate' | 'singleBlockDie' | 'hatred' | 'multiBlockDice', dieSelection?: number | number[]): void;
  sendMultiHatred(targetId: string): void;
  setCoach(coach: string): void;
  setPlaying(playing: boolean): void;
  setOrder66(enabled: boolean): void;
  presentationSeat(): 'home' | 'away' | null;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorOrder66 = settings.order66;
  const priorInteractive = interactiveReRolls;
  const priorBlockPartial = state.blockPartial;
  const priorMulti = state.multiBlockResolution;
  const priorHandled = [...followupHandled];

  followupHandled.clear();
  state.blockPartial = null;
  state.multiBlockResolution = null;
  game.value = fixture;
  game.value.turnMode = 'regular';
  play.active = true;
  play.coach = String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach');
  settings.order66 = false;
  interactiveReRolls = true;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  const teamId = String((fixture.teamHome as { teamId?: string }).teamId ?? '');
  const blockerId = String(fixture.teamHome.playerArray[0]!.playerId);

  return {
    applyBlockDialog(extra, reports = []) {
      if (game.value) {
        game.value.dialogParameter = {
          dialogId: 'blockRollProperties', choosingTeamId: teamId, ...extra,
        } as GameJson['dialogParameter'];
      }
      resolvePlayFollowups(reports);
    },
    surfaceReadOnlyBlockDialog(extra) {
      if (game.value) {
        game.value.dialogParameter = {
          dialogId: 'blockRollProperties', choosingTeamId: teamId, ...extra,
        } as GameJson['dialogParameter'];
        surfaceBlockPartial(game.value.dialogParameter as Record<string, unknown>, { readOnly: true });
      }
    },
    applyAuthoritativeFrame(command) {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          modelChangeList: { modelChangeArray: [] },
          reportList: { reports: [] },
          ...command,
          commandNr: command.commandNr ?? ++isolatedPresentationTestCommandNr,
        },
      });
    },
    applyMultiBlockDialog(extra) {
      if (game.value) {
        game.value.dialogParameter = {
          dialogId: 'reRollBlockForTargetsProperties', playerId: blockerId, ...extra,
        } as GameJson['dialogParameter'];
      }
      resolvePlayFollowups();
    },
    partial: () => state.blockPartial,
    stamp: () => state.blockResultStamp,
    multi: () => state.multiBlockResolution,
    resolve(kind, dieSelection) { gameStore.resolveBlockPartial(kind, dieSelection); },
    sendMultiHatred(targetId) { gameStore.sendMultiBlockHatred(targetId); },
    setCoach(coach) { play.coach = coach; },
    setPlaying(playing) { play.active = playing; },
    setOrder66(enabled) { settings.order66 = enabled; },
    presentationSeat: () => gameStore.blockPresentationSeat.value,
    dispose() {
      if (opponentBlockChoiceRevealTimer) cancelGameTimeout(opponentBlockChoiceRevealTimer);
      opponentBlockChoiceRevealTimer = null;
      opponentBlockChoiceRevealUntil = 0;
      followupHandled.clear();
      for (const key of priorHandled) followupHandled.add(key);
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      settings.order66 = priorOrder66;
      interactiveReRolls = priorInteractive;
      state.blockPartial = priorBlockPartial;
      state.multiBlockResolution = priorMulti;
    },
  };
}

/** @internal interception decline / chained-offer / `/stuck` integration seam (game 866 live wedge, 08-17):
 *  covers the followupHandled key-collision fix (a caught-and-returned bomb re-offers interception at the
 *  identical throwerId+target, commandNr 1957→1973 in the wire) and forceAdvanceCurrentState's missing
 *  `interception` branch (`/stuck` blindly ended the turn instead of answering the wedge). */
export function installInterceptionTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => boolean | void,
  /** Star S1: the SEAT answering. 'player' = the interceptors are mine; 'opponent' = I'm the thrower's coach;
   *  'spectator' = no seat at all (play.active false). */
  seat: 'player' | 'opponent' | 'spectator' = 'player',
): {
  /** Arms/re-arms the interception dialog with a FRESH dialogParameter object — mirrors the server pushing a
   *  genuinely new gameSetDialogParameter offer (vs. the same offer re-syncing through roll resolution).
   *  Star S1: `skill` puts the server's easy-intercept skill name on the offer (DialogInterceptionParameter's
   *  `skill` field); `grant` gives the candidate interceptor that skill on its roster entry, `used` marks it spent. */
  offer(options?: { skill?: string | null; grant?: string | null; used?: string | null }): void;
  pick(): typeof state.playerPick;
  yesNo(): typeof state.yesNo;
  answer(yes: boolean): void;
  /** The lone eligible interceptor's id (the away player placed between thrower and target). */
  candidateId: string;
  choose(playerId?: string): void;
  decline(): void;
  stuck(): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorInteractive = interactiveReRolls;
  const priorHandled = [...followupHandled];
  const priorPlayerPick = state.playerPick;
  const priorYesNo = state.yesNo;
  const priorLiveDialog = liveInterceptionDialog;
  const priorLiveCommandNr = liveInterceptionCommandNr;
  const priorElection = interceptionSkillElection;

  followupHandled.clear();
  state.playerPick = null;
  state.yesNo = null;
  liveInterceptionDialog = null;
  liveInterceptionCommandNr = 0;
  interceptionSkillElection = null;
  game.value = fixture;
  game.value.turnMode = 'regular';
  play.active = seat !== 'spectator';
  // spectator = a coach on NEITHER roster (myPlayTeam's strict non-participant result, play.active false).
  play.coach = seat === 'opponent'
    ? String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach')
    : seat === 'spectator'
      ? 'watcher-not-on-either-roster'
      : String((fixture.teamAway as { coach?: string }).coach ?? 'away-coach');
  interactiveReRolls = true;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  const throwerId = String(fixture.teamHome.playerArray[0]!.playerId);
  const candidateId = String(fixture.teamAway.playerArray[0]!.playerId);
  const from: [number, number] = [5, 5];
  const target: [number, number] = [5, 9];
  const place = (playerId: string, coordinate: [number, number]) => {
    const entry = fixture.fieldModel.playerDataArray.find((d) => d.playerId === playerId);
    if (entry) { (entry as { playerCoordinate: unknown }).playerCoordinate = coordinate; (entry as { playerState: unknown }).playerState = 1; }
  };
  place(throwerId, from);
  place(candidateId, [5, 7]); // between thrower and target — eligible interceptor

  const rosterEntry = (playerId: string) => [
    ...((fixture.teamHome as { playerArray?: { playerId: string; skillArray?: string[]; usedSkills?: string[] }[] }).playerArray ?? []),
    ...((fixture.teamAway as { playerArray?: { playerId: string; skillArray?: string[]; usedSkills?: string[] }[] }).playerArray ?? []),
  ].find((p) => p.playerId === playerId);

  return {
    offer(options?: { skill?: string | null; grant?: string | null; used?: string | null }) {
      if (!game.value) return;
      const entry = rosterEntry(candidateId);
      if (entry) {
        entry.skillArray = options?.grant ? [...new Set([...(entry.skillArray ?? []), options.grant])] : (entry.skillArray ?? []).filter((s) => s !== options?.grant);
        entry.usedSkills = options?.used ? [...new Set([...(entry.usedSkills ?? []), options.used])] : [];
      }
      game.value.throwerId = throwerId;
      game.value.passCoordinate = target;
      game.value.dialogParameter = {
        // Star S1: the offer's own `skill` field — DialogInterceptionParameter serializes the easy-intercept
        // skill under IJsonOption.SKILL ⇒ json key `skill` (the skill NAME, e.g. "Yoink!"); null otherwise.
        dialogId: 'interception', throwerId, skill: options?.skill ?? null, skillMnemonic: options?.skill ? 111 : 0,
      } as GameJson['dialogParameter'];
      lastAppliedCommandNr += 1;
      resolvePlayFollowups();
    },
    pick: () => state.playerPick,
    yesNo: () => state.yesNo,
    answer(yes: boolean) { gameStore.resolveYesNo(yes); },
    candidateId,
    choose(playerId?: string) { gameStore.resolvePlayerPick(playerId ?? candidateId); },
    decline() { gameStore.resolvePlayerPick(null); },
    stuck() { gameStore.devCommand('stuck'); },
    dispose() {
      followupHandled.clear();
      for (const key of priorHandled) followupHandled.add(key);
      liveInterceptionDialog = priorLiveDialog;
      liveInterceptionCommandNr = priorLiveCommandNr;
      interceptionSkillElection = priorElection;
      state.yesNo = priorYesNo;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      interactiveReRolls = priorInteractive;
      state.playerPick = priorPlayerPick;
    },
  };
}

/** @internal Star S2 (Quick Bite) — playerChoice seam over the production drivePregameStep path.
 *  Pins the quickBite/feed split: `feed` = the Bloodlust bite card (StepInitFeeding), `quickBite` =
 *  Guffle Pusmaw's attacker election on the generic pick rail (StepQuickBite: offered IDs are the
 *  eligible BITERS, verbatim; [] refuses). */
export function installPlayerChoiceTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => boolean | void,
  /** 'player' = the dialog's team is mine; 'headless' = same seat, bot-driven (interactiveSetup off);
   *  'opponent' = the other coach; 'spectator' = no seat. */
  seat: 'player' | 'headless' | 'opponent' | 'spectator' = 'player',
): {
  /** Arm a FRESH playerChoice offer (a new server frame: bumps the applied commandNr). */
  offer(mode: string, playerIds: string[], options?: { teamId?: string; minSelects?: number; maxSelects?: number; actingPlayerId?: string }): void;
  /** Re-run the driver over the SAME standing dialog (a frame with no dialog push). */
  resync(): void;
  bloodlustAction(playerId: string, playerAction: string): void;
  /** The server replaced/cleared the dialog — a stale pick must clear, not send. */
  replaceDialog(dialogId: string | null): void;
  /** Shape an acknowledged regular Move so the production move/end send path can be exercised. */
  prepareMove(playerId: string, destination?: [number, number]): void;
  move(playerId: string, destination?: [number, number]): void;
  end(): void;
  answered(): boolean;
  railLogs(): string[];
  pick(): typeof state.playerPick;
  bloodlust(): typeof state.bloodlust;
  /** Toggle + Confirm on the confirm-mode pick rail. */
  choose(playerId: string): void;
  toggle(playerId: string): void;
  undo(): void;
  confirm(): void;
  decline(): void;
  bite(victimId: string | null): void;
  homeTeamId: string;
  homeIds: string[];
  awayIds: string[];
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorInteractiveSetup = interactiveSetup;
  const priorHandled = [...pregameHandled];
  const priorPick = state.playerPick;
  const priorBloodlust = state.bloodlust;
  const priorCommandNr = lastAppliedCommandNr;
  const priorAnsweredKey = answeredDialogInstanceKey;
  const priorAnsweredRef = answeredDialogInstanceRef;
  const priorLogLength = state.log.length;
  const priorMoveOfferOccurrences = new Map(moveOfferOccurrences);
  const priorMoveOfferRevision = moveOfferRevision;

  pregameHandled.clear();
  clearAnsweredDialogInstance();
  state.playerPick = null;
  state.bloodlust = null;
  game.value = fixture;
  game.value.turnMode = 'regular';
  game.value.dialogParameter = null;
  play.active = seat !== 'spectator';
  play.autoPregame = true;
  play.coach = seat === 'opponent'
    ? String((fixture.teamAway as { coach?: string }).coach ?? 'away-coach')
    : seat === 'spectator'
      ? 'watcher-not-on-either-roster'
      : String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach');
  interactiveSetup = seat === 'player' || seat === 'opponent';
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  const homeTeamId = String((fixture.teamHome as { teamId?: string }).teamId ?? '');
  const ids = (team: { playerArray?: { playerId: string }[] }) => (team.playerArray ?? []).map((p) => String(p.playerId));

  return {
    offer(mode, playerIds, options) {
      if (!game.value) return;
      if (options?.actingPlayerId !== undefined)
        (game.value as { actingPlayer?: unknown }).actingPlayer = {
          ...((game.value.actingPlayer ?? {}) as Record<string, unknown>), playerId: options.actingPlayerId,
        };
      game.value.dialogParameter = {
        dialogId: 'playerChoice', teamId: options?.teamId ?? homeTeamId, playerChoiceMode: mode,
        playerIds: [...playerIds], minSelects: options?.minSelects ?? 0, maxSelects: options?.maxSelects ?? 1,
      } as GameJson['dialogParameter'];
      lastAppliedCommandNr += 1;
      drivePregameStep();
    },
    bloodlustAction(playerId, playerAction) {
      if (!game.value) return;
      game.value.actingPlayer = { ...(game.value.actingPlayer ?? {}), playerId, playerAction };
      game.value.dialogParameter = { dialogId: 'bloodlustAction', playerId, changeToMove: true } as GameJson['dialogParameter'];
      lastAppliedCommandNr += 1;
      const priorInteractive = interactiveReRolls;
      interactiveReRolls = true;
      try { resolvePlayFollowups(); } finally { interactiveReRolls = priorInteractive; }
    },
    prepareMove(playerId, destination = [2, 3]) {
      if (!game.value) return;
      game.value.homePlaying = game.value.teamHome.teamId === homeTeamId;
      game.value.actingPlayer = {
        ...game.value.actingPlayer,
        playerId,
        playerAction: 'move',
      };
      const data = game.value.fieldModel.playerDataArray.find((entry) => entry.playerId === playerId);
      if (data) {
        data.playerCoordinate = [1, 3];
        data.playerState = 0x101;
      }
      game.value.fieldModel.moveSquareArray = [{
        coordinate: destination,
        minimumRollDodge: 0,
        minimumRollGfi: 0,
      }];
      seedMoveOfferSnapshot(playerId);
    },
    move(playerId, destination = [2, 3]) { gameStore.stepMove(playerId, destination); },
    end() { gameStore.endActivation(); },
    answered: () => dialogAlreadyAnswered(),
    railLogs: () => state.log.slice(priorLogLength).map((entry) => entry.text)
      .filter((text) => text.includes('rail:')),
    resync() { drivePregameStep(); },
    replaceDialog(dialogId) {
      if (!game.value) return;
      game.value.dialogParameter = (dialogId ? { dialogId } : null) as GameJson['dialogParameter'];
      lastAppliedCommandNr += 1;
      drivePregameStep();
    },
    pick: () => state.playerPick,
    bloodlust: () => state.bloodlust,
    choose(playerId) { gameStore.resolvePlayerPick(playerId); gameStore.confirmPlayerPick(); },
    toggle(playerId) { gameStore.resolvePlayerPick(playerId); },
    undo() { gameStore.undoLastPlayerPick(); },
    confirm() { gameStore.confirmPlayerPick(); },
    decline() { gameStore.resolvePlayerPick(null); },
    bite(victimId) { gameStore.resolveBloodlustBite(victimId); },
    homeTeamId,
    homeIds: ids(fixture.teamHome as { playerArray?: { playerId: string }[] }),
    awayIds: ids(fixture.teamAway as { playerArray?: { playerId: string }[] }),
    dispose() {
      pregameHandled.clear();
      for (const key of priorHandled) pregameHandled.add(key);
      state.playerPick = priorPick;
      state.bloodlust = priorBloodlust;
      lastAppliedCommandNr = priorCommandNr;
      latchAnsweredDialogInstance(priorAnsweredKey, priorAnsweredRef);
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      interactiveSetup = priorInteractiveSetup;
      moveOfferOccurrences.clear();
      for (const [key, occurrence] of priorMoveOfferOccurrences) moveOfferOccurrences.set(key, occurrence);
      moveOfferRevision = priorMoveOfferRevision;
    },
  };
}

/** @internal Star S5 (Gored by the Bull) — the blitz block-commit election over the PRODUCTION
 *  holdBlitzBlockChoice → commitBlitzBlock path (the same hold the planner's act leg takes). `arm` shapes the
 *  server-derived inputs the offer turns on: the SELECTED target-selection, the target square's dice decoration,
 *  the blitzer's unused Gored By The Bull, and adjacency. */
export function installGoredBlitzTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => void,
  seat: 'player' | 'opponent' | 'spectator' = 'player',
): {
  blitzerId: string;
  targetId: string;
  /** Re-shape the model. Defaults = a live 2-die decorated adjacent Gored offer. */
  arm(options?: {
    grant?: boolean; used?: boolean; nrOfDice?: number; noDecoration?: boolean;
    selectedId?: string | null; selectionStatus?: string; adjacent?: boolean; defenderGrant?: string;
  }): void;
  /** The planner act-leg hold, verbatim. True = the card is up. */
  hold(): boolean;
  choice(): typeof state.blitzBlockChoice;
  commit(kind: string | null): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorHandled = [...followupHandled];
  const priorChoice = state.blitzBlockChoice;
  const priorBlockInFlight = blockInFlight;

  followupHandled.clear();
  state.blitzBlockChoice = null;
  blockInFlight = false;
  game.value = fixture;
  game.value.turnMode = 'regular';
  game.value.dialogParameter = null;
  (game.value as { homePlaying?: boolean }).homePlaying = true;
  play.active = seat !== 'spectator';
  play.coach = seat === 'opponent'
    ? String((fixture.teamAway as { coach?: string }).coach ?? 'away-coach')
    : seat === 'spectator'
      ? 'watcher-not-on-either-roster'
      : String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach');
  session = {
    send(command: Record<string, unknown>) { send(command); },
  } as unknown as GameSession;

  const blitzerId = String(fixture.teamHome.playerArray[0]!.playerId);
  const targetId = String(fixture.teamAway.playerArray[0]!.playerId);
  const rosterEntry = (playerId: string) => [
    ...((fixture.teamHome as { playerArray?: { playerId: string; skillArray?: string[]; usedSkills?: string[] }[] }).playerArray ?? []),
    ...((fixture.teamAway as { playerArray?: { playerId: string; skillArray?: string[]; usedSkills?: string[] }[] }).playerArray ?? []),
  ].find((p) => p.playerId === playerId);
  const place = (playerId: string, coordinate: [number, number]) => {
    const entry = fixture.fieldModel.playerDataArray.find((d) => d.playerId === playerId);
    if (entry) { (entry as { playerCoordinate: unknown }).playerCoordinate = coordinate; (entry as { playerState: unknown }).playerState = 1; }
  };

  return {
    blitzerId,
    targetId,
    arm(options) {
      place(blitzerId, [10, 7]);
      place(targetId, options?.adjacent === false ? [13, 7] : [11, 7]);
      const targetPos: [number, number] = options?.adjacent === false ? [13, 7] : [11, 7];
      const blitzer = rosterEntry(blitzerId);
      if (blitzer) {
        blitzer.skillArray = options?.grant === false ? [] : ['Gored By The Bull'];
        blitzer.usedSkills = options?.used ? ['Gored By The Bull'] : [];
      }
      const defender = rosterEntry(targetId);
      if (defender) {
        defender.skillArray = options?.defenderGrant ? [options.defenderGrant] : [];
        defender.usedSkills = [];
      }
      (fixture as { actingPlayer?: unknown }).actingPlayer =
        { playerId: blitzerId, playerAction: 'blitzMove', currentMove: 0 };
      const selectedId = options?.selectedId === undefined ? targetId : options.selectedId;
      (fixture.fieldModel as { targetSelectionState?: unknown }).targetSelectionState = selectedId == null
        ? null
        : { playerId: selectedId, targetSelectionStatus: options?.selectionStatus ?? 'SELECTED' };
      (fixture.fieldModel as { diceDecorationArray?: unknown[] }).diceDecorationArray = options?.noDecoration
        ? []
        : [{ coordinate: targetPos, nrOfDice: options?.nrOfDice ?? 2 }];
    },
    hold: () => holdBlitzBlockChoice(blitzerId, targetId),
    choice: () => state.blitzBlockChoice,
    commit(kind: string | null) { gameStore.commitBlitzBlock(kind); },
    dispose() {
      followupHandled.clear();
      for (const key of priorHandled) followupHandled.add(key);
      state.blitzBlockChoice = priorChoice;
      blockInFlight = priorBlockInFlight;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
    },
  };
}

/** @internal Star S4 — seats the generic registry-mounted use-skill sender over a fixture (wire assertion only;
 *  the offer surface is pure availableActions and tested there). */
export function installStarUseSkillTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => void,
  seat: 'player' | 'opponent' | 'spectator' | 'replay' = 'player',
): { use(ruleId: string, skillUsed?: boolean): void; toggleIncorporeal(): void; dispose(): void } {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  game.value = fixture;
  play.active = seat === 'player' || seat === 'opponent';
  const actingId = String(fixture.actingPlayer?.playerId ?? '');
  const actingTeam = fixture.teamHome.playerArray.some((player) => player.playerId === actingId)
    ? fixture.teamHome
    : fixture.teamAway;
  const otherTeam = actingTeam === fixture.teamHome ? fixture.teamAway : fixture.teamHome;
  play.coach = seat === 'player'
    ? String((actingTeam as { coach?: string }).coach ?? 'acting-coach')
    : seat === 'opponent'
      ? String((otherTeam as { coach?: string }).coach ?? 'opponent-coach')
      : 'watcher-not-on-either-roster';
  session = { send } as unknown as GameSession;
  return {
    use(ruleId: string, skillUsed = true) { gameStore.useStarSkill(ruleId, skillUsed); },
    toggleIncorporeal() { gameStore.toggleIncorporeal(); },
    dispose() {
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
    },
  };
}

/** @internal Owner 08-20 — production declare/model-ack/property-map seam for activation-menu specials. */
export function installWideRailActivationTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => void,
  seat: 'player' | 'opponent' | 'spectator' = 'player',
): {
  declare(playerId: string, playerAction: string): void;
  ack(playerId: string | null, playerAction?: string | null): void;
  ackActionOnly(playerAction: string | null): void;
  terminal(): void;
  options(): ReturnType<typeof wideRailActivationOptions>;
  election(targetId?: string): ReturnType<typeof gameStore.wideRailActivationElection>;
  use(ruleId: WideRailPreActionRuleId, expectedPlayerId?: string, expectedPlayerAction?: string, expectedSeq?: number): void;
  dismiss(expectedPlayerId?: string, expectedPlayerAction?: string, expectedSeq?: number): void;
  legacyRaidingParty(): void;
  legacyStarRule(ruleId: string): void;
  legacyTargetRule(ruleId: 'catchOfTheDay' | 'blackInk' | 'frenziedRush' | 'slashingNails'): void;
  raidingPlayerOffer(playerIds: string[], squares: [number, number][]): void;
  playerPick(): typeof state.playerPick;
  choosePlayer(playerId: string): void;
  coordinateOffer(turnMode: string, squares: [number, number][], preserveDialog?: boolean): void;
  squarePick(): typeof state.squarePick;
  chooseCoordinate(square: [number, number]): void;
  resolveDeferredWideRail(): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorSrvId = srvActingId;
  const priorSrvAction = srvActingAction;
  const priorPendingWideRailDeclare = pendingWideRailDeclare;
  const priorAcknowledgedWideRailDeclare = acknowledgedWideRailDeclare;
  const priorCompletedWideRailDeclare = completedWideRailDeclare;
  const priorDeferredStandUpWideRail = deferredStandUpWideRail;
  const priorInteractiveSetup = interactiveSetup;
  const priorPregameHandled = [...pregameHandled];
  const priorAnsweredKey = answeredDialogInstanceKey;
  const priorAnsweredRef = answeredDialogInstanceRef;
  const priorPlayerPick = state.playerPick;
  const priorSquarePick = state.squarePick;
  const priorPendingRailCommands = new Map(pendingRailCommands);
  game.value = fixture;
  play.active = seat !== 'spectator';
  play.coach = seat === 'player'
    ? String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach')
    : seat === 'opponent'
      ? String((fixture.teamAway as { coach?: string }).coach ?? 'away-coach')
      : 'watcher-not-on-either-roster';
  srvActingId = null;
  srvActingAction = null;
  pendingWideRailDeclare = null;
  acknowledgedWideRailDeclare = null;
  completedWideRailDeclare = null;
  deferredStandUpWideRail = null;
  interactiveSetup = seat !== 'spectator';
  pregameHandled.clear();
  clearAnsweredDialogInstance();
  state.playerPick = null;
  state.squarePick = null;
  clearPendingRailCommands();
  session = { send } as unknown as GameSession;
  return {
    declare(playerId, playerAction) { gameStore.declareAction(playerId, playerAction); },
    ack(playerId, playerAction = null) {
      const priorActing = fixture.actingPlayer as { playerStateOld?: number | null; currentMove?: number } | null;
      const receivedOldState = priorActing?.playerStateOld
        ?? fixture.fieldModel.playerDataArray.find((player) => player.playerId === playerId)?.playerState
        ?? null;
      fixture.actingPlayer = {
        ...(fixture.actingPlayer ?? {}), playerId, playerAction,
        playerStateOld: receivedOldState,
        currentMove: Number(priorActing?.currentMove ?? 0),
      } as GameJson['actingPlayer'];
      trackActingPlayer({
        modelChangeList: { modelChangeArray: [
          { modelChangeId: 'actingPlayerSetPlayerId', modelChangeValue: playerId },
          { modelChangeId: 'actingPlayerSetPlayerAction', modelChangeValue: playerAction },
        ] },
      });
      advanceDeferredStandUpWideRail();
    },
    ackActionOnly(playerAction) {
      fixture.actingPlayer = {
        ...(fixture.actingPlayer ?? {}), playerAction,
        currentMove: Number((fixture.actingPlayer as { currentMove?: number } | null)?.currentMove ?? 0),
      } as GameJson['actingPlayer'];
      trackActingPlayer({
        modelChangeList: { modelChangeArray: [
          { modelChangeId: 'actingPlayerSetPlayerAction', modelChangeValue: playerAction },
        ] },
      });
    },
    terminal() {
      trackActingPlayer({
        modelChangeList: { modelChangeArray: [
          { modelChangeId: 'gameSetTurnMode', modelChangeValue: 'betweenTurns' },
        ] },
      });
    },
    options() {
      return gameStore.wideRailActivationOptions();
    },
    election(targetId) {
      return gameStore.wideRailActivationElection(targetId);
    },
    use(ruleId, expectedPlayerId, expectedPlayerAction, expectedSeq) {
      gameStore.useWideRailActivationRule(ruleId, expectedPlayerId, expectedPlayerAction, expectedSeq);
    },
    dismiss(expectedPlayerId, expectedPlayerAction, expectedSeq) {
      gameStore.dismissWideRailActivationRules(expectedPlayerId, expectedPlayerAction, expectedSeq);
    },
    legacyRaidingParty() { gameStore.useRaidingParty(); },
    legacyStarRule(ruleId) { gameStore.useStarSkill(ruleId); },
    legacyTargetRule(ruleId) {
      if (ruleId === 'catchOfTheDay') gameStore.useCatchOfTheDay();
      else if (ruleId === 'blackInk') gameStore.useBlackInk();
      else if (ruleId === 'frenziedRush') gameStore.useFrenziedRush();
      else gameStore.useSlashingNails();
    },
    raidingPlayerOffer(playerIds, squares) {
      fixture.turnMode = 'raidingParty';
      fixture.dialogParameter = {
        dialogId: 'playerChoice',
        teamId: fixture.teamHome.teamId,
        playerChoiceMode: 'raidingParty',
        playerIds: [...playerIds],
        minSelects: 0,
        maxSelects: 1,
      } as GameJson['dialogParameter'];
      fixture.fieldModel.moveSquareArray = squares.map((coordinate) => ({ coordinate }));
      drivePregameStep();
      armServerCoordinatePicks();
    },
    playerPick: () => state.playerPick,
    choosePlayer(playerId) {
      gameStore.resolvePlayerPick(playerId);
      gameStore.confirmPlayerPick();
    },
    coordinateOffer(turnMode, squares, preserveDialog = false) {
      fixture.turnMode = turnMode;
      if (!preserveDialog) fixture.dialogParameter = null;
      fixture.fieldModel.moveSquareArray = squares.map((coordinate) => ({ coordinate }));
      armServerCoordinatePicks();
    },
    squarePick: () => state.squarePick,
    chooseCoordinate(square) { gameStore.resolveSquarePick(square); },
    resolveDeferredWideRail() {
      fixture.turnMode = 'regular';
      fixture.dialogParameter = null;
      fixture.fieldModel.moveSquareArray = [];
      advanceDeferredStandUpWideRail();
    },
    dispose() {
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      srvActingId = priorSrvId;
      srvActingAction = priorSrvAction;
      pendingWideRailDeclare = priorPendingWideRailDeclare;
      acknowledgedWideRailDeclare = priorAcknowledgedWideRailDeclare;
      completedWideRailDeclare = priorCompletedWideRailDeclare;
      deferredStandUpWideRail = priorDeferredStandUpWideRail;
      interactiveSetup = priorInteractiveSetup;
      pregameHandled.clear();
      for (const key of priorPregameHandled) pregameHandled.add(key);
      clearAnsweredDialogInstance();
      if (priorAnsweredKey) latchAnsweredDialogInstance(priorAnsweredKey, priorAnsweredRef);
      state.playerPick = priorPlayerPick;
      state.squarePick = priorSquarePick;
      clearPendingRailCommands();
      for (const [rail, pending] of priorPendingRailCommands) pendingRailCommands.set(rail, pending);
    },
  };
}

/** @internal Star S7 — seats declareAction over a fixture for the composite/paired wire assertions.
 *  `declare` pre-seeds the receive-time acting mirror to the expected wire action so whenActingPlayerAcked's
 *  immediate tick fires synchronously (the pair ORDER, not the ack pacing, is under test). */
export function installStarDeclareTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => void,
  seat: 'player' | 'spectator' = 'player',
): {
  declare(playerId: string, action: string, expectedWireAction: string): void;
  declareWithoutAck(playerId: string, action: string): void;
  ack(playerId: string, playerAction: string): void;
  seedReconnect(): void;
  choice(): typeof state.skillChoice;
  answer(use: boolean): void;
  attempt(command: Record<string, unknown>): boolean;
  wideElection(): ReturnType<typeof gameStore.wideRailActivationElection>;
  wideUse(ruleId: WideRailPreActionRuleId): void;
  setInteractive(on: boolean): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorSrvId = srvActingId;
  const priorSrvAction = srvActingAction;
  const priorOrder66 = settings.order66;
  const priorInteractive = interactiveReRolls;
  const priorPendingWideRailDeclare = pendingWideRailDeclare;
  const priorAcknowledgedWideRailDeclare = acknowledgedWideRailDeclare;
  const priorCompletedWideRailDeclare = completedWideRailDeclare;
  const priorPendingShotToNothingDeclare = pendingShotToNothingDeclare;
  const priorAcknowledgedShotToNothingDeclare = acknowledgedShotToNothingDeclare;
  const priorSkillChoice = state.skillChoice;
  game.value = fixture;
  play.active = seat === 'player';
  play.coach = seat === 'player'
    ? String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach')
    : 'watcher-not-on-either-roster';
  session = { send } as unknown as GameSession;
  settings.order66 = true;
  interactiveReRolls = true;
  return {
    declare(playerId: string, action: string, expectedWireAction: string) {
      srvActingId = playerId;
      srvActingAction = expectedWireAction;
      gameStore.declareAction(playerId, action);
    },
    declareWithoutAck(playerId: string, action: string) {
      srvActingId = null;
      srvActingAction = null;
      gameStore.declareAction(playerId, action);
    },
    ack(playerId: string, playerAction: string) {
      fixture.actingPlayer = {
        ...(fixture.actingPlayer ?? {}), playerId, playerAction,
        currentMove: Number((fixture.actingPlayer as { currentMove?: number } | null)?.currentMove ?? 0),
      } as GameJson['actingPlayer'];
      trackActingPlayer({ modelChangeList: { modelChangeArray: [
        { modelChangeId: 'actingPlayerSetPlayerId', modelChangeValue: playerId },
        { modelChangeId: 'actingPlayerSetPlayerAction', modelChangeValue: playerAction },
      ] } });
    },
    seedReconnect() { seedActingPlayer(fixture); },
    choice: () => state.skillChoice,
    answer(use: boolean) { gameStore.resolveSkillUse(use); },
    attempt(command) { return sendCommand(command); },
    wideElection: () => gameStore.wideRailActivationElection(),
    wideUse(ruleId) { gameStore.useWideRailActivationRule(ruleId); },
    setInteractive(on) { interactiveReRolls = on; },
    dispose() {
      srvActingId = priorSrvId;
      srvActingAction = priorSrvAction;
      pendingWideRailDeclare = priorPendingWideRailDeclare;
      acknowledgedWideRailDeclare = priorAcknowledgedWideRailDeclare;
      completedWideRailDeclare = priorCompletedWideRailDeclare;
      pendingShotToNothingDeclare = priorPendingShotToNothingDeclare;
      acknowledgedShotToNothingDeclare = priorAcknowledgedShotToNothingDeclare;
      state.skillChoice = priorSkillChoice;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      settings.order66 = priorOrder66;
      interactiveReRolls = priorInteractive;
    },
  };
}

/** @internal Star S8 — seats the terminal-trio senders over a fixture (wire assertions only; offers/routing are
 *  pure availableActions/order66Interaction and tested there). Same seat semantics as the S4 harness. */
export function installStarTerminalTrioTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => void,
  seat: 'player' | 'home' | 'away' | 'spectator' | 'replay' = 'player',
): {
  declare(playerId: string, playerAction: string): void;
  kickEm(defenderId: string): void;
  blitzStep(playerId: string, square: [number, number]): void;
  ordinaryBlock(attackerId: string, defenderId: string): void;
  blastin(targetId: string): void;
  square(playerId: string, square: [number, number]): void;
  switchFriendly(playerId: string, disposition: FriendlyActivationSwitchDisposition): boolean;
  end(blitzConfirmed?: boolean): void;
  playerEndTurn(): void;
  sync(): void;
  choose(playerId: string): void;
  clickNominated(playerId: string): boolean;
  answerConfirm(yes: boolean): void;
  setSeat(seat: 'player' | 'home' | 'away' | 'spectator' | 'replay'): void;
  reconnect(): void;
  setCatchingUp(catchingUp: boolean): void;
  playerPick(): typeof state.playerPick;
  target(): typeof state.kickEmBlitzTarget;
  yesNo(): typeof state.yesNo;
  actionNotice(): typeof state.actionNotice;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorSrvActingId = srvActingId;
  const priorOrder66 = settings.order66;
  const priorInteractiveSetup = interactiveSetup;
  const priorDemoMode = state.demoMode;
  const priorReplayActive = replay.active;
  const priorCatchingUp = playback.catchingUp;
  const priorHandledOccurrence = kickEmBlitzTargetHandledOccurrence;
  const priorKickEmTarget = state.kickEmBlitzTarget;
  const priorPick = state.playerPick;
  const priorPlayerPickResolver = playerPickResolver;
  const priorYesNo = state.yesNo;
  const priorYesNoResolver = yesNoResolver;
  const priorActionNotice = state.actionNotice;
  const priorMoveOfferRevision = moveOfferRevision;
  const priorMoveOfferOccurrences = new Map(moveOfferOccurrences);
  const priorEndTurnInFlight = endTurnInFlight;
  const priorEndTurnInFlightTurnKey = endTurnInFlightTurnKey;
  game.value = fixture;
  let currentSeat = seat;
  const applySeat = () => {
    const home = currentSeat === 'player' || currentSeat === 'home';
    const away = currentSeat === 'away';
    play.active = home || away;
    play.coach = home
      ? String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach')
      : away
        ? String((fixture.teamAway as { coach?: string }).coach ?? 'away-coach')
        : 'watcher-not-on-either-roster';
    state.demoMode = currentSeat === 'replay';
    replay.active = currentSeat === 'replay';
    interactiveSetup = play.active;
  };
  applySeat();
  srvActingId = null; // clean slate: declares fire immediately (whenPriorActivationEnded fast path)
  settings.order66 = true;
  clearPlayerPick();
  clearYesNo();
  kickEmBlitzTargetHandledOccurrence = null;
  state.kickEmBlitzTarget = null;
  endTurnInFlight = false;
  endTurnInFlightTurnKey = null;
  seedMoveOfferSnapshot();
  session = { send } as unknown as GameSession;
  return {
    declare(playerId: string, playerAction: string) { gameStore.declareAction(playerId, playerAction); },
    kickEm(defenderId: string) { gameStore.sendKickEmBlock(defenderId); },
    blitzStep(playerId: string, square: [number, number]) { gameStore.sendBlitzMove(playerId, square); },
    ordinaryBlock(attackerId: string, defenderId: string) { gameStore.sendBlock(attackerId, defenderId); },
    blastin(targetId: string) { gameStore.sendBlastinTarget(targetId); },
    square(playerId: string, square: [number, number]) { gameStore.sendFieldCoordinate(playerId, square); },
    switchFriendly(playerId, disposition) { return gameStore.switchFriendlyActivation(playerId, disposition); },
    end(blitzConfirmed = false) { gameStore.endActivation({ blitzConfirmed }); },
    playerEndTurn() { gameStore.playerEndTurn(); },
    sync() { resolvePlayFollowups(); syncKickEmTargetRail(); },
    choose(playerId: string) { gameStore.resolvePlayerPick(playerId); },
    clickNominated(playerId: string) { return gameStore.requestKickEmBlitzBlock(playerId); },
    answerConfirm(yes: boolean) { gameStore.resolveYesNo(yes); },
    setSeat(nextSeat) { currentSeat = nextSeat; applySeat(); clearPlayerPick(); state.kickEmBlitzTarget = null; clearYesNo(); syncKickEmTargetRail(); },
    reconnect() { clearPlayerPick(); state.kickEmBlitzTarget = null; clearYesNo(); kickEmBlitzTargetHandledOccurrence = null; syncKickEmTargetRail(); },
    setCatchingUp(catchingUp: boolean) { playback.catchingUp = catchingUp; syncKickEmTargetRail(); },
    playerPick: () => state.playerPick,
    target: () => state.kickEmBlitzTarget,
    yesNo: () => state.yesNo,
    actionNotice: () => state.actionNotice,
    dispose() {
      clearPlayerPick();
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      srvActingId = priorSrvActingId;
      settings.order66 = priorOrder66;
      interactiveSetup = priorInteractiveSetup;
      state.demoMode = priorDemoMode;
      replay.active = priorReplayActive;
      playback.catchingUp = priorCatchingUp;
      kickEmBlitzTargetHandledOccurrence = priorHandledOccurrence;
      state.kickEmBlitzTarget = priorKickEmTarget;
      state.playerPick = priorPick;
      playerPickResolver = priorPlayerPickResolver;
      state.yesNo = priorYesNo;
      yesNoResolver = priorYesNoResolver;
      state.actionNotice = priorActionNotice;
      moveOfferRevision = priorMoveOfferRevision;
      moveOfferOccurrences.clear();
      for (const [key, occurrence] of priorMoveOfferOccurrences) moveOfferOccurrences.set(key, occurrence);
      endTurnInFlight = priorEndTurnInFlight;
      endTurnInFlightTurnKey = priorEndTurnInFlightTurnKey;
    },
  };
}


/** @internal Owner 08-18 (game 870 P1) re-roll-offer seam, over the PRODUCTION applyFrame → resolvePlayFollowups →
 *  surfaceReRollPrompt path. `sync` replays a literal server frame (modelChanges + reports) so the test controls
 *  the ONE thing the offer's identity turns on: whether the frame carries a `gameSetDialogParameter` push. A frame
 *  without one leaves the SAME dialogParameter object standing — exactly how the fork server resolves a Direction
 *  re-roll — and that is what must NOT be mistaken for a new offer. Legacy (non-o66) reroll dispatch so the seat
 *  test is `ownedReroll`, not a deriveReaction fixture. */
export function installReRollOfferTestHarness(fixture: GameJson, send: (command: Record<string, unknown>) => void): {
  sync(changes: ModelChangeListJson['modelChangeArray'], reports?: Record<string, unknown>[]): void;
  prompt(): typeof state.reRollPrompt;
  skillChoice(): typeof state.skillChoice;
  primalIntent(): { playerId: string; skillUsed: boolean } | null;
  scatterSeq(): number;
  answer(source: string | null): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorInteractive = interactiveReRolls;
  const priorHandled = [...followupHandled];
  const priorPrompt = state.reRollPrompt;
  const priorSkillChoice = state.skillChoice;
  const priorPrimalIntent = primalSavageryIntent;
  const priorAnsweredSkills = answeredSkillDialog;
  const priorScatter = state.bncScatter;
  const priorOrder66 = settings.order66;
  const priorLiveDialog = liveReRollDialog;
  const priorEpoch = liveReRollOfferEpoch;

  followupHandled.clear();
  state.reRollPrompt = null;
  state.skillChoice = null;
  primalSavageryIntent = null;
  answeredSkillDialog = null;
  state.bncScatter = null;
  liveReRollDialog = null;
  liveReRollOfferEpoch = 0;
  game.value = fixture;
  game.value.turnMode = 'regular';
  settings.order66 = false;
  play.active = true;
  play.coach = String((fixture.teamAway as { coach?: string }).coach ?? 'away-coach');
  interactiveReRolls = true;
  session = {
    send(command: Record<string, unknown>) { send(command); },
  } as unknown as GameSession;

  let nr = 0;
  return {
    sync(changes, reports = []) {
      nr += 1;
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr: nr,
          modelChangeList: { modelChangeArray: changes },
          reportList: { reports },
        },
      });
      resolvePlayFollowups();
    },
    prompt: () => state.reRollPrompt,
    skillChoice: () => state.skillChoice,
    primalIntent: () => primalSavageryIntent
      ? { playerId: primalSavageryIntent.playerId, skillUsed: primalSavageryIntent.skillUsed }
      : null,
    scatterSeq: () => state.bncScatter?.seq ?? 0,
    answer(source) { gameStore.resolveReRoll(source); },
    dispose() {
      followupHandled.clear();
      for (const key of priorHandled) followupHandled.add(key);
      liveReRollDialog = priorLiveDialog;
      liveReRollOfferEpoch = priorEpoch;
      state.reRollPrompt = priorPrompt;
      state.skillChoice = priorSkillChoice;
      primalSavageryIntent = priorPrimalIntent;
      answeredSkillDialog = priorAnsweredSkills;
      state.bncScatter = priorScatter;
      settings.order66 = priorOrder66;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      interactiveReRolls = priorInteractive;
    },
  };
}

/** @internal Production integration seam for the Pass-plan pickup/reroll transaction. It deliberately applies
 * literal model-sync frames through applyFrame and uses the real reroll resolver, planner, outgoing shadow, and
 * Move ownership projection. The test owns the fake clock; this seam exposes no alternate scheduling logic. */
export function installPassPickupReRollPlannerTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => boolean | void,
): {
  startPass(playerId: string, route: [number, number][]): boolean;
  apply(changes: ModelChangeListJson['modelChangeArray'], reports?: Record<string, unknown>[]): void;
  answer(source: string | null): void;
  prompt(): typeof state.reRollPrompt;
  answered(): boolean;
  active(): boolean;
  sentIndex(): number | null;
  step(playerId: string, square: [number, number]): boolean;
  yesNo(): typeof state.yesNo;
  answerYesNo(yes: boolean): void;
  railLogs(): string[];
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorOrder66 = settings.order66;
  const priorInteractiveSetup = interactiveSetup;
  const priorInteractiveReRolls = interactiveReRolls;
  const priorPrompt = state.reRollPrompt;
  const priorHandled = [...followupHandled];
  const priorAnsweredKey = answeredDialogInstanceKey;
  const priorAnsweredRef = answeredDialogInstanceRef;
  const priorLiveDialog = liveReRollDialog;
  const priorLiveEpoch = liveReRollOfferEpoch;
  const priorCommandNr = lastAppliedCommandNr;
  const priorLogLength = state.log.length;
  const priorMoveOfferOccurrences = new Map(moveOfferOccurrences);
  const priorMoveOfferRevision = moveOfferRevision;

  resetPresentation();
  plannerClearAbort();
  plannerSet(null);
  clearAnsweredDialogInstance();
  followupHandled.clear();
  state.reRollPrompt = null;
  liveReRollDialog = null;
  liveReRollOfferEpoch = 0;
  game.value = fixture;
  game.value.turnMode = 'regular';
  play.active = true;
  play.coach = String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach');
  settings.order66 = true;
  interactiveSetup = false;
  interactiveReRolls = true;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;
  seedMoveOfferSnapshot();

  let commandNr = 0;
  return {
    startPass: (playerId, route) => plannerStart({ playerId, actKind: 'pass', route }),
    apply(changes, reports = []) {
      commandNr += 1;
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr,
          modelChangeList: { modelChangeArray: changes },
          reportList: { reports },
        },
      });
    },
    answer(source) { gameStore.resolveReRoll(source); },
    prompt: () => state.reRollPrompt,
    answered: () => dialogAlreadyAnswered(),
    active: plannerActive,
    sentIndex: () => plannerPlan?.sentIdx ?? null,
    step: (playerId, square) => gameStore.stepMove(playerId, square),
    yesNo: () => state.yesNo,
    answerYesNo: (yes) => gameStore.resolveYesNo(yes),
    railLogs: () => state.log.slice(priorLogLength).map((entry) => entry.text)
      .filter((entry) => entry.includes('rail:')),
    dispose() {
      resetPresentation();
      plannerClearAbort();
      plannerSet(null);
      clearAnsweredDialogInstance();
      if (priorAnsweredKey) latchAnsweredDialogInstance(priorAnsweredKey, priorAnsweredRef);
      followupHandled.clear();
      for (const key of priorHandled) followupHandled.add(key);
      state.reRollPrompt = priorPrompt;
      liveReRollDialog = priorLiveDialog;
      liveReRollOfferEpoch = priorLiveEpoch;
      lastAppliedCommandNr = priorCommandNr;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      settings.order66 = priorOrder66;
      interactiveSetup = priorInteractiveSetup;
      interactiveReRolls = priorInteractiveReRolls;
      moveOfferOccurrences.clear();
      for (const [key, occurrence] of priorMoveOfferOccurrences) moveOfferOccurrences.set(key, occurrence);
      moveOfferRevision = priorMoveOfferRevision;
    },
  };
}

/** @internal SERVER_ADD_PLAYER integration seam over the production receive/apply/send paths. */
export function installServerAddPlayerTestHarness(
  fixture: GameJson,
  mode: 'player' | 'spectator',
  send: (command: Record<string, unknown>) => boolean | void,
): {
  mount(surface: 'modern' | 'classic'): void;
  receive(command: Record<string, unknown>): void;
  applyModelChanges(changes: ModelChangeListJson['modelChangeArray'], commandNr: number, reports?: Record<string, unknown>[]): void;
  setup(): typeof state.setupPhase;
  place(playerId: string, coordinate: [number, number]): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorUiMode = settings.uiMode;
  const priorInteractiveSetup = interactiveSetup;
  const priorFastPregame = fastPregame;
  const priorSetup = state.setupPhase;
  const priorPuff = state.addPlayerPuff;

  game.value = fixture;
  play.active = mode === 'player';
  play.coach = mode === 'player' ? String((fixture.teamHome as { coach?: string }).coach ?? '') : '';
  play.autoPregame = true;
  interactiveSetup = false;
  fastPregame = false;
  state.setupPhase = null;
  state.addPlayerPuff = null;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  return {
    mount(surface) {
      settings.uiMode = surface === 'classic' ? 'classic' : 'fumbbl40k';
      interactiveSetup = mode === 'player';
    },
    receive: handleServerPush,
    applyModelChanges(changes, commandNr, reports) {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr,
          modelChangeList: { modelChangeArray: changes },
          reportList: { reports: reports ?? [] },
        },
      });
      if (play.active) drivePregameStep();
    },
    setup: () => state.setupPhase,
    place: (playerId, coordinate) => gameStore.setupPlace(playerId, coordinate),
    dispose() {
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      settings.uiMode = priorUiMode;
      interactiveSetup = priorInteractiveSetup;
      fastPregame = priorFastPregame;
      state.setupPhase = priorSetup;
      state.addPlayerPuff = priorPuff;
    },
  };
}

/** @internal SetupError recovery seam over production model apply, setup projection, action lock and senders. */
export function installSetupErrorRecoveryTestHarness(
  fixture: GameJson,
  seat: 'home' | 'away' | 'spectator',
  send: (command: Record<string, unknown>) => boolean | void,
): {
  mount(surface: 'modern' | 'classic'): void;
  apply(command: Record<string, unknown>): void;
  setup(): typeof state.setupPhase;
  swarming(): typeof state.swarmingPhase;
  remove(playerId: string): void;
  submit(): void;
  swarmPlace(playerId: string, coordinate: [number, number]): void;
  swarmSubmit(): void;
  attempt(command: Record<string, unknown>): boolean;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorUiMode = settings.uiMode;
  const priorInteractiveSetup = interactiveSetup;
  const priorFastPregame = fastPregame;
  const priorSetup = state.setupPhase;
  const priorSwarming = state.swarmingPhase;
  const priorHandled = [...pregameHandled];
  const priorAnsweredKey = answeredDialogInstanceKey;
  const priorAnsweredRef = answeredDialogInstanceRef;
  const priorCommandNr = lastAppliedCommandNr;

  pregameHandled.clear();
  clearAnsweredDialogInstance();
  lastAppliedCommandNr = 0;
  game.value = fixture;
  play.active = seat !== 'spectator';
  play.coach = seat === 'home'
    ? String((fixture.teamHome as { coach?: string }).coach ?? '')
    : seat === 'away'
      ? String((fixture.teamAway as { coach?: string }).coach ?? '')
      : 'setup-recovery-spectator';
  play.autoPregame = true;
  interactiveSetup = seat !== 'spectator';
  fastPregame = false;
  state.setupPhase = null;
  state.swarmingPhase = null;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  return {
    mount(surface) {
      settings.uiMode = surface === 'classic' ? 'classic' : 'fumbbl40k';
      if (play.active) {
        drivePregameStep();
        if (game.value && interactiveSetup) computeSwarmingPhase(game.value);
      }
    },
    apply(command) {
      applyFrame({ receivedAt: Date.now(), cmd: command });
      if (play.active) {
        drivePregameStep();
        if (game.value && interactiveSetup) computeSwarmingPhase(game.value);
      }
    },
    setup: () => state.setupPhase,
    swarming: () => state.swarmingPhase,
    remove: (playerId) => gameStore.setupRemove(playerId),
    submit: () => gameStore.setupSubmit(),
    swarmPlace: (playerId, coordinate) => gameStore.swarmingPlace(playerId, coordinate),
    swarmSubmit: () => gameStore.swarmingConfirm(),
    attempt: (command) => sendCommand(command),
    dispose() {
      clearSetupLoop();
      pregameHandled.clear();
      for (const key of priorHandled) pregameHandled.add(key);
      clearAnsweredDialogInstance();
      if (priorAnsweredKey) latchAnsweredDialogInstance(priorAnsweredKey, priorAnsweredRef);
      lastAppliedCommandNr = priorCommandNr;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      settings.uiMode = priorUiMode;
      interactiveSetup = priorInteractiveSetup;
      fastPregame = priorFastPregame;
      state.setupPhase = priorSetup;
      state.swarmingPhase = priorSwarming;
    },
  };
}

/** @internal Star S3 (I'll Carry You) wire seam: send-capturing session over a crafted fixture, driving the
 *  REAL dialog handler (drivePregameStep 'playerChoice') and the REAL server-square arm
 *  (armServerCoordinatePicks) so tests assert the exact election/choice/placement commands. */
export function installIllCarryYouTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => boolean | void,
  /** 'player' = the home coach (craft acting players from teamHome); 'opponent' = away coach; 'spectator' = no seat. */
  seat: 'player' | 'opponent' | 'spectator' = 'player',
): {
  /** Replace dialogParameter with a FRESH object and run the production dialog driver. */
  dialog(dp: Record<string, unknown> | null): void;
  /** Re-derive the server coordinate picks (the placement beat's arm). */
  syncSquares(): void;
  pick(): typeof state.playerPick;
  squarePick(): typeof state.squarePick;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorInteractiveSetup = interactiveSetup;
  const priorFastPregame = fastPregame;
  const priorHandled = [...pregameHandled];
  const priorPlayerPick = state.playerPick;
  const priorSquarePick = state.squarePick;

  pregameHandled.clear();
  state.playerPick = null;
  state.squarePick = null;
  game.value = fixture;
  play.active = seat !== 'spectator';
  play.autoPregame = true;
  play.coach = seat === 'player'
    ? String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach')
    : seat === 'opponent'
      ? String((fixture.teamAway as { coach?: string }).coach ?? 'away-coach')
      : 'watcher-not-on-either-roster';
  interactiveSetup = true;
  fastPregame = false;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  return {
    dialog(dp) {
      if (!game.value) return;
      game.value.dialogParameter = (dp ? structuredClone(dp) : null) as GameJson['dialogParameter'];
      drivePregameStep();
    },
    syncSquares: () => armServerCoordinatePicks(),
    pick: () => state.playerPick,
    squarePick: () => state.squarePick,
    dispose() {
      pregameHandled.clear();
      for (const key of priorHandled) pregameHandled.add(key);
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      interactiveSetup = priorInteractiveSetup;
      fastPregame = priorFastPregame;
      state.playerPick = priorPlayerPick;
      state.squarePick = priorSquarePick;
    },
  };
}

/** @internal wizard-window fix test seam: feed raw serverModelSync model-change/report batches through the
 *  production applyFrame path and read back the turn-start splash / "Turn <N>" toast surfaces. */
export function installTurnPresentationTestHarness(fixture: GameJson): {
  applyModelChanges(
    changes: ModelChangeListJson['modelChangeArray'],
    reports?: Record<string, unknown>[],
    commandNr?: number,
  ): void;
  turnStart(): typeof state.turnStart;
  turnToast(): typeof state.turnToast;
  turnover(): typeof state.turnover;
  ttmRailTerminal(): typeof state.ttmRailTerminal;
  setLivePlayer(active: boolean, catchingUp?: boolean): void;
  /** Owner 08-18 rocking-boundary probe: the SETTLED playing side + the acted set it scopes. */
  playingIsHome(): boolean;
  actedPlayers(): string[];
  gazeVictims(): string[];
  resetGame(): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorTurnStart = state.turnStart;
  const priorTurnToast = state.turnToast;
  const priorTurnover = state.turnover;
  const priorTtmRailTerminal = state.ttmRailTerminal;
  const priorPlayActive = play.active;
  const priorCatchingUp = playback.catchingUp;
  const priorTurnToastKey = turnToastKey;
  const priorTurnoverArmed = turnoverArmed;
  const priorTurnoverArmedAfterInjury = turnoverArmedAfterInjury;
  game.value = fixture;
  state.turnStart = null;
  state.turnToast = null;
  state.turnover = null;
  state.ttmRailTerminal = null;
  turnToastKey = '';
  turnoverArmed = false;
  turnoverArmedAfterInjury = false;
  const priorSettled = settledPlayingIsHome;
  const priorActed = state.actedPlayers;
  const priorGazeVictims = state.gazeVictims;
  const priorGazeVictimIds = [...gazeVictimIds];
  settledPlayingIsHome = null; // the fixture's own first frame settles it
  let nr = 0;
  return {
    applyModelChanges(changes, reports = [], commandNr) {
      nr = commandNr ?? nr + 1;
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr: nr,
          modelChangeList: { modelChangeArray: changes },
          reportList: { reports },
        },
      });
    },
    turnStart: () => state.turnStart,
    turnToast: () => state.turnToast,
    turnover: () => state.turnover,
    ttmRailTerminal: () => state.ttmRailTerminal,
    setLivePlayer(active, catchingUp = false) { play.active = active; playback.catchingUp = catchingUp; },
    playingIsHome: () => state.playingIsHome,
    actedPlayers: () => [...state.actedPlayers],
    gazeVictims: () => [...state.gazeVictims],
    resetGame() { resetPlayback(); },
    dispose() {
      game.value = priorGame;
      state.turnStart = priorTurnStart;
      state.turnToast = priorTurnToast;
      state.turnover = priorTurnover;
      state.ttmRailTerminal = priorTtmRailTerminal;
      play.active = priorPlayActive;
      playback.catchingUp = priorCatchingUp;
      turnToastKey = priorTurnToastKey;
      settledPlayingIsHome = priorSettled;
      state.actedPlayers = priorActed;
      state.gazeVictims = priorGazeVictims;
      gazeVictimIds.clear();
      for (const playerId of priorGazeVictimIds) gazeVictimIds.add(playerId);
      turnoverArmed = priorTurnoverArmed;
      turnoverArmedAfterInjury = priorTurnoverArmedAfterInjury;
    },
  };
}

/** @internal row-teleport (owner 08-18 P1) seam over the PRODUCTION #67 run ledger: enqueue movement steps through
 *  enqueueMoveStep, fire the real drain-idle path (`drainIdle` = pumpPresentation's own `finally` body) to simulate
 *  the transient FIFO empty the wire cadence creates between tiles, and read back the dispatch surface the renderer
 *  consumes. No fixture/model needed — the drain's contiguity ledger is model-independent by construction (DD-1). */
export function installPresentationRunTestHarness(): {
  step(playerId: string, from: [number, number], to: [number, number]): void;
  stepWithUsage(playerId: string, from: [number, number], to: [number, number], before: number, after: number): void;
  finishStep(seq?: number): void;
  presentingSeq(): number | null;
  queuedSteps(): number;
  drainIdle(): void;
  drainIdleAtModel(coordinate: [number, number] | null): void;
  turnEnd(): void;
  /** retire-gap hook 1, over the production predicate: the acting player carried by an APPLIED frame. */
  actingPlayer(playerId: string): void;
  /** retire-gap hook 2, over the production predicate: the applied frame's coordinate for the presented player. */
  modelCoordinate(coordinate: [number, number] | null): void;
  presented(): typeof state.presentationStep;
  activation(): string | null;
  dispose(): void;
} {
  resetPresentation();
  const priorGame = game.value;
  const enqueueHarnessStep = (playerId: string, from: [number, number], to: [number, number]) => {
    const usedBefore = presentation.stepRun.get(playerId) ?? 0;
    enqueueMoveStep(playerId, from, to, usedBefore, usedBefore + 1);
  };
  return {
    step(playerId, from, to) { enqueueHarnessStep(playerId, from, to); },
    stepWithUsage(playerId, from, to, before, after) {
      enqueueMoveStep(playerId, from, to, before, after);
    },
    finishStep(seq) {
      const current = presentation.presenting;
      if (current?.kind === 'walk') gameStore.onAnimDone('walk', current.id, seq ?? current.seq);
    },
    presentingSeq: () => presentation.presenting?.kind === 'walk' ? presentation.presenting.seq ?? null : null,
    queuedSteps: () => presentation.queue.filter((ev) => ev.kind === 'step').length,
    drainIdle() {
      const step = state.presentationStep;
      if (step) {
        game.value = {
          fieldModel: {
            playerDataArray: [{ playerId: step.playerId, playerCoordinate: [step.to[0], step.to[1]] }],
          },
        } as unknown as GameJson;
      }
      onPresentationDrainIdle();
    },
    drainIdleAtModel(coordinate) {
      const step = state.presentationStep;
      if (step) {
        game.value = {
          fieldModel: {
            playerDataArray: coordinate == null ? [] : [{ playerId: step.playerId, playerCoordinate: coordinate }],
          },
        } as unknown as GameJson;
      }
      onPresentationDrainIdle();
    },
    turnEnd() { requestPresentationRetire(); },
    actingPlayer(playerId) { retirePresentationOnActingChange(playerId); },
    modelCoordinate(coordinate) { retirePresentationOnModelDivergence(coordinate); },
    presented: () => state.presentationStep,
    activation: () => presentation.activation,
    dispose() { resetPresentation(); game.value = priorGame; },
  };
}

/** @internal BB2025 Swoop interaction seam. It exercises the production skill answer and strict CLIENT_SWOOP
 * sender against replaceable authoritative snapshots, including reconnect and both true-side seats. */
export function installSwoopCommandTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => void,
  seat: 'player' | 'opponent' | 'spectator' = 'player',
): {
  answerSkill(use: boolean): void;
  choose(playerId: string, square: [number, number]): boolean;
  reconnect(next: GameJson): void;
  transition(next: GameJson): void;
  choice(): typeof state.skillChoice;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorChoice = state.skillChoice;
  const priorPendingRailCommands = new Map(pendingRailCommands);
  pendingRailCommands.clear();
  game.value = fixture;
  play.active = seat !== 'spectator';
  const actingId = String(fixture.actingPlayer?.playerId ?? '');
  const actingIsHome = fixture.teamHome.playerArray.some((player) => player.playerId === actingId);
  const actingTeam = actingIsHome ? fixture.teamHome : fixture.teamAway;
  const otherTeam = actingIsHome ? fixture.teamAway : fixture.teamHome;
  play.coach = seat === 'player'
    ? String((actingTeam as { coach?: string }).coach ?? 'acting-coach')
    : seat === 'opponent'
      ? String((otherTeam as { coach?: string }).coach ?? 'opponent-coach')
      : 'swoop-spectator';
  session = { send } as unknown as GameSession;
  return {
    answerSkill(use) {
      const g = game.value;
      const dp = g?.dialogParameter as { dialogId?: string; playerId?: string; skill?: string; minimumRoll?: number } | null;
      if (!g || dp?.dialogId !== 'skillUse' || !dp.playerId || !dp.skill) return;
      state.skillChoice = {
        playerId: String(dp.playerId), skill: String(dp.skill), label: prettySkillName(String(dp.skill)),
        minimumRoll: Number(dp.minimumRoll ?? 0), mine: iControlPlayer(String(dp.playerId)),
        seq: (state.skillChoice?.seq ?? 0) + 1, instanceKey: dialogInstanceKey(g),
      };
      gameStore.resolveSkillUse(use);
    },
    choose(playerId, square) { return gameStore.sendSwoop(playerId, square); },
    reconnect(next) { pendingRailCommands.delete('swoop-coordinate'); game.value = next; },
    transition(next) { game.value = next; retireCompletedSwoopOccurrence(); },
    choice: () => state.skillChoice,
    dispose() {
      state.skillChoice = priorChoice;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      pendingRailCommands.clear();
      for (const [rail, pending] of priorPendingRailCommands) pendingRailCommands.set(rail, pending);
    },
  };
}

