/** @internal Inaccurate-pass/interception command-sequence seam over the production model applier. */
export function installPassPacingTestHarness(fixture: GameJson): {
  apply(command: Record<string, unknown>): void;
  throwerId: string;
  interceptorId: string;
  hold(): typeof state.passBallHold;
  throwCue(): typeof state.throwAnim;
  scatterCue(): typeof state.scatterAnim;
  transaction(): { awaitingThrow: boolean; active: string | null; queued: string[] } | null;
  finishThrow(): void;
  finishScatter(): void;
  setCatchingUp(value: boolean): void;
  setActingPlayer(playerId: string | null): void;
  hardBoundary(): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorPlay = { ...play };
  const priorOrder66 = settings.order66;
  const priorCatchingUp = playback.catchingUp;
  const priorHold = state.passBallHold;
  const priorThrow = state.throwAnim;
  const priorScatter = state.scatterAnim;
  const priorLastReportSig = lastReportSig;
  const priorLastReportCommandNr = lastReportCommandNr;

  clearPassPacing(true);
  const next = structuredClone(fixture);
  game.value = next;
  const throwerId = String(next.teamHome.playerArray[0]?.playerId ?? '');
  const interceptorId = String(next.teamAway.playerArray[0]?.playerId ?? '');
  const place = (playerId: string, coordinate: [number, number]) => {
    const data = next.fieldModel.playerDataArray.find((entry) => entry.playerId === playerId);
    if (!data) return;
    data.playerCoordinate = coordinate;
    data.playerState = 1;
  };
  place(throwerId, [12, 3]);
  place(interceptorId, [15, 2]);
  next.turnMode = 'regular';
  next.homePlaying = true;
  next.throwerId = throwerId;
  next.passCoordinate = null;
  next.dialogParameter = null;
  next.fieldModel.ballCoordinate = [12, 3];
  next.fieldModel.ballMoving = false;
  next.actingPlayer = {
    ...(next.actingPlayer ?? {}),
    playerId: throwerId,
    playerAction: 'pass',
  } as GameJson['actingPlayer'];
  play.active = false;
  play.coach = 'pass-pacing-spectator';
  settings.order66 = true;
  playback.catchingUp = false;
  state.passBallHold = null;
  state.throwAnim = null;
  state.scatterAnim = null;
  lastReportSig = null;
  lastReportCommandNr = null;

  return {
    apply(command) {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          modelChangeList: { modelChangeArray: [] },
          reportList: { reports: [] },
          ...structuredClone(command),
        },
      });
    },
    throwerId,
    interceptorId,
    hold: () => state.passBallHold,
    throwCue: () => state.throwAnim,
    scatterCue: () => state.scatterAnim,
    transaction: () => passPacing ? {
      awaitingThrow: passPacing.awaitingAuthoritativeThrow,
      active: passPacing.active?.kind ?? null,
      queued: passPacing.queue.map((event) => event.kind),
    } : null,
    finishThrow() { gameStore.onAnimDone('throw', '__ball__'); },
    finishScatter() {
      if (passPacing?.active?.kind === 'scatter') completePassPacingVisual('scatter', passPacing.active.id);
    },
    setCatchingUp(value) { playback.catchingUp = value; },
    setActingPlayer(playerId) {
      if (!game.value) return;
      game.value.actingPlayer = {
        ...(game.value.actingPlayer ?? {}),
        playerId,
      } as GameJson['actingPlayer'];
    },
    hardBoundary() { clearCinematics(true); },
    dispose() {
      clearPassPacing(true);
      state.passBallHold = priorHold;
      state.throwAnim = priorThrow;
      state.scatterAnim = priorScatter;
      lastReportSig = priorLastReportSig;
      lastReportCommandNr = priorLastReportCommandNr;
      playback.catchingUp = priorCatchingUp;
      settings.order66 = priorOrder66;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      game.value = priorGame;
    },
  };
}

/** @internal Coin-result presentation seam over the production pregame FIFO/log gate. */
export function installCoinPresentationTestHarness(
  fixture: GameJson,
  clickDismiss = false,
): {
  queueFanAndWeather(): void;
  reveal(input: { result: 'heads' | 'tails'; coach: string; won: boolean; called: 'heads' | 'tails' }): void;
  applyCoinReport(input: { coinThrowHeads: boolean; coinChoiceHeads: boolean; coach: string }): void;
  applyAuthoritativeCoin(input: { coinThrowHeads: boolean; coinChoiceHeads: boolean; coach: string }): void;
  showing(): typeof state.coinToss;
  queueKinds(): Array<PregameCineStep['kind']>;
  allLogs(): string[];
  resultLogs(): string[];
  dismiss(): void;
  hardBoundary(): void;
  setCatchingUp(value: boolean): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorClickDismiss = settings.clickDismissCinematics;
  const priorDebugLog = settings.debugLog;
  const priorCatchingUp = playback.catchingUp;
  const priorLog = [...state.log];
  const priorCoinToss = state.coinToss;
  const priorWeather = state.weatherCine;
  const priorFan = state.fanFactorCine;
  const priorLastCoinCall = lastCoinCall;
  const priorRevealShown = coinRevealShown;
  const priorRevealResult = coinRevealResult;
  const priorArmedGameId = coinArmedGameId;
  const priorPendingLog = pendingCoinResultLog;
  const priorLastReportSig = lastReportSig;
  const priorLastReportCommandNr = lastReportCommandNr;
  const priorLastAppliedCommandNr = lastAppliedCommandNr;

  const resetCoinQueue = (publish = false) => {
    for (const timer of [coinTimer, weatherTimer, fanFactorTimer, pregameCineTimer]) if (timer) cancelGameTimeout(timer);
    coinTimer = weatherTimer = fanFactorTimer = pregameCineTimer = null;
    pregameCineQueue.length = 0;
    pregameCineBusyUntil = 0;
    state.weatherCine = null;
    state.fanFactorCine = null;
    finishCoinToss(publish);
  };

  resetCoinQueue(false);
  game.value = structuredClone(fixture);
  settings.clickDismissCinematics = clickDismiss;
  settings.debugLog = true;
  playback.catchingUp = false;
  state.log = [];
  lastCoinCall = null;
  coinRevealShown = false;
  coinRevealResult = null;
  coinArmedGameId = null;
  lastReportSig = null;
  lastReportCommandNr = null;

  return {
    queueFanAndWeather() {
      const g = game.value!;
      enqueuePregameCine(
        () => showFanFactor({ fans: 1, roll: 2, total: 3 }, { fans: 1, roll: 1, total: 2 }, g),
        presentationMs(FAN_CINE_MS),
        'fan',
      );
      enqueuePregameCine(() => showWeather([3, 4], 'Nice'), presentationMs(WEATHER_CINE_MS), 'weather');
    },
    reveal(input) {
      enqueuePriorityCoinReveal(
        () => showCoinToss(input.result, input.coach, input.won, input.called),
        presentationMs(COIN_CINE_MS),
      );
    },
    applyCoinReport(input) {
      detectPregameCinematics([{ reportId: 'coinThrow', ...input }], game.value!);
    },
    applyAuthoritativeCoin(input) {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          commandNr: ++isolatedPresentationTestCommandNr,
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          modelChangeList: { modelChangeArray: [] },
          reportList: { reports: [{ reportId: 'coinThrow', ...input }] },
        },
      });
    },
    showing: () => state.coinToss,
    queueKinds: () => pregameCineQueue.map((step) => step.kind),
    allLogs: () => state.log.map((entry) => entry.text),
    resultLogs: () => state.log.filter((entry) => entry.text.startsWith('🪙 ')).map((entry) => entry.text),
    dismiss: () => dismissShownCine(),
    hardBoundary: () => clearCinematics(true),
    setCatchingUp(value) { playback.catchingUp = value; },
    dispose() {
      resetCoinQueue(false);
      game.value = priorGame;
      settings.clickDismissCinematics = priorClickDismiss;
      settings.debugLog = priorDebugLog;
      playback.catchingUp = priorCatchingUp;
      state.log = priorLog;
      state.coinToss = priorCoinToss;
      state.weatherCine = priorWeather;
      state.fanFactorCine = priorFan;
      lastCoinCall = priorLastCoinCall;
      coinRevealShown = priorRevealShown;
      coinRevealResult = priorRevealResult;
      coinArmedGameId = priorArmedGameId;
      pendingCoinResultLog = priorPendingLog;
      lastReportSig = priorLastReportSig;
      lastReportCommandNr = priorLastReportCommandNr;
      lastAppliedCommandNr = priorLastAppliedCommandNr;
    },
  };
}

/** @internal Kickoff command-sequence seam over production applyFrame + the presentation FIFO. */
export function installKickoffPresentationTestHarness(
  fixture: GameJson,
  seat: 'home' | 'away' | 'spectator',
  send: (command: Record<string, unknown>) => void = () => undefined,
): {
  apply(command: Record<string, unknown>): void;
  preview(): typeof state.kickScatterPreview;
  aim(): typeof state.kickAim;
  descend(): typeof state.kickDescend;
  bounce(): typeof state.scatterAnim;
  queue(): string[];
  presenting(): string | null;
  dismissEvent(): void;
  finishKick(): void;
  submitLocalAim(square: [number, number]): void;
  setCatchingUp(value: boolean): void;
  decisionDwell(): boolean;
  event(): typeof state.kickoffCine;
  modelBall(): unknown;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorOrder66 = settings.order66;
  const priorClickDismiss = settings.clickDismissCinematics;
  const priorPreview = state.kickScatterPreview;
  const priorAim = state.kickAim;
  const priorDescend = state.kickDescend;
  const priorScatter = state.scatterAnim;
  const priorPlacement = state.kickPlacement;
  const priorOpponentPending = state.opponentChoicePending;
  const priorOpponentPendingPlayerId = state.opponentChoicePendingPlayerId;
  const priorOpponentReviewing = state.opponentReviewingDice;
  const priorCatchingUp = playback.catchingUp;
  const priorDecisionDwell = state.kickoffArcNeedsDecisionDwell;
  const priorKickoffCine = state.kickoffCine;
  const priorPendingWinnerKickoff = pendingWinnerKickoff;
  const priorLastReportSig = lastReportSig;
  const priorLastReportCommandNr = lastReportCommandNr;

  resetPresentation();
  kickoffPresentationOccurrence = null;
  acceptedAuthoritativeKicks.clear();
  acceptedKickoffScatterReveals.clear();
  lastReportSig = null;
  lastReportCommandNr = null;
  // Model the requested player seat as the server-designated kicking/acting side.
  // This keeps the local-aim assertion on the real resolveKickPlacement/send lock.
  if (seat === 'home') fixture.homePlaying = true;
  else if (seat === 'away') fixture.homePlaying = false;
  game.value = fixture;
  play.active = seat !== 'spectator';
  play.coach = seat === 'home'
    ? String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach')
    : seat === 'away'
      ? String((fixture.teamAway as { coach?: string }).coach ?? 'away-coach')
      : 'spectator-not-seated';
  settings.order66 = true;
  settings.clickDismissCinematics = true;
  state.kickScatterPreview = null;
  state.kickAim = null;
  state.kickDescend = null;
  state.scatterAnim = null;
  state.kickPlacement = null;
  state.opponentChoicePending = null; state.opponentChoicePendingPlayerId = null;
  state.opponentReviewingDice = false;
  state.kickoffArcNeedsDecisionDwell = false;
  state.kickoffCine = null;
  pendingWinnerKickoff = null;
  session = { send } as unknown as GameSession;

  return {
    apply(command) {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          modelChangeList: { modelChangeArray: [] },
          reportList: { reports: [] },
          ...command,
          commandNr: command.commandNr ?? ++isolatedPresentationTestCommandNr,
        },
      });
    },
    preview: () => state.kickScatterPreview,
    aim: () => state.kickAim,
    descend: () => state.kickDescend,
    bounce: () => state.scatterAnim,
    queue: () => presentation.queue.map((event) => event.kind),
    presenting: () => presentation.presenting?.kind ?? null,
    dismissEvent() { if (presentation.presenting?.kind === 'cine') presentation.presenting.release(); },
    finishKick() { gameStore.onAnimDone('kickDescend', '__ball__'); },
    submitLocalAim(square) {
      state.kickPlacement = { squares: [square], seq: 1 };
      gameStore.resolveKickPlacement(square);
    },
    setCatchingUp(value) { playback.catchingUp = value; },
    decisionDwell: () => state.kickoffArcNeedsDecisionDwell,
    event: () => state.kickoffCine,
    modelBall: () => game.value?.fieldModel.ballCoordinate,
    dispose() {
      resetPresentation();
      clearAllGameTimeouts();
      kickoffPresentationOccurrence = null;
      acceptedAuthoritativeKicks.clear();
      acceptedKickoffScatterReveals.clear();
      lastReportSig = priorLastReportSig;
      lastReportCommandNr = priorLastReportCommandNr;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      settings.order66 = priorOrder66;
      settings.clickDismissCinematics = priorClickDismiss;
      state.kickScatterPreview = priorPreview;
      state.kickAim = priorAim;
      state.kickDescend = priorDescend;
      state.scatterAnim = priorScatter;
      state.kickPlacement = priorPlacement;
      state.opponentChoicePending = priorOpponentPending;
      state.opponentChoicePendingPlayerId = priorOpponentPendingPlayerId;
      state.opponentReviewingDice = priorOpponentReviewing;
      playback.catchingUp = priorCatchingUp;
      state.kickoffArcNeedsDecisionDwell = priorDecisionDwell;
      state.kickoffCine = priorKickoffCine;
      pendingWinnerKickoff = priorPendingWinnerKickoff;
    },
  };
}

