/** @internal REFEREE SEND-OFF integration seam (Row19, owner sighting 08-17 game 866: Argue-the-call
 *  dialog wouldn't dismiss / re-argued 9x). Feeds raw serverModelSync frames — exact wire literals — through
 *  the production applyFrame path so the argueTheCall→bribes dialog flip and the answered-instance latch can
 *  be exercised end-to-end, same as the game_866.log capture. */
export function installSendOffTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => boolean | void,
  seat: 'home' | 'away' | 'spectator' | 'replay' = 'home',
): {
  apply(command: Record<string, unknown>): void;
  sendOff(): typeof state.sendOff;
  sendOffResult(): typeof state.sendOffResult;
  sendOffWaiting(): typeof state.sendOffWaiting;
  argue(): void;
  bribe(): void;
  pass(): void;
  hardBoundary(next?: GameJson): void;
  setCatchingUp(value: boolean): void;
  disconnect(): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorOrder66 = settings.order66;
  const priorInteractive = interactiveReRolls;
  const priorReplayActive = replay.active;
  const priorCatchingUp = playback.catchingUp;
  const priorSendOff = state.sendOff;
  const priorSendOffResult = state.sendOffResult;
  const priorSendOffWaiting = state.sendOffWaiting;
  const priorSendOffKey = sendOffKey;
  const priorSendOffAnsweredKey = sendOffAnsweredKey;

  game.value = fixture;
  game.value.turnMode = 'regular';
  game.value.dialogParameter = null;
  play.active = seat === 'home' || seat === 'away';
  play.coach = seat === 'home' ? String((fixture.teamHome as { coach?: string }).coach ?? 'home-coach')
    : seat === 'away' ? String((fixture.teamAway as { coach?: string }).coach ?? 'away-coach') : '';
  replay.active = seat === 'replay';
  playback.catchingUp = false;
  settings.order66 = false;
  interactiveReRolls = true;
  state.sendOff = null;
  state.sendOffResult = null;
  clearSendOffWaiting();
  sendOffKey = '';
  sendOffAnsweredKey = null;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  return {
    apply(command) {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          modelChangeList: { modelChangeArray: [] },
          reportList: { reports: [] },
          ...command,
        },
      });
    },
    sendOff: () => state.sendOff,
    sendOffResult: () => state.sendOffResult,
    sendOffWaiting: () => state.sendOffWaiting,
    argue: () => gameStore.sendOffArgue(),
    bribe: () => gameStore.sendOffBribe(),
    pass: () => gameStore.sendOffPass(),
    hardBoundary(next = fixture) {
      clearCinematics(true);
      game.value = structuredClone(next);
      game.value.turnMode = 'regular';
      game.value.dialogParameter = null;
    },
    setCatchingUp(value) {
      playback.catchingUp = value;
      syncOpponentSendOffWaiting(game.value!);
    },
    disconnect() { play.active = false; clearSendOffWaiting(); },
    dispose() {
      clearSendOffWaiting();
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      settings.order66 = priorOrder66;
      interactiveReRolls = priorInteractive;
      replay.active = priorReplayActive;
      playback.catchingUp = priorCatchingUp;
      state.sendOff = priorSendOff;
      state.sendOffResult = priorSendOffResult;
      state.sendOffWaiting = priorSendOffWaiting;
      sendOffKey = priorSendOffKey;
      sendOffAnsweredKey = priorSendOffAnsweredKey;
    },
  };
}

/** Hook: called after each server command is fully applied to the model (applyFrame). `cmd` is the frame just
 *  applied — its reportList carries the arrival-square resolution outcomes (leg-2a). */
function plannerOnModelApplied(cmd?: Record<string, unknown>) {
  const p = plannerPlan;
  if (!p) return;
  // Resolve a square's rolls only after arrival and only on success; failures remain pending for reroll/fall.
  if (p.phase === 'moving' && p.sentIdx >= 0) {
    const cur = p.squareResolutions[p.sentIdx];
    const target = p.route[p.sentIdx];
    if (cur && cur.size > 0 && target) {
      const coord = plannerCoord(p.playerId);
      const arrived = !!coord && coord[0] === target[0] && coord[1] === target[1];
      const reps = (cmd?.reportList as { reports?: { reportId?: unknown; playerId?: unknown; successful?: unknown; reRolled?: unknown }[] } | undefined)?.reports ?? [];
      for (const r of reps) {
        if (String(r.playerId ?? '') !== p.playerId) continue;
        const kind = PLAN_RESOLUTION_REPORT[String(r.reportId ?? '')];
        if (!kind || r.successful !== true || !cur.has(kind)) continue;
        if (arrived) cur.delete(kind);
        else if (r.reRolled === true) {
          // A successful reroll may settle the roll but leave the model at the origin. Mark the current destination
          // for one server-offer-bounded resend after the live reroll dialog clears (plannerPromptPending above).
          cur.delete(kind);
          p.retryResolvedIdx = p.sentIdx;
        }
      }
    }
  }
  plannerAdvance();
}

/** Owner-captured 08-04 defaults, home-relative (own half x0..12, LOS x=12).
 *  Bands are deliberately LOS-first: star-priority player selection therefore puts stars on the line,
 *  and a short bench degrades to the minimum-three-LOS legal shape before filling deeper bands. */
const KICKING_SETUP_FORMATION: { capacity: number; squares: [number, number][] }[] = [
  { capacity: 5, squares: [[12, 5], [12, 6], [12, 7], [12, 8], [12, 9]] },
  { capacity: 3, squares: [[11, 4], [11, 7], [11, 10]] },
  { capacity: 3, squares: [[9, 6], [9, 7], [9, 8]] },
];
const RECEIVING_SETUP_FORMATION: { capacity: number; squares: [number, number][] }[] = [
  { capacity: 8, squares: [[12, 3], [12, 5], [12, 6], [12, 7], [12, 8], [12, 9], [12, 10], [12, 12]] },
  { capacity: 2, squares: [[11, 2], [11, 13]] },
  { capacity: 1, squares: [[6, 7], [5, 7], [7, 7]] }, // deep safety: owner permits +/-1 depth if needed
];
const pregameHandled = new Set<string>();
let setupLoop: ReturnType<typeof setInterval> | null = null;

// Central send lock: always-allowed, declarations, then owned-dialog answers; unknown commands fail open as answers.
const ALWAYS_ALLOWED_COMMANDS = new Set<string>([
  NetCommandId.CLIENT_ILLEGAL_PROCEDURE, NetCommandId.CLIENT_CONCEDE_GAME, NetCommandId.CLIENT_TALK,
  NetCommandId.CLIENT_PING, NetCommandId.CLIENT_JOIN, NetCommandId.CLIENT_PASSWORD_CHALLENGE,
  NetCommandId.CLIENT_REQUEST_VERSION, NetCommandId.CLIENT_USER_SETTINGS, NetCommandId.CLIENT_CLOSE_SESSION,
  NetCommandId.CLIENT_DEBUG_CLIENT_STATE, NetCommandId.CLIENT_SET_MARKER,
  NetCommandId.CLIENT_UPDATE_PLAYER_MARKINGS, NetCommandId.CLIENT_LOAD_AUTOMATIC_PLAYER_MARKINGS,
  NetCommandId.CLIENT_TEAM_SETUP_LOAD, NetCommandId.CLIENT_TEAM_SETUP_SAVE, NetCommandId.CLIENT_TEAM_SETUP_DELETE,
]);
/** The ACTION wire — what "no actions while an opponent choice is pending" actually means. */
const DECLARE_COMMANDS = new Set<string>([
  NetCommandId.CLIENT_ACTING_PLAYER, NetCommandId.CLIENT_MOVE, NetCommandId.CLIENT_BLITZ_MOVE,
  NetCommandId.CLIENT_BLITZ_TARGET_SELECTED, NetCommandId.CLIENT_TARGET_SELECTED, NetCommandId.CLIENT_END_TURN,
  NetCommandId.CLIENT_HAND_OVER, NetCommandId.CLIENT_PASS, NetCommandId.CLIENT_BLOCK, NetCommandId.CLIENT_FOUL,
  NetCommandId.CLIENT_THROW_TEAM_MATE, NetCommandId.CLIENT_KICK_TEAM_MATE, NetCommandId.CLIENT_SWOOP,
  NetCommandId.CLIENT_GAZE, NetCommandId.CLIENT_FIELD_COORDINATE, NetCommandId.CLIENT_THROW_KEG,
  NetCommandId.CLIENT_SET_BLOCK_TARGET_SELECTION, NetCommandId.CLIENT_UNSET_BLOCK_TARGET_SELECTION,
  NetCommandId.CLIENT_SYNCHRONOUS_MULTI_BLOCK, NetCommandId.CLIENT_KICKOFF,
  // Setup placement is phase-scoped, not always allowed; server dispatch alone does not make it legitimate.
  NetCommandId.CLIENT_USE_FUMBLEROOSKIE,
  NetCommandId.CLIENT_SETUP_PLAYER,
]);
const OWN_DIALOG_ANSWER_COMMANDS = new Set<string>([
  NetCommandId.CLIENT_PUNT_TO_CROWD,
]);
const seenUnclassifiedCommands = new Set<string>();
/** The lock's view of ONE outbound command. Exported-by-use only (module-local): the view never calls this —
 *  it consults `actionAllowed` directly for its affordances; this is the wire backstop. */
function commandActionClass(id: string): ActionClass {
  if (DECLARE_COMMANDS.has(id)) return 'declare';
  if (OWN_DIALOG_ANSWER_COMMANDS.has(id)) return 'answerOwnDialog';
  // Illegal Procedure bypasses this classifier via ALWAYS_ALLOWED; preserve that coupling if classifications change.
  if (!ALWAYS_ALLOWED_COMMANDS.has(id) && !seenUnclassifiedCommands.has(id)) {
    seenUnclassifiedCommands.add(id);
    console.info(`[#173] '${id}' unclassified → treated as answerOwnDialog (fail-soft). Classify it if it is an action.`);
  }
  return 'answerOwnDialog';
}

/** BB2025 Swoop is a two-command decision inside one server step. After CLIENT_USE_SKILL(true), upstream keeps
 * the skillUse dialog parked while it changes the thrown player to `playerAction=swoop`, publishes the four
 * cardinal move squares, and waits for CLIENT_SWOOP. The generic raw-dialog lock must admit only that exact
 * second-stage answer; otherwise the field click is locally dropped and the match wedges after "Swoop USED".
 * Re-derive the complete server-owned contract here instead of trusting the UI or the prior local answer. */
function ownedSwoopCoordinateCommandPermitted(g: GameJson, command: Record<string, unknown>): boolean {
  if (String(command.netCommandId ?? '') !== NetCommandId.CLIENT_SWOOP) return false;
  const dialog = g.dialogParameter as { dialogId?: unknown; playerId?: unknown; skill?: unknown } | null | undefined;
  if (String(dialog?.dialogId ?? '') !== 'skillUse' || normSkill(dialog?.skill) !== 'swoop') return false;
  const acting = g.actingPlayer as { playerId?: unknown; playerAction?: unknown } | null | undefined;
  const actingId = String(acting?.playerId ?? '');
  if (!actingId || String(acting?.playerAction ?? '') !== 'swoop'
      || String(dialog?.playerId ?? '') !== actingId
      || String(command.actingPlayerId ?? '') !== actingId
      || !iControlPlayer(actingId)) return false;
  const ctx: ClientStateContext = { mode: 'player', loggedIn: true, myIsHome: myPlayTeam(g) === g.teamHome };
  if (deriveClientState(g, ctx) !== 'SWOOP') return false;
  const target = command.targetCoordinate;
  if (!Array.isArray(target) || target.length < 2) return false;
  const x = Number(target[0]);
  const y = Number(target[1]);
  if (!Number.isInteger(x) || !Number.isInteger(y) || x < 0 || x > 25 || y < 0 || y > 14) return false;
  const source = normSquare((g.fieldModel?.playerDataArray ?? [])
    .find((data) => data.playerId === actingId)?.playerCoordinate);
  return !!source
    && Math.abs(source[0] - x) + Math.abs(source[1] - y) === 1
    && serverMoveSquares(g).some((offered) => offered[0] === x && offered[1] === y);
}

/** @internal Exact DialogPuntToCrowd yes/no occurrence seam. */
export function installPuntToCrowdTestHarness(
  fixture: GameJson,
  seat: 'owner' | 'opponent' | 'spectator',
  send: (command: Record<string, unknown>) => boolean | void,
  interactive = true,
): {
  mount(): void;
  prompt(): typeof state.yesNo;
  unknown(): typeof state.unknownCall;
  answer(value: boolean): void;
  resync(): void;
  replaceDialog(dialog: GameJson['dialogParameter']): void;
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorInteractiveSetup = interactiveSetup;
  const priorInteractiveReRolls = interactiveReRolls;
  const priorYesNo = state.yesNo;
  const priorYesNoResolver = yesNoResolver;
  const priorUnknown = state.unknownCall;
  const priorHandled = [...pregameHandled];
  const priorAnsweredKey = answeredDialogInstanceKey;
  const priorAnsweredRef = answeredDialogInstanceRef;

  pregameHandled.clear();
  clearAnsweredDialogInstance();
  state.yesNo = null;
  yesNoResolver = null;
  state.unknownCall = null;
  game.value = fixture;
  const actingId = String(fixture.actingPlayer?.playerId ?? '');
  const actorHome = fixture.teamHome.playerArray.some((player) => player.playerId === actingId);
  const ownerTeam = actorHome ? fixture.teamHome : fixture.teamAway;
  const opponentTeam = actorHome ? fixture.teamAway : fixture.teamHome;
  play.active = seat !== 'spectator';
  play.coach = seat === 'owner'
    ? String((ownerTeam as { coach?: string }).coach ?? '')
    : seat === 'opponent'
      ? String((opponentTeam as { coach?: string }).coach ?? '')
      : 'punt-spectator';
  play.autoPregame = true;
  interactiveSetup = interactive;
  interactiveReRolls = interactive;
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;

  const drive = () => { drivePregameStep(); maybeSurfaceUnknownCall(game.value!); };
  return {
    mount: drive,
    prompt: () => state.yesNo,
    unknown: () => state.unknownCall,
    answer: (value) => gameStore.resolveYesNo(value),
    resync: drive,
    replaceDialog(dialog) {
      if (game.value) game.value.dialogParameter = dialog;
      drive();
    },
    dispose() {
      clearYesNo();
      state.yesNo = priorYesNo;
      yesNoResolver = priorYesNoResolver;
      state.unknownCall = priorUnknown;
      pregameHandled.clear();
      for (const key of priorHandled) pregameHandled.add(key);
      clearAnsweredDialogInstance();
      if (priorAnsweredKey) latchAnsweredDialogInstance(priorAnsweredKey, priorAnsweredRef);
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
      interactiveSetup = priorInteractiveSetup;
      interactiveReRolls = priorInteractiveReRolls;
    },
  };
}

/** @internal Foul terminal seam for the additional-foul pending-offer boundary. */
export function installFoulTargetTestHarness(
  fixture: GameJson,
  send: (command: Record<string, unknown>) => boolean | void,
): {
  send(defenderId: string): void;
  applyResponse(): void;
  logs(): LogEntry[];
  dispose(): void;
} {
  const priorGame = game.value;
  const priorSession = session;
  const priorPlay = { ...play };
  const priorPending = new Map(pendingRailCommands);
  const priorLog = [...state.log];
  pendingRailCommands.clear();
  state.log = [];
  game.value = fixture;
  play.active = true;
  play.coach = String((fixture.homePlaying ? fixture.teamHome : fixture.teamAway as { coach?: string }).coach ?? '');
  session = {
    send(command: Record<string, unknown>) {
      if (send(command) === false) throw new Error('test transport refusal');
    },
  } as unknown as GameSession;
  return {
    send: (defenderId) => gameStore.sendFoulTarget(defenderId),
    applyResponse() {
      applyFrame({
        receivedAt: Date.now(),
        cmd: {
          netCommandId: NetCommandId.SERVER_MODEL_SYNC,
          commandNr: 0,
          modelChangeList: { modelChangeArray: [] },
          reportList: { reports: [] },
        },
      });
    },
    logs: () => state.log,
    dispose() {
      pendingRailCommands.clear();
      for (const [rail, pending] of priorPending) pendingRailCommands.set(rail, pending);
      state.log = priorLog;
      session = priorSession;
      game.value = priorGame;
      play.active = priorPlay.active;
      play.coach = priorPlay.coach;
      play.autoPregame = priorPlay.autoPregame;
    },
  };
}

function ownedBlitzTargetDialogCommandPermitted(g: GameJson, command: Record<string, unknown>): boolean {
  if (String(command.netCommandId ?? '') !== NetCommandId.CLIENT_TARGET_SELECTED) return false;
  const dialog = g.dialogParameter as { dialogId?: unknown; teamId?: unknown } | null | undefined;
  if (String(dialog?.dialogId ?? '') !== 'selectBlitzTarget') return false;
  const actingId = String((g.actingPlayer as { playerId?: unknown } | null | undefined)?.playerId ?? '');
  if (!actingId || !iControlPlayer(actingId)) return false;
  const myTeamId = String((myPlayTeam(g) as { teamId?: unknown } | undefined)?.teamId ?? '');
  if (dialog?.teamId != null && String(dialog.teamId) !== myTeamId) return false;
  const targetId = String(command.playerId ?? '');
  return !!targetId && (g.fieldModel?.playerDataArray ?? []).some((data) => data.playerId === targetId);
}

/**
 * Declaration-shaped commands are normally forbidden while a raw server dialog is live. A small number of
 * upstream states deliberately keep such a dialog open while awaiting another declaration-shaped command.
 * This is the complete capability list for those states; no generic "my dialog" bypass exists.
 */
function ownedDeclarationInsideLiveDialogPermitted(g: GameJson, command: Record<string, unknown>): boolean {
  return isOwnedOnTheBallDialogCommand(onTheBallFrame(g), command)
    || ownedBlitzTargetDialogCommandPermitted(g, command)
    || ownedSwoopCoordinateCommandPermitted(g, command)
    || ownedSetupPhaseDialogCommandPermitted(g, command);
}
/** #173 boundary gate. Returns true when the command may go out. */
function commandPermittedByLock(cmd: Record<string, unknown>): boolean {
  const g = game.value;
  if (!g || !play.active) return true; // not in play → the lock has no opinion (spectate/replay/pregame paths)
  const id = String(cmd.netCommandId ?? '');
  if (ALWAYS_ALLOWED_COMMANDS.has(id)) return true;
  if (state.skillChoice?.origin === 'shotToNothing') {
    return id === NetCommandId.CLIENT_USE_SKILL
      && normSkill(cmd.skill) === 'shottonothing'
      && cmd.skillUsed === true
      && String(cmd.playerId ?? '') === state.skillChoice.playerId;
  }
  // The established action-state classifier does not distinguish every locally
  // unresolved occurrence of an own-team model dialog. Keep declarations behind
  // that raw server occurrence, without blocking client-owned commit cards such as
  // Gored By The Bull whose payload is itself a declaration command.
  // Live game 1940037 (owner 09-07): upstream SetupMechanic shows `setupError` with no matching hide — the next
  // hideDialog is StepKickoffResultRoll — so an opponent's (or my own, already corrected) setup notice is STILL the
  // model's dialogParameter when turnMode flips to kickoff. It is informational (the server never waits on it), so
  // outside the setup turn modes it must not veto declarations: the kicking coach's CLIENT_KICKOFF was dropped here.
  const liveDialogId = String((g.dialogParameter as { dialogId?: unknown } | null | undefined)?.dialogId ?? '');
  const staleSetupNotice = (liveDialogId === 'setupError' || liveDialogId === 'swarmingError')
    && !STALE_SETUP_NOTICE_LIVE_MODES.has(String(g.turnMode ?? ''));
  if (commandActionClass(id) === 'declare' && g.dialogParameter && !dialogAlreadyAnswered() && !staleSetupNotice) {
    return ownedDeclarationInsideLiveDialogPermitted(g, cmd);
  }
  const ctx: ClientStateContext = { mode: 'player', loggedIn: true, myIsHome: myPlayTeam(g) === g.teamHome };
  return actionAllowed(g, ctx, commandActionClass(id));
}
/** Turn modes in which a setupError/swarmingError dialog is still the live correction surface (see above). */
const STALE_SETUP_NOTICE_LIVE_MODES = new Set(['setup', 'solidDefence', 'perfectDefence', 'swarming']);

function sendCommand(cmd: Record<string, unknown>): boolean {
  if (!replayAllowsGameCommand(replay.active)) {
    observeOutgoingShadow(cmd, 'dropped');
    console.warn('[replay] dropped outbound command:', cmd.netCommandId);
    return false;
  }
  // Stop code: drop every play-mode/turn command in a spectator-only build or after the server terminates the match.
  if (!playPermitted()) {
    observeOutgoingShadow(cmd, 'dropped');
    console.warn('[play-gate] dropped outbound command:', cmd.netCommandId);
    return false;
  }
  // #173: no ACTIONS while an opponent choice is pending (or during the opponent's turn/setup). Answers to my own live dialog and Call Time-Out still go out — see commandActionClass + actionSurfaceLock.
  if (!commandPermittedByLock(cmd)) {
    observeOutgoingShadow(cmd, 'dropped');
    const g = game.value;
    console.warn('[#173] dropped outbound command outside exact dialog capability:', {
      netCommandId: cmd.netCommandId,
      turnMode: g?.turnMode ?? null,
      dialogId: (g?.dialogParameter as { dialogId?: unknown } | null | undefined)?.dialogId ?? null,
      dialogTeamId: (g?.dialogParameter as { teamId?: unknown } | null | undefined)?.teamId ?? null,
    });
    return false;
  }
  observeOutgoingShadow(cmd, 'emitted');
  let outgoing = cmd;
  const g = game.value;
  // Respin 7 (owner live false-refusal, 08-12 eve): the Move-rail cutover claims sends ONLY in the turn
  // modes its transaction models. kickoffReturn/passBlock (On the Ball) declare implicitly — the first
  // clientMove arrives with NO model actingPlayer, the transaction reads 'inactive', and ownership
  // projection false-refused every On-the-Ball move. Positive allow-list (owner doctrine); all other
  // modes ride legacy with shadow telemetry still observing. Full modeling = a later slice.
  if (g && RAIL_CUTOVER_TURN_MODES.has(String(g.turnMode ?? ''))) {
    const team = play.active ? myPlayTeam(g) : undefined;
    const audience = state.demoMode ? 'replay' : play.active ? 'player' : 'spectator';
    const myTeamId = (team as { teamId?: string } | undefined)?.teamId ?? null;
    const owned = projectOwnedOutgoingCommand(outgoingShadowFrame(g), cmd, {
      audience,
      myTeamId,
      maySend: play.active,
    }, railDiagnostic);
    if (!owned) {
      const netCommandId = String(cmd.netCommandId ?? '');
      console.warn('[move-rail] dropped outbound command (ownership refused):', cmd.netCommandId);
      railDiagnostic({
        rail: 'move',
        code: 'ownership-refusal',
        netCommandId,
        audience,
        myTeamId,
        message: `[move-rail] ownership refused outbound command netCommandId=${netCommandId} audience=${audience} myTeamId=${myTeamId ?? 'none'}`,
      });
      return false;
    }
    outgoing = owned;
  }
  try {
    verboseTee('out', outgoing); // owner 2026-07-07: tee outbound commands actually sent (wire log)
    if (!session) return false;
    session.send(outgoing as never);
    return true;
  } catch (e) {
    // connection dropped between the state update and the send — ignore.
    console.warn('[play] send skipped:', (e as Error)?.message);
    return false;
  }
}

// Owner 2026-07-06: SPECTATOR drive-north flip helpers. Best-effort read of which team is on offense when JOIN mid-game (no kickoff observed): ball carrier's team if held, else first-offense/half rule (home receives first drive of first half iff homeFirstOffense; swaps at second half); half rule is first guess, self-corrects at next kickoff.
function deriveOffenseIsHome(g: GameJson): boolean {
  const fm = g.fieldModel;
  const ball = fm.ballCoordinate;
  if (fm.ballInPlay && !fm.ballMoving && Array.isArray(ball)) {
    const carrier = fm.playerDataArray.find(
      (d) => Array.isArray(d.playerCoordinate) && d.playerCoordinate[0] === ball[0] && d.playerCoordinate[1] === ball[1],
    );
    if (carrier) return g.teamHome.playerArray.some((p) => p.playerId === carrier.playerId);
  }
  const homeFirst = !!(g as { homeFirstOffense?: unknown }).homeFirstOffense;
  const secondHalf = Number(g.half ?? 1) === 2;
  return secondHalf ? !homeFirst : homeFirst;
}

/** Recompute state.fieldFlip from current drive offense + play mode. Flip is SPECTATOR-ONLY (play mode keeps active/home at bottom), true only when driving team is AWAY (attacks near/south natively, mirror to send drive north). seq bumps only on real change. */
function updateFieldFlip(g: GameJson): void {
  if (driveOffenseIsHome === null) driveOffenseIsHome = deriveOffenseIsHome(g);
  const flip = !play.active && driveOffenseIsHome === false;
  if (flip !== state.fieldFlip.flip) {
    state.fieldFlip = { flip, seq: state.fieldFlip.seq + 1 };
  }
}

/** Resolve my team by normalized coach name; player feeds are mirrored, while dialog team IDs remain raw. */
function myPlayTeam(g: GameJson) {
  const me = play.coach?.trim().toLowerCase() ?? '';
  const byCoach = me
    ? [g.teamHome, g.teamAway].find((t) => (t as { coach?: string })?.coach?.trim().toLowerCase() === me)
    : undefined;
  if (byCoach) return byCoach;
  // Last-resort fallback (owner 2026-07-09): if coach STILL doesn't match, live player gets myTeamId=undefined→teamId-addressed dialog (inducements) matches NEITHER side→coaches stall. Returning teamHome keeps teamId gate resolving; only correct when local player is home (safety net not truth); case-insensitive match above makes this near-unreachable. Spectators/replays (play.active=false) keep strict result (no team→correct for non-participant).
  if (play.active) return g.teamHome;
  return undefined;
}

/** Presentation/decision ownership is strict and never inherits myPlayTeam's command-liveness Home fallback. */
function blockPresentationSeat(g: GameJson | null | undefined): 'home' | 'away' | null {
  return strictBlockPresentationSeat(g, play.active, play.coach);
}

function localOwnsCurrentBlockDialog(): boolean {
  const g = game.value;
  if (!g || !play.active) return false;
  return projectBlockChooser(g, currentBlockChoosingTeamId(g), blockPresentationSeat(g), false).mine;
}

function localOwnsCurrentMultiBlockDialog(): boolean {
  const g = game.value;
  if (!g || !play.active) return false;
  return projectBlockChooser(g, currentMultiBlockChoosingTeamId(g), blockPresentationSeat(g), false).mine;
}

/** Player-ids of my team. */
function myPlayIds(g: GameJson): Set<string> {
  return new Set(((myPlayTeam(g)?.playerArray ?? []) as { playerId: string }[]).map((p) => p.playerId));
}

/** True when it's MY turn to act (mirror-agnostic): homePlaying matches my side. */
function isMyTurn(g: GameJson): boolean {
  const mySideId = (myPlayTeam(g) as { teamId?: string } | undefined)?.teamId;
  const mySide = mySideId === (g.teamHome as { teamId?: string }).teamId ? 'home' : 'away';
  return !!(g as { homePlaying?: boolean }).homePlaying === (mySide === 'home');
}

/** Send player actions only for an owned player on our turn in player mode. */
function iControlPlayer(playerId: string): boolean {
  const g = game.value;
  if (!g || !play.active) return false;
  if (!myPlayIds(g).has(playerId)) return false; // not my player
  return isMyTurn(g);
}

/** Owner o66ak: does playerId carry CHAINSAW skill? (name-normalized: lowercase, alpha-only); used to default foul to usingChainsaw for chainsaw player—wire flag mirrors BlockKind flavor flags. */
function actorHasChainsaw(playerId: string): boolean {
  const g = game.value;
  if (!g) return false;
  const p = g.teamHome.playerArray.find((q) => q.playerId === playerId)
    ?? g.teamAway.playerArray.find((q) => q.playerId === playerId);
  return playerHasSkill(p, 'Chainsaw'); // base + TEMPORARY skills (shared protocol decoder)
}
// #41 exception (2026-07-16, Veers/Pellaeon): "Sneakiest of the Lot" ONLY skill granting NamedProperties.allowsAdditionalFoul—lets player make SECOND foul this turn (StepInitSelecting:220-221 accepts 2nd CLIENT_FOUL, StepInitFouling never sets foulUsed); present on Star Players in 2 fork rosters (tester-reachable)—once-per-turn latch must NOT deny legitimate 2nd foul; read wire skillArray (same as chainsaw).
function actorAllowsAdditionalFoul(playerId: string): boolean {
  const g = game.value;
  if (!g) return false;
  const p = g.teamHome.playerArray.find((q) => q.playerId === playerId)
    ?? g.teamAway.playerArray.find((q) => q.playerId === playerId);
  return playerHasSkill(p, 'Sneakiest of the Lot'); // base + TEMPORARY skills (shared protocol decoder)
}

/** My players currently standing on the pitch (x 0..25, y 0..14). */
function myOnFieldPlayers(g: GameJson) {
  const mine = myPlayIds(g);
  return (g.fieldModel?.playerDataArray ?? []).filter(
    (p) =>
      mine.has(p.playerId) && p.playerCoordinate &&
      p.playerCoordinate[0] >= 0 && p.playerCoordinate[0] <= 25 &&
      p.playerCoordinate[1] >= 0 && p.playerCoordinate[1] <= 14,
  );
}

/** M4.2: resolve mechanical Move/Block follow-up chain for THIS coach with safe defaults—take first offered block die, decline optional re-rolls/skills (e.g. Stand Firm), push into first legal square, don't follow up; server is authority—only answer prompts addressed to us (choosingTeam/dialog-player owner/acting player); bot opponent's obligatory decisions on OUR players answered same way; verified end-to-end against fork server via drivePregame --probe-block. */
const followupHandled = new Set<string>();
